10	 * Unless required by applicable law or agreed to in writing, software
11	 * distributed under the License is distributed on an "AS IS" BASIS,
12	 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
13	 * See the License for the specific language governing permissions and
14	 * limitations under the License.
15	 */
16	
17	/*
18	 * Doubao streaming ASR via WebSocket (V2 binary protocol).
19	 *
20	 * Protocol: wss://openspeech.bytedance.com/api/v2/asr
21	 * Flow:
22	 *   1. TLS connect + HTTP Upgrade to WebSocket
23	 *   2. Send full_client_request (JSON metadata) in Volcengine frame
24	 *   3. Send audio_only chunks (PCM), last chunk flagged
25	 *   4. Receive full_server_response, extract result text
26	 *
27	 * Volcengine binary frame (carried inside standard WebSocket frames):
28	 *   Byte 0: [protocol_version:4][header_size:4]  = 0x11
29	 *   Byte 1: [message_type:4][message_type_flags:4]
30	 *   Byte 2: [serialization:4][compression:4]
31	 *   Byte 3: reserved = 0x00
32	 *   Bytes 4-7: payload size (big-endian uint32)
33	 *   Bytes 8+: payload
34	 */
35	
36	#include "voice/volc_asr.h"
37	#include "infra/config_store.h"
38	#include "infra/http_proxy.h"
39	#include "agent_compat.h"
40	#include "agent_config.h"
41	#include "voice/voice_asr.h"
42	
43	#include "cJSON.h"
44	#include "mbedtls/base64.h"
45	#include "mbedtls/ctr_drbg.h"
46	#include "mbedtls/error.h"
47	#include "mbedtls/net_sockets.h"
48	#include "mbedtls/ssl.h"
49	#include "netutils/base64.h"
50	
51	#include <errno.h>
52	#include <fcntl.h>
53	#include <stdlib.h>
54	#include <string.h>
55	#include <sys/socket.h>
56	#include <time.h>
57	
58	static const char* TAG = "volc_asr";
59	
60	/* Volcengine binary protocol constants */
61	#define VOLC_PROTO_VER 0x11 /* version=1, header_size=1 (x4=4B) */
62	#define VOLC_MSG_FULL_REQ 0x10 /* full_client_request */
63	#define VOLC_MSG_AUDIO 0x20 /* audio_only, not last */
64	#define VOLC_MSG_AUDIO_LAST 0x22 /* audio_only, last chunk */
65	#define VOLC_MSG_FULL_RESP 0x90 /* full_server_response */
66	#define VOLC_MSG_ERROR 0xF0 /* server error */
67	#define VOLC_SER_JSON 0x10 /* JSON, no compression */
68	#define VOLC_SER_RAW 0x00 /* raw audio, no compression */
69	#define VOLC_HDR_SIZE 8 /* 4-byte header + 4-byte payload len */
70	
71	#define WS_BUF_SIZE 4096
72	#define WS_MASK_KEY_LEN 4
73	#define WS_OPCODE_BINARY 0x02
74	#define WS_OPCODE_CLOSE 0x08
75	#define WS_FIN_BIT 0x80
76	#define WS_MASK_BIT 0x80
77	
78	#define ASR_RESP_CODE_OK 1000
79	#define ASR_UUID_LEN 37 /* 36 chars + NUL */
80	
81	/* TLS context for ASR connection (not pooled — single use) */
82	typedef struct {
83	    mbedtls_ssl_context ssl;
84	    mbedtls_ssl_config cfg;
85	    mbedtls_net_context net;
86	    mbedtls_ctr_drbg_context ctr_drbg;
87	} asr_tls_ctx_t;
88	
89	/* ── Entropy source ──────────────────────────────────────────── */
90	
91	static int asr_entropy_func(void* data, unsigned char* output, size_t len)
92	{
93	    (void)data;
94	    if (agent_secure_random(output, len) == 0) {
95	        return 0;
96	    }
97	    syslog(LOG_ERR, "[volc_asr] CRITICAL: No secure entropy source available\n");
98	    return -1;  /* Generic error - TLS handshake will fail safely */
99	}
100	
101	/* ── TLS connect / free ──────────────────────────────────────── */
102	
103	static int asr_tls_connect(asr_tls_ctx_t* ctx,
104	    const char* host, const char* port)
105	{
106	    int ret;
107	
108	    mbedtls_ssl_init(&ctx->ssl);
109	    mbedtls_ssl_config_init(&ctx->cfg);
110	    mbedtls_net_init(&ctx->net);
111	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
112	
113	    const char* pers = "volc_asr";
114	
115	    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, asr_entropy_func,
116	        NULL, (const unsigned char*)pers,
117	        strlen(pers));
118	    if (ret != 0) {
119	        syslog(LOG_ERR, "[%s] ctr_drbg_seed: -0x%04x\n", TAG, -ret);
120	        return -EIO;
121	    }
122	
123	    /* If proxy is enabled, open a CONNECT tunnel first */
124	    if (http_proxy_is_enabled()) {
125	        int port_num = atoi(port);
126	        int tunnel_fd = proxy_open_tunnel(host, port_num, 30000);
127	
128	        if (tunnel_fd < 0) {
129	            syslog(LOG_ERR, "[%s] proxy tunnel failed\n", TAG);
130	            return -ECONNREFUSED;
131	        }
132	
133	        ctx->net.fd = tunnel_fd;
134	        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
135	            TAG, tunnel_fd, host, port);
136	    } else {
137	        ret = mbedtls_net_connect(&ctx->net, host, port,
138	            MBEDTLS_NET_PROTO_TCP);
139	        if (ret != 0) {
140	            syslog(LOG_ERR, "[%s] net_connect %s:%s: -0x%04x\n",
141	                TAG, host, port, -ret);
142	            return -ECONNREFUSED;
143	        }
144	    }
145	
146	    mbedtls_net_set_block(&ctx->net);
147	    if (ctx->net.fd >= 0) {
148	        struct timeval tv = { .tv_sec = 30, .tv_usec = 0 };
149	
150	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO,
151	            &tv, sizeof(tv));
152	    }
153	
154	    ret = mbedtls_ssl_config_defaults(&ctx->cfg,
155	        MBEDTLS_SSL_IS_CLIENT,
156	        MBEDTLS_SSL_TRANSPORT_STREAM,
157	        MBEDTLS_SSL_PRESET_DEFAULT);
158	    if (ret != 0) {
159	        return -EIO;
160	    }
161	
162	    mbedtls_ssl_conf_min_tls_version(&ctx->cfg,
163	        MBEDTLS_SSL_VERSION_TLS1_2);
164	#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
165	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg,
166	        MBEDTLS_SSL_VERSION_TLS1_3);
167	#else
168	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg,
169	        MBEDTLS_SSL_VERSION_TLS1_2);
170	#endif
171	
172	#if defined(MBEDTLS_SSL_ALPN)
173	    static const char* alpn[] = { "http/1.1", NULL };
174	
175	    mbedtls_ssl_conf_alpn_protocols(&ctx->cfg, alpn);
176	#endif
177	
178	    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
179	    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random,
180	        &ctx->ctr_drbg);
181	
182	    ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg);
183	    if (ret != 0) {
184	        return -EIO;
185	    }
186	
187	    mbedtls_ssl_set_hostname(&ctx->ssl, host);
188	    mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net,
189	        mbedtls_net_send, mbedtls_net_recv, NULL);
190	
191	    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
192	        if (ret != MBEDTLS_ERR_SSL_WANT_READ
193	            && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
194	            syslog(LOG_ERR, "[%s] handshake: -0x%04x\n", TAG, -ret);
195	            return -EIO;
196	        }
197	    }
198	
199	    syslog(LOG_INFO, "[%s] TLS connected to %s:%s\n", TAG, host, port);
200	    return 0;
201	}
