212	/* ── Low-level TLS I/O helpers ───────────────────────────────── */
213	
214	static int tls_write_all(asr_tls_ctx_t* ctx,
215	    const unsigned char* buf, size_t len)
216	{
217	    size_t written = 0;
218	
219	    while (written < len) {
220	        int ret = mbedtls_ssl_write(&ctx->ssl, buf + written,
221	            len - written);
222	
223	        if (ret > 0) {
224	            written += (size_t)ret;
225	        } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
226	            syslog(LOG_ERR, "[%s] ssl_write: -0x%04x\n", TAG, -ret);
227	            return -EIO;
228	        }
229	    }
230	    return 0;
231	}
232	
233	static int tls_read_all(asr_tls_ctx_t* ctx,
234	    unsigned char* buf, size_t len)
235	{
236	    size_t got = 0;
237	
238	    while (got < len) {
239	        int ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);
240	
241	        if (ret > 0) {
242	            got += (size_t)ret;
243	        } else if (ret == 0
244	            || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
245	            return -ECONNRESET;
246	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
247	            syslog(LOG_ERR, "[%s] ssl_read: -0x%04x\n", TAG, -ret);
248	            return -EIO;
249	        }
250	    }
251	    return 0;
252	}
