592	
593	/* ── Receive and parse Volcengine server response ────────────── */
594	
595	/* Read a big-endian uint32 from buf at offset off. */
596	static uint32_t read_be32(const unsigned char* buf, size_t off)
597	{
598	    return ((uint32_t)buf[off] << 24)
599	        | ((uint32_t)buf[off + 1] << 16)
600	        | ((uint32_t)buf[off + 2] << 8)
601	        | (uint32_t)buf[off + 3];
602	}
603	
604	/* Receive one WS frame, unwrap Volcengine header, parse JSON.
605	 * Extracts result[0].text into text_out.
606	 * Returns: 1 = got final result, 0 = intermediate, negative = error
607	 *
608	 * Volcengine binary protocol layout varies by message type:
609	 *
610	 *   Normal response (msg_type 0x9):
611	 *     [4B header] [4B payload_size] [payload...]
612	 *
613	 *   Error response (msg_type 0xF):
614	 *     [4B header] [4B error_code] [4B error_msg_size] [error_msg...]
615	 */
616	static int recv_volc_response(asr_tls_ctx_t* ctx,
617	    char* text_out, size_t text_cap)
618	{
619	    unsigned char* buf = malloc(WS_BUF_SIZE);
620	
621	    if (!buf) {
622	        return -ENOMEM;
623	    }
624	
625	    size_t flen;
626	    int opcode;
627	    int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);
628	
629	    if (ret != 0) {
630	        free(buf);
631	        return ret;
632	    }
633	
634	    if (opcode == WS_OPCODE_CLOSE) {
635	        syslog(LOG_WARNING, "[%s] Server sent WS close\n", TAG);
636	        free(buf);
637	        return -ECONNRESET;
638	    }
639	
640	    /* Need at least Volcengine header (4 bytes minimum) */
641	    if (flen < 4) {
642	        syslog(LOG_ERR, "[%s] Frame too short: %zu\n", TAG, flen);
643	        free(buf);
644	        return -EPROTO;
645	    }
646	
647	    /* Parse Volcengine header */
648	    int hdr_units = buf[0] & 0x0F;
649	    size_t volc_hdr_len = (size_t)hdr_units * 4;
650	    unsigned char msg_type_byte = buf[1];
651	    unsigned char msg_type_nibble = (msg_type_byte >> 4) & 0x0F;
652	
653	    if (volc_hdr_len < 4 || flen < volc_hdr_len) {
654	        syslog(LOG_ERR,
655	            "[%s] Bad volc header: hdr_units=%d flen=%zu\n",
656	            TAG, hdr_units, flen);
657	        free(buf);
658	        return -EPROTO;
659	    }
660	
661	    /* ── Error response: special layout with error_code field ── */
662	    if (msg_type_nibble == 0x0F) {
663	        /* [4B hdr][4B error_code][4B msg_size][msg...] */
664	        if (flen < volc_hdr_len + 8) {
665	            syslog(LOG_ERR,
666	                "[%s] Error frame too short: %zu\n",
667	                TAG, flen);
668	            free(buf);
669	            return -EPROTO;
670	        }
671	
672	        uint32_t err_code = read_be32(buf, volc_hdr_len);
673	        uint32_t msg_size = read_be32(buf, volc_hdr_len + 4);
674	        size_t msg_off = volc_hdr_len + 8;
675	
676	        if (msg_off + msg_size > flen) {
677	            msg_size = (uint32_t)(flen - msg_off);
678	        }
679	
680	        /* NUL-terminate and log the error message */
681	        char errbuf[256];
682	        size_t cplen = msg_size;
683	
684	        if (cplen >= sizeof(errbuf)) {
685	            cplen = sizeof(errbuf) - 1;
686	        }
687	        memcpy(errbuf, buf + msg_off, cplen);
688	        errbuf[cplen] = '\0';
689	
690	        syslog(LOG_ERR,
691	            "[%s] Server error %lu: %s\n",
692	            TAG, (unsigned long)err_code, errbuf);
693	        free(buf);
694	        return -EIO;
695	    }
696	
697	    /* ── Normal response: [4B hdr][4B payload_size][payload] ── */
698	    if (flen < volc_hdr_len + 4) {
699	        syslog(LOG_ERR,
700	            "[%s] Frame too short for payload size: %zu\n",
701	            TAG, flen);
702	        free(buf);
703	        return -EPROTO;
704	    }
705	
706	    uint32_t payload_len = read_be32(buf, volc_hdr_len);
707	    size_t data_off = volc_hdr_len + 4;
708	
709	    if (data_off + payload_len > flen) {
710	        syslog(LOG_ERR,
711	            "[%s] Payload overrun: off=%zu + plen=%lu "
712	            "> flen=%zu\n",
713	            TAG, data_off, (unsigned long)payload_len, flen);
714	        free(buf);
715	        return -EPROTO;
716	    }
717	
718	    /* We only care about full_server_response (0x9) */
719	    if (msg_type_nibble != 0x09) {
720	        free(buf);
721	        return 0; /* skip unknown message types */
722	    }
723	
724	    /* Parse JSON payload */
725	    buf[data_off + payload_len] = '\0';
726	    cJSON* root = cJSON_Parse((char*)(buf + data_off));
727	
728	    free(buf);
729	    buf = NULL;
730	
731	    if (!root) {
732	        syslog(LOG_ERR, "[%s] Bad JSON in response\n", TAG);
733	        return -EPROTO;
734	    }
735	
736	    cJSON* code_j = cJSON_GetObjectItem(root, "code");
737	    int code = code_j ? (int)code_j->valuedouble : -1;
738	
739	    if (code != ASR_RESP_CODE_OK) {
740	        cJSON* msg_j = cJSON_GetObjectItem(root, "message");
741	
742	        syslog(LOG_ERR, "[%s] ASR error %d: %s\n", TAG, code,
743	            (msg_j && msg_j->valuestring)
744	                ? msg_j->valuestring
745	                : "unknown");
746	        cJSON_Delete(root);
747	        return -EIO;
748	    }
749	
750	    /* Extract result[0].text.
751	     * Volcengine streaming ASR sends multiple responses per session.
752	     * We maintain a "confirmed" offset: text_out[0..confirmed_len-1]
753	     * holds final utterances that must not be overwritten.
754	     * Intermediate results (seq >= 0) overwrite only the portion
755	     * after confirmed_len.  Final results (seq < 0) append and
756	     * advance confirmed_len. */
757	    cJSON* result = cJSON_GetObjectItem(root, "result");
758	
759	    /* Negative sequence means final response */
760	    cJSON* seq_j = cJSON_GetObjectItem(root, "sequence");
761	    int seq = seq_j ? (int)seq_j->valuedouble : 0;
762	
763	    if (cJSON_IsArray(result) && cJSON_GetArraySize(result) > 0) {
764	        cJSON* first = cJSON_GetArrayItem(result, 0);
765	        cJSON* txt = cJSON_GetObjectItem(first, "text");
766	
767	        if (txt && cJSON_IsString(txt) && txt->valuestring
768	            && txt->valuestring[0] != '\0') {
769	            static size_t confirmed_len;
770	            if (text_out[0] == '\0') {
771	                confirmed_len = 0;
772	            }
773	
774	            if (seq < 0) {
775	                /* Final: write after confirmed, then advance */
776	                size_t remain = text_cap - confirmed_len - 1;
777	                if (remain > 0) {
778	                    strncpy(text_out + confirmed_len,
779	                        txt->valuestring, remain);
780	                    text_out[text_cap - 1] = '\0';
781	                }
782	                confirmed_len = strlen(text_out);
783	            } else {
784	                /* Intermediate: overwrite only after confirmed */
785	                size_t remain = text_cap - confirmed_len - 1;
786	                if (remain > 0) {
787	                    strncpy(text_out + confirmed_len,
788	                        txt->valuestring, remain);
789	                    text_out[text_cap - 1] = '\0';
790	                }
791	            }
792	        }
793	    }
794	
795	    cJSON_Delete(root);
796	
797	    return (seq < 0) ? 1 : 0;
798	}
799	
800	/* ── Credentials (self-loaded from config store) ─────────────── */
801	
802	static char s_app_id[128];
803	static char s_token[256];
804	static char s_cluster[128];
805	
806	static int volc_asr_init(void)
807	{
808	    memset(s_app_id, 0, sizeof(s_app_id));
809	    memset(s_token, 0, sizeof(s_token));
810	    memset(s_cluster, 0, sizeof(s_cluster));
811	
812	    claw_config_get(AGENT_CFG_KEY_VOLC_APPKEY,
813	        s_app_id, sizeof(s_app_id));
814	    claw_config_get(AGENT_CFG_KEY_VOLC_TOKEN,
815	        s_token, sizeof(s_token));
816	
817	    if (claw_config_get(AGENT_CFG_KEY_VOLC_ASR_CLUSTER,
818	            s_cluster, sizeof(s_cluster))
819	            != OK
820	        || s_cluster[0] == '\0') {
821	        strncpy(s_cluster, AGENT_DOUBAO_ASR_CLUSTER,
822	            sizeof(s_cluster) - 1);
823	    }
824	
825	    return 0;
826	}
827	
828	/* ── Public API (direct call, kept for backward compat) ──────── */
829	
830	int volc_asr_recognize(const unsigned char* pcm_data,
831	    size_t pcm_len,
832	    const char* app_id,
833	    const char* token,
834	    const char* cluster,
835	    char* text_out,
836	    size_t text_cap)
837	{
838	    if (!pcm_data || pcm_len == 0 || !app_id || !token
839	        || !cluster || !text_out || text_cap == 0) {
840	        return -EINVAL;
841	    }
842	
843	    text_out[0] = '\0';
844	
845	    struct timespec e2e_t0;
846	    clock_gettime(CLOCK_MONOTONIC, &e2e_t0);
847	
848	    asr_tls_ctx_t ctx;
849	    int ret;
850	
851	    /* 1. TLS connect */
852	    ret = asr_tls_connect(&ctx, AGENT_DOUBAO_ASR_HOST,
853	        AGENT_DOUBAO_ASR_PORT);
854	    if (ret != 0) {
855	        asr_tls_free(&ctx);
856	        return ret;
857	    }
858	
859	    /* 2. WebSocket upgrade */
860	    ret = ws_upgrade(&ctx, AGENT_DOUBAO_ASR_HOST,
861	        AGENT_DOUBAO_ASR_WS_PATH, token);
862	    if (ret != 0) {
863	        asr_tls_free(&ctx);
864	        return ret;
865	    }
866	
867	    /* 3. Send full_client_request (JSON metadata) */
868	    ret = send_full_client_request(&ctx, app_id, token, cluster);
869	    if (ret != 0) {
870	        asr_tls_free(&ctx);
871	        return ret;
872	    }
873	
874	    /* 4. Stream audio chunks */
875	    size_t offset = 0;
876	    size_t chunk_size = AGENT_ASR_CHUNK_SIZE;
877	
878	    while (offset < pcm_len) {
879	        size_t remain = pcm_len - offset;
880	        size_t clen = (remain < chunk_size) ? remain : chunk_size;
881	        int is_last = (offset + clen >= pcm_len) ? 1 : 0;
882	
883	        ret = send_audio_chunk(&ctx, pcm_data + offset, clen,
884	            is_last);
885	        if (ret != 0) {
886	            syslog(LOG_ERR, "[%s] send_audio_chunk failed: %d\n",
887	                TAG, ret);
888	            asr_tls_free(&ctx);
889	            return ret;
890	        }
891	        offset += clen;
892	    }
893	
894	    syslog(LOG_INFO, "[%s] Sent %zu bytes in %zu-byte chunks\n",
895	        TAG, pcm_len, chunk_size);
896	
897	    /* 5. Receive responses until final (sequence < 0) */
898	    struct timespec asr_t0;
899	    clock_gettime(CLOCK_MONOTONIC, &asr_t0);
900	
901	    int attempts = 0;
902	    int max_attempts = 100; /* safety limit */
903	
904	    while (attempts < max_attempts) {
905	        ret = recv_volc_response(&ctx, text_out, text_cap);
906	        if (ret < 0) {
907	            syslog(LOG_ERR, "[%s] recv error: %d\n", TAG, ret);
908	            asr_tls_free(&ctx);
909	            return ret;
910	        }
911	        if (ret == 1) {
912	            break; /* final response received */
913	        }
914	        attempts++;
915	    }
916	
917	    struct timespec asr_t1;
918	    clock_gettime(CLOCK_MONOTONIC, &asr_t1);
919	    long asr_ms = (asr_t1.tv_sec - asr_t0.tv_sec) * 1000
920	        + (asr_t1.tv_nsec - asr_t0.tv_nsec) / 1000000;
921	
922	    asr_tls_free(&ctx);
923	
924	    if (text_out[0] == '\0') {
925	        syslog(LOG_WARNING, "[%s] No text recognized (%ldms)\n",
926	            TAG, asr_ms);
927	        return -ENODATA;
928	    }
929	
930	    struct timespec e2e_t1;
931	    clock_gettime(CLOCK_MONOTONIC, &e2e_t1);
932	    long e2e_ms = (e2e_t1.tv_sec - e2e_t0.tv_sec) * 1000
933	        + (e2e_t1.tv_nsec - e2e_t0.tv_nsec) / 1000000;
934	
935	    syslog(LOG_INFO,
936	        "[%s] Recognized: %.80s (infer=%ldms e2e=%ldms)\n",
937	        TAG, text_out, asr_ms, e2e_ms);
938	    return 0;
939	}
940	
941	/* ── Streaming ASR API ────────────────────────────────────────── */
942	
943	struct volc_asr_stream {
944	    asr_tls_ctx_t tls;
945	    int ready; /* 1 after successful open */
946	};
947	
948	volc_asr_stream_t* volc_asr_stream_open(void)
949	{
950	    volc_asr_init();
951	
952	    if (s_app_id[0] == '\0' || s_token[0] == '\0') {
953	        syslog(LOG_ERR, "[%s] stream: credentials not configured\n",
954	            TAG);
955	        return NULL;
956	    }
957	
958	    volc_asr_stream_t* s = calloc(1, sizeof(*s));
959	
960	    if (!s) {
961	        return NULL;
962	    }
963	
964	    int ret = asr_tls_connect(&s->tls, AGENT_DOUBAO_ASR_HOST,
965	        AGENT_DOUBAO_ASR_PORT);
966	    if (ret != 0) {
967	        asr_tls_free(&s->tls);
968	        free(s);
969	        return NULL;
970	    }
971	
972	    ret = ws_upgrade(&s->tls, AGENT_DOUBAO_ASR_HOST,
973	        AGENT_DOUBAO_ASR_WS_PATH, s_token);
974	    if (ret != 0) {
975	        asr_tls_free(&s->tls);
976	        free(s);
977	        return NULL;
978	    }
979	
980	    ret = send_full_client_request(&s->tls, s_app_id, s_token,
981	        s_cluster);
982	    if (ret != 0) {
983	        asr_tls_free(&s->tls);
984	        free(s);
985	        return NULL;
986	    }
987	
988	    s->ready = 1;
989	    syslog(LOG_INFO, "[%s] stream: session opened\n", TAG);
990	    return s;
991	}
992	
993	int volc_asr_stream_send(volc_asr_stream_t* s,
994	    const unsigned char* pcm, size_t len)
995	{
996	    if (!s || !s->ready || !pcm || len == 0) {
997	        return -EINVAL;
998	    }
999	
1000	    return send_audio_chunk(&s->tls, pcm, len, 0);
1001	}
1002	
1003	int volc_asr_stream_finish(volc_asr_stream_t* s,
1004	    char* text_out, size_t text_cap)
1005	{
1006	    if (!s || !text_out || text_cap == 0) {
1007	        free(s);
1008	        return -EINVAL;
1009	    }
1010	
1011	    text_out[0] = '\0';
1012	
1013	    if (!s->ready) {
1014	        free(s);
1015	        return -EINVAL;
1016	    }
1017	
1018	    /* Send empty last-chunk to signal end of audio */
1019	    int ret = send_audio_chunk(&s->tls, (const unsigned char*)"",
1020	        0, 1);
1021	    if (ret != 0) {
1022	        syslog(LOG_ERR, "[%s] stream: send last chunk failed: %d\n",
1023	            TAG, ret);
1024	        asr_tls_free(&s->tls);
1025	        free(s);
1026	        return ret;
1027	    }
1028	
1029	    /* Receive responses until final */
1030	    int attempts = 0;
1031	
1032	    while (attempts < 100) {
1033	        ret = recv_volc_response(&s->tls, text_out, text_cap);
1034	        if (ret < 0) {
1035	            syslog(LOG_ERR, "[%s] stream: recv error: %d\n",
1036	                TAG, ret);
1037	            asr_tls_free(&s->tls);
1038	            free(s);
1039	            return ret;
1040	        }
1041	        if (ret == 1) {
1042	            break;
1043	        }
1044	        attempts++;
1045	    }
1046	
1047	    asr_tls_free(&s->tls);
1048	    free(s);
1049	
1050	    if (text_out[0] == '\0') {
1051	        syslog(LOG_WARNING, "[%s] stream: no text recognized\n",
1052	            TAG);
1053	        return -ENODATA;
1054	    }
1055	
1056	    syslog(LOG_INFO, "[%s] stream: recognized: %.80s\n",
1057	        TAG, text_out);
1058	    return 0;
1059	}
1060	
1061	void volc_asr_stream_abort(volc_asr_stream_t* s)
1062	{
1063	    if (!s) {
1064	        return;
1065	    }
1066	
1067	    if (s->ready) {
1068	        asr_tls_free(&s->tls);
1069	    }
1070	
1071	    free(s);
1072	    syslog(LOG_INFO, "[%s] stream: aborted\n", TAG);
1073	}
1074	
1075	/* ── Ops-based wrapper (simplified signature for framework) ──── */
1076	
1077	static int volc_asr_recognize_ops(const unsigned char* pcm_data,
1078	    size_t pcm_len,
1079	    char* text_out,
1080	    size_t text_cap)
1081	{
1082	    /* Reload credentials in case they changed at runtime */
1083	    volc_asr_init();
1084	
1085	    if (s_app_id[0] == '\0' || s_token[0] == '\0') {
1086	        syslog(LOG_ERR, "[%s] ASR credentials not configured\n", TAG);
1087	        return -ENOENT;
1088	    }
1089	
1090	    return volc_asr_recognize(pcm_data, pcm_len,
1091	        s_app_id, s_token, s_cluster,
1092	        text_out, text_cap);
1093	}
1094	
1095	/* Backend ops registration */
1096	static const voice_asr_ops_t s_volc_asr_ops = {
1097	    .name = "volcengine",
1098	    .init = volc_asr_init,
1099	    .recognize = volc_asr_recognize_ops,
1100	    .deinit = NULL,
1101	};
1102	
1103	int volc_asr_register(void)
1104	{
1105	    return voice_asr_register(&s_volc_asr_ops);
1106	}
