107	    *pcm_len = 0;
108	
109	    char* body = build_tts_request(text, s_speaker);
110	
111	    if (!body) {
112	        syslog(LOG_ERR, "[%s] Failed to build TTS request\n", TAG);
113	        return -ENOMEM;
114	    }
115	
116	    vela_header_t hdrs[] = {
117	        { "x-api-key", s_api_key },
118	        { "X-Api-Resource-Id", AGENT_DOUBAO_TTS_RESOURCE },
119	        { "Connection", "close" },
