153	        return -EPROTO;
154	    }
155	
156	    size_t total_pcm = 0;
157	    int chunks = 0;
158	    char* line = resp;
159	
160	    while (line && *line) {
161	        while (*line == '\n' || *line == '\r' || *line == ' ') {
162	            line++;
163	        }
164	
165	        if (*line == '\0') {
166	            break;
167	        }
168	
169	        char* eol = strchr(line, '\n');
