181	                syslog(LOG_WARNING,
182	                    "[%s] TTS: truncated chunk %d (buffer full), "
183	                    "using %zu bytes decoded so far\n",
184	                    TAG, chunks, total_pcm);
185	                break;
186	            }
187	            syslog(LOG_ERR, "[%s] TTS: bad JSON chunk %d: %.80s\n",
188	                TAG, chunks, line);
189	            break;
190	        }
191	
192	        cJSON* code_j = cJSON_GetObjectItem(obj, "code");
193	        int code_val = code_j ? (int)code_j->valuedouble : -1;
194	
195	        if (!code_j || !cJSON_IsNumber(code_j)
196	            || (code_val != 0 && code_val != 20000000)) {
197	            cJSON* msg_j = cJSON_GetObjectItem(obj, "message");
198	
199	            syslog(LOG_ERR, "[%s] TTS error %d: %.80s\n",
200	                TAG, code_val,
201	                (msg_j && msg_j->valuestring)
202	                    ? msg_j->valuestring
203	                    : line);
204	            cJSON_Delete(obj);
205	            free(resp);
206	            return -EIO;
207	        }
208	
209	        cJSON* data_j = cJSON_GetObjectItem(obj, "data");
210	
211	        if (data_j && cJSON_IsString(data_j)
212	            && data_j->valuestring[0]) {
213	            const char* b64 = data_j->valuestring;
214	            size_t b64_len = strlen(b64);
215	            size_t decoded_len;
216	
217	            if (total_pcm + (b64_len * 3 / 4) > pcm_cap) {
218	                syslog(LOG_ERR,
219	                    "[%s] TTS: PCM buffer full at chunk %d\n",
220	                    TAG, chunks);
221	                cJSON_Delete(obj);
222	                break;
223	            }
