225	            mbedtls_base64_decode(
226	                pcm_out + total_pcm, pcm_cap - total_pcm,
227	                &decoded_len,
228	                (const unsigned char*)b64, b64_len);
229	            total_pcm += decoded_len;
230	            chunks++;
231	        }
