282	        return -ENOMEM;
283	    }
284	
285	    vela_header_t hdrs[] = {
286	        { "x-api-key", s_api_key },
287	        { "X-Api-Resource-Id", AGENT_DOUBAO_TTS_RESOURCE },
288	        { "Connection", "close" },
289	        { NULL, NULL }
290	    };
291	
292	    char* resp = calloc(1, VOLC_TTS_STREAM_RESP_SIZE);
293	
294	    if (!resp) {
295	        free(body);
296	        return -ENOMEM;
297	    }
298	
299	    size_t body_len;
300	    int status = vela_https_request(
301	        AGENT_DOUBAO_TTS_HOST, AGENT_DOUBAO_TTS_PORT,
302	        "POST", AGENT_DOUBAO_TTS_V3_PATH, hdrs,
303	        body, strlen(body),
304	        resp, VOLC_TTS_STREAM_RESP_SIZE, &body_len);
305	
306	    free(body);
307	
308	    if (status != 200) {
309	        syslog(LOG_ERR, "[%s] stream: HTTP %d\n", TAG, status);
310	        free(resp);
311	        return -EIO;
312	    }
313	
314	    if (body_len == 0) {
315	        free(resp);
316	        return -EPROTO;
317	    }
318	
319	    /* Decode buffer for base64 chunks */
320	    unsigned char* pcm_tmp = malloc(VOLC_TTS_STREAM_B64_SIZE);
321	
322	    if (!pcm_tmp) {
323	        free(resp);
324	        return -ENOMEM;
325	    }
326	
327	    int chunks = 0;
328	    int err = 0;
329	    char* line = resp;
330	
331	    while (line && *line) {
332	        while (*line == '\n' || *line == '\r' || *line == ' ') {
333	            line++;
334	        }
335	
336	        if (*line == '\0') {
337	            break;
338	        }
339	
340	        char* eol = strchr(line, '\n');
341	
342	        if (eol) {
343	            *eol = '\0';
344	        }
345	
346	        cJSON* obj = cJSON_Parse(line);
347	
348	        if (!obj) {
349	            if (chunks > 0) {
350	                syslog(LOG_WARNING,
351	                    "[%s] stream: response truncated after "
352	                    "%d chunks (buffer full?)\n",
353	                    TAG, chunks);
354	                break;
355	            }
356	            syslog(LOG_ERR, "[%s] stream: bad JSON: %.80s\n",
357	                TAG, line);
358	            err = -EPROTO;
359	            break;
360	        }
361	
362	        cJSON* code_j = cJSON_GetObjectItem(obj, "code");
363	        int code_val = code_j ? (int)code_j->valuedouble : -1;
364	
365	        if (!code_j || !cJSON_IsNumber(code_j)
366	            || (code_val != 0 && code_val != 20000000)) {
367	            syslog(LOG_ERR, "[%s] stream: TTS error %d\n",
368	                TAG, code_val);
369	            cJSON_Delete(obj);
370	            err = -EIO;
371	            break;
372	        }
373	
374	        cJSON* data_j = cJSON_GetObjectItem(obj, "data");
375	
376	        if (data_j && cJSON_IsString(data_j)
377	            && data_j->valuestring[0]) {
378	            const char* b64 = data_j->valuestring;
379	            size_t b64_len = strlen(b64);
380	            size_t decoded_len;
381	
382	            mbedtls_base64_decode(
383	                pcm_tmp, VOLC_TTS_STREAM_B64_SIZE,
384	                &decoded_len,
385	                (const unsigned char*)b64, b64_len);
386	
387	            cb(pcm_tmp, decoded_len, 0, user_data);
388	            chunks++;
389	        }
390	
391	        cJSON_Delete(obj);
392	        line = eol ? eol + 1 : NULL;
393	    }
394	
395	    /* Send exactly one is_last=1 notification */
396	    if (chunks > 0 && err == 0) {
397	        cb(NULL, 0, 1, user_data);
398	    }
399	
400	    free(pcm_tmp);
401	    free(resp);
402	
403	    if (chunks == 0 && err == 0) {
404	        err = -EPROTO;
405	    }
406	
407	    syslog(LOG_INFO, "[%s] stream: %d chunks delivered\n",
408	        TAG, chunks);
409	    return err;
410	}
411	
412	/* Legacy API kept for backward compatibility */
413	int volc_tts_synthesize_compat(const char* text,
414	    const char* appid,
415	    const char* token,
416	    const char* speaker,
417	    unsigned char* pcm_out,
418	    size_t pcm_cap,
419	    size_t* pcm_len)
420	{
