422	    (void)speaker;
423	
424	    /* Temporarily override api_key if caller provides one */
425	    if (token && token[0] != '\0') {
426	        strncpy(s_api_key, token, sizeof(s_api_key) - 1);
427	        s_api_key[sizeof(s_api_key) - 1] = '\0';
428	    }
429	
430	    return volc_tts_synthesize(text, pcm_out, pcm_cap, pcm_len);
431	}
