51	#define TTS_WS_PATH "/api/v1/tts/ws_binary"
52	
53	/* Volcengine binary protocol constants */
54	#define VOLC_PROTO_VER 0x11
55	#define VOLC_HDR_SIZE 8
56	#define VOLC_MSG_FULL_REQ 0x10
57	#define VOLC_MSG_AUDIO_RESP 0xB0 /* audio_only server response */
58	#define VOLC_MSG_FRONTEND 0xC0 /* frontend server response */
59	#define VOLC_MSG_ERROR 0xF0
60	#define VOLC_SER_JSON 0x10
61	#define VOLC_SER_JSON_GZ 0x11 /* JSON + gzip */
62	#define VOLC_SER_RAW 0x00
63	
64	/* WebSocket constants */
65	#define WS_BUF_SIZE (32 * 1024)
66	#define WS_MASK_KEY_LEN 4
67	#define WS_OPCODE_BINARY 0x02
68	#define WS_OPCODE_CLOSE 0x08
69	#define WS_FIN_BIT 0x80
70	#define WS_MASK_BIT 0x80
