78	typedef struct {
79	    mbedtls_ssl_context ssl;
80	    mbedtls_ssl_config cfg;
81	    mbedtls_net_context net;
82	    mbedtls_ctr_drbg_context ctr_drbg;
83	} tts_tls_ctx_t;
84	
85	/* ── Entropy ─────────────────────────────────────────────────── */
86	
87	static int tts_entropy_func(void* data, unsigned char* output, size_t len)
88	{
89	    (void)data;
90	    if (agent_secure_random(output, len) == 0) {
91	        return 0;
92	    }
93	    syslog(LOG_ERR, "[volc_tts] CRITICAL: No secure entropy source available\n");
94	    return -1;  /* Generic error - TLS handshake will fail safely */
95	}
96	
97	/* ── TLS connect / free ──────────────────────────────────────── */
98	
99	static void tts_tls_free(tts_tls_ctx_t* ctx);
100	
101	static int tts_tls_connect(tts_tls_ctx_t* ctx, const char* host,
102	    const char* port)
103	{
104	    int ret;
105	
106	    mbedtls_ssl_init(&ctx->ssl);
107	    mbedtls_ssl_config_init(&ctx->cfg);
108	    mbedtls_net_init(&ctx->net);
109	    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);
110	
111	    ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, tts_entropy_func, NULL,
112	        (const unsigned char*)"volc_tts_ws", 11);
113	    if (ret != 0) {
114	        goto fail;
115	    }
116	
117	    if (http_proxy_is_enabled()) {
118	        int tunnel_fd = proxy_open_tunnel(host, atoi(port), 30000);
119	
120	        if (tunnel_fd < 0) {
121	            ret = -ECONNREFUSED;
122	            goto fail;
123	        }
124	
125	        ctx->net.fd = tunnel_fd;
126	    } else {
127	        ret = mbedtls_net_connect(&ctx->net, host, port, MBEDTLS_NET_PROTO_TCP);
128	        if (ret != 0) {
129	            ret = -ECONNREFUSED;
130	            goto fail;
131	        }
132	    }
133	
134	    mbedtls_net_set_block(&ctx->net);
135	
136	    if (ctx->net.fd >= 0) {
137	        struct timeval tv = { .tv_sec = 10, .tv_usec = 0 };
138	
139	        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
140	    }
141	
142	    ret = mbedtls_ssl_config_defaults(&ctx->cfg, MBEDTLS_SSL_IS_CLIENT,
143	        MBEDTLS_SSL_TRANSPORT_STREAM,
144	        MBEDTLS_SSL_PRESET_DEFAULT);
145	    if (ret != 0) {
146	        ret = -EIO;
147	        goto fail;
148	    }
149	
150	    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
151	#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
152	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_3);
153	#else
154	    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
155	#endif
156	
157	    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);
158	    mbedtls_ssl_conf_rng(&ctx->cfg, mbedtls_ctr_drbg_random, &ctx->ctr_drbg);
159	
160	    ret = mbedtls_ssl_setup(&ctx->ssl, &ctx->cfg);
161	    if (ret != 0) {
162	        ret = -EIO;
163	        goto fail;
164	    }
165	
166	    mbedtls_ssl_set_hostname(&ctx->ssl, host);
167	    mbedtls_ssl_set_bio(&ctx->ssl, &ctx->net, mbedtls_net_send, mbedtls_net_recv,
168	        NULL);
169	
170	    syslog(LOG_INFO, "[%s] Handshake start: %s:%s\n", TAG, host, port);
171	
172	    while ((ret = mbedtls_ssl_handshake(&ctx->ssl)) != 0) {
173	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
174	            syslog(LOG_ERR, "[%s] handshake: -0x%04x\n", TAG, -ret);
175	            ret = -EIO;
176	            goto fail;
177	        }
178	    }
179	
180	    syslog(LOG_INFO, "[%s] TLS connected\n", TAG);
181	    return 0;
182	
183	fail:
184	    tts_tls_free(ctx);
185	    return ret;
186	}
187	
188	static void tts_tls_free(tts_tls_ctx_t* ctx)
189	{
190	    mbedtls_ssl_close_notify(&ctx->ssl);
191	    mbedtls_net_free(&ctx->net);
192	    mbedtls_ssl_free(&ctx->ssl);
193	    mbedtls_ssl_config_free(&ctx->cfg);
194	    mbedtls_ctr_drbg_free(&ctx->ctr_drbg);
195	}
196	
197	/* ── TLS I/O helpers ─────────────────────────────────────────── */
198	
199	static int tls_write_all(tts_tls_ctx_t* ctx, const unsigned char* buf,
200	    size_t len)
201	{
202	    size_t written = 0;
203	
204	    while (written < len) {
205	        int ret = mbedtls_ssl_write(&ctx->ssl, buf + written, len - written);
206	
207	        if (ret > 0) {
208	            written += (size_t)ret;
209	        } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
210	            return -EIO;
211	        }
212	    }
213	
214	    return 0;
215	}
216	
217	static int tls_read_all(tts_tls_ctx_t* ctx, unsigned char* buf, size_t len)
218	{
219	    size_t got = 0;
220	
221	    while (got < len) {
222	        int ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);
223	
224	        if (ret > 0) {
225	            got += (size_t)ret;
226	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
227	            return -ECONNRESET;
228	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
229	            /* Distinguish SO_RCVTIMEO timeout from real I/O errors.
230	             * When the socket recv timeout fires, recv() returns -1
231	             * with errno EAGAIN/EWOULDBLOCK, and mbedtls maps that
232	             * to MBEDTLS_ERR_NET_RECV_FAILED (-0x004C).  Return a
233	             * distinct code so callers can treat timeout as normal
234	             * end-of-stream without masking real connection failures. */
235	            if (ret == -0x004C && (errno == EAGAIN || errno == EWOULDBLOCK
236	                                   || errno == ETIMEDOUT)) {
237	                return -ETIMEDOUT;
238	            }
239	            return -EIO;
240	        }
241	    }
242	
243	    return 0;
244	}
245	
246	/* ── WebSocket upgrade ───────────────────────────────────────── */
247	
248	static int ws_upgrade(tts_tls_ctx_t* ctx, const char* host, const char* path,
249	    const char* token)
250	{
251	    unsigned char key_raw[16];
252	    unsigned char key_b64[32];
253	    size_t key_b64_len;
254	
255	    tts_entropy_func(NULL, key_raw, sizeof(key_raw));
256	    mbedtls_base64_encode(key_b64, sizeof(key_b64), &key_b64_len, key_raw,
257	        sizeof(key_raw));
258	
259	    char req[768];
260	    int n = snprintf(req, sizeof(req),
261	        "GET %s HTTP/1.1\r\n"
262	        "Host: %s\r\n"
263	        "Upgrade: websocket\r\n"
264	        "Connection: Upgrade\r\n"
265	        "Sec-WebSocket-Key: REDACTED\r\n"
266	        "Sec-WebSocket-Version: 13\r\n"
267	        "Authorization: Bearer;%s\r\n"
268	        "\r\n",
269	        path, host, (int)key_b64_len, key_b64, token);
270	
271	    if (n <= 0 || n >= (int)sizeof(req)) {
272	        return -EOVERFLOW;
273	    }
274	
275	    int ret = tls_write_all(ctx, (const unsigned char*)req, (size_t)n);
276	
277	    if (ret != 0) {
278	        return ret;
279	    }
280	
281	    char resp[1024];
282	    size_t rlen = 0;
283	
284	    while (rlen < sizeof(resp) - 1) {
285	        int r = mbedtls_ssl_read(&ctx->ssl, (unsigned char*)resp + rlen,
286	            sizeof(resp) - 1 - rlen);
287	
288	        if (r > 0) {
289	            rlen += (size_t)r;
290	            resp[rlen] = '\0';
291	            if (strstr(resp, "\r\n\r\n")) {
292	                break;
293	            }
294	        } else if (r == 0 || r == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
295	            return -ECONNRESET;
296	        } else if (r != MBEDTLS_ERR_SSL_WANT_READ) {
297	            return -EIO;
298	        }
299	    }
300	
301	    int status = 0;
302	
303	    if (sscanf(resp, "HTTP/1.1 %d", &status) != 1 || status != 101) {
304	        syslog(LOG_ERR, "[%s] WS upgrade failed: HTTP %d\n", TAG, status);
305	        return -EPROTO;
306	    }
307	
308	    syslog(LOG_INFO, "[%s] WebSocket upgrade OK\n", TAG);
309	    return 0;
310	}
311	
312	/* ── WebSocket frame send (client must mask) ─────────────────── */
313	
314	static int ws_send_binary(tts_tls_ctx_t* ctx, const unsigned char* payload,
315	    size_t plen)
316	{
317	    unsigned char hdr[14];
318	    size_t hdr_len = 0;
319	
320	    hdr[0] = WS_FIN_BIT | WS_OPCODE_BINARY;
321	
322	    if (plen < 126) {
323	        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
324	        hdr_len = 2;
325	    } else if (plen <= 0xFFFF) {
326	        hdr[1] = WS_MASK_BIT | 126;
327	        hdr[2] = (unsigned char)(plen >> 8);
328	        hdr[3] = (unsigned char)(plen & 0xFF);
329	        hdr_len = 4;
330	    } else {
331	        hdr[1] = WS_MASK_BIT | 127;
332	        memset(hdr + 2, 0, 4);
333	        hdr[6] = (unsigned char)((plen >> 24) & 0xFF);
334	        hdr[7] = (unsigned char)((plen >> 16) & 0xFF);
335	        hdr[8] = (unsigned char)((plen >> 8) & 0xFF);
336	        hdr[9] = (unsigned char)(plen & 0xFF);
337	        hdr_len = 10;
338	    }
339	
340	    unsigned char mask[WS_MASK_KEY_LEN];
341	
342	    tts_entropy_func(NULL, mask, WS_MASK_KEY_LEN);
343	    memcpy(hdr + hdr_len, mask, WS_MASK_KEY_LEN);
344	    hdr_len += WS_MASK_KEY_LEN;
345	
346	    int ret = tls_write_all(ctx, hdr, hdr_len);
347	
348	    if (ret != 0) {
349	        return ret;
350	    }
351	
352	    unsigned char chunk[1024];
353	    size_t sent = 0;
354	
355	    while (sent < plen) {
356	        size_t clen = plen - sent;
357	
358	        if (clen > sizeof(chunk)) {
359	            clen = sizeof(chunk);
360	        }
361	
362	        for (size_t i = 0; i < clen; i++) {
363	            chunk[i] = payload[sent + i] ^ mask[(sent + i) % 4];
364	        }
365	
366	        ret = tls_write_all(ctx, chunk, clen);
367	        if (ret != 0) {
368	            return ret;
369	        }
370	
371	        sent += clen;
372	    }
373	
374	    return 0;
375	}
376	
377	/* ── WebSocket frame recv ────────────────────────────────────── */
378	
379	static int ws_recv_frame(tts_tls_ctx_t* ctx, unsigned char* buf, size_t cap,
380	    size_t* out_len, int* out_opcode)
381	{
382	    unsigned char hdr[2];
383	    int ret = tls_read_all(ctx, hdr, 2);
384	
385	    if (ret != 0) {
386	        return ret;
387	    }
388	
389	    *out_opcode = hdr[0] & 0x0F;
390	    int masked = (hdr[1] & WS_MASK_BIT) != 0;
391	    size_t plen = hdr[1] & 0x7F;
392	
393	    if (plen == 126) {
394	        unsigned char ext[2];
395	
396	        ret = tls_read_all(ctx, ext, 2);
397	        if (ret != 0) {
398	            return ret;
399	        }
400	
401	        plen = ((size_t)ext[0] << 8) | ext[1];
402	    } else if (plen == 127) {
403	        unsigned char ext[8];
404	
405	        ret = tls_read_all(ctx, ext, 8);
406	        if (ret != 0) {
407	            return ret;
408	        }
409	
410	        plen = ((size_t)ext[4] << 24) | ((size_t)ext[5] << 16) | ((size_t)ext[6] << 8) | ext[7];
411	    }
412	
413	    unsigned char mask_key[WS_MASK_KEY_LEN];
414	
415	    if (masked) {
416	        ret = tls_read_all(ctx, mask_key, WS_MASK_KEY_LEN);
417	        if (ret != 0) {
418	            return ret;
419	        }
420	    }
421	
422	    if (plen > cap) {
423	        syslog(LOG_ERR, "[%s] WS frame too large: %zu\n", TAG, plen);
424	        return -EOVERFLOW;
425	    }
426	
427	    if (plen > 0) {
428	        ret = tls_read_all(ctx, buf, plen);
429	        if (ret != 0) {
430	            return ret;
431	        }
432	
433	        if (masked) {
434	            for (size_t i = 0; i < plen; i++) {
435	                buf[i] ^= mask_key[i % 4];
436	            }
437	        }
438	    }
439	
440	    *out_len = plen;
441	    return 0;
442	}
443	
444	/* ── Volcengine frame send ───────────────────────────────────── */
445	
446	static int send_volc_frame(tts_tls_ctx_t* ctx, unsigned char msg_type,
447	    unsigned char serialization,
448	    const unsigned char* payload, size_t plen)
449	{
450	    unsigned char* frame = malloc(VOLC_HDR_SIZE + plen);
451	
452	    if (!frame) {
453	        return -ENOMEM;
454	    }
455	
456	    frame[0] = VOLC_PROTO_VER;
457	    frame[1] = msg_type;
458	    frame[2] = serialization;
459	    frame[3] = 0x00;
460	    frame[4] = (unsigned char)((plen >> 24) & 0xFF);
461	    frame[5] = (unsigned char)((plen >> 16) & 0xFF);
462	    frame[6] = (unsigned char)((plen >> 8) & 0xFF);
463	    frame[7] = (unsigned char)(plen & 0xFF);
464	
465	    if (plen > 0) {
466	        memcpy(frame + VOLC_HDR_SIZE, payload, plen);
467	    }
468	
469	    int ret = ws_send_binary(ctx, frame, VOLC_HDR_SIZE + plen);
470	
471	    free(frame);
472	    return ret;
473	}
474	
475	/* ── Build and send TTS full_client_request ──────────────────── */
476	
477	static int send_tts_request(tts_tls_ctx_t* ctx, const char* text)
478	{
479	    cJSON* root = cJSON_CreateObject();
480	
481	    if (!root) {
482	        return -ENOMEM;
483	    }
484	
485	    /* app */
486	    cJSON* app = cJSON_AddObjectToObject(root, "app");
487	
488	    cJSON_AddStringToObject(app, "appid", s_appid);
489	    cJSON_AddStringToObject(app, "token", s_token);
490	    cJSON_AddStringToObject(app, "cluster", s_cluster);
491	
492	    /* user */
493	    cJSON* user = cJSON_AddObjectToObject(root, "user");
494	
495	    cJSON_AddStringToObject(user, "uid", "agent");
496	
497	    /* audio */
498	    cJSON* audio = cJSON_AddObjectToObject(root, "audio");
499	
500	    cJSON_AddStringToObject(audio, "voice_type", s_speaker);
501	    cJSON_AddStringToObject(audio, "encoding", "pcm");
502	    cJSON_AddNumberToObject(audio, "sample_rate", AGENT_TTS_WS_SAMPLE_RATE);
503	    cJSON_AddNumberToObject(audio, "speed_ratio", 1.0);
504	
505	    /* request */
506	    cJSON* req = cJSON_AddObjectToObject(root, "request");
507	
508	    cJSON_AddStringToObject(req, "reqid", "agent-tts");
509	    cJSON_AddStringToObject(req, "text", text);
510	    cJSON_AddStringToObject(req, "text_type", "plain");
511	    cJSON_AddStringToObject(req, "operation", "submit");
512	
513	    char* json_str = cJSON_PrintUnformatted(root);
514	
515	    cJSON_Delete(root);
516	
517	    if (!json_str) {
518	        return -ENOMEM;
519	    }
520	
521	    syslog(LOG_INFO, "[%s] TTS request: text=%zu bytes\n", TAG, strlen(text));
522	
523	    int ret = send_volc_frame(ctx, VOLC_MSG_FULL_REQ, VOLC_SER_JSON,
524	        (const unsigned char*)json_str, strlen(json_str));
525	    free(json_str);
526	    return ret;
527	}
528	
529	/* ── Receive audio responses ─────────────────────────────────── */
530	
531	static int recv_tts_audio(tts_tls_ctx_t* ctx, volc_tts_chunk_cb cb,
532	    void* user_data)
533	{
534	    unsigned char* buf = malloc(WS_BUF_SIZE);
535	
536	    if (!buf) {
537	        return -ENOMEM;
538	    }
539	
540	    /* Recv timeout strategy:
541	     * - First chunk: keep the handshake timeout (10s) since TTS synthesis
542	     *   latency varies with text length and server load (200ms–2s typical).
543	     * - After first chunk: tighten to 500ms per recv.  To tolerate
544	     *   transient network stalls without silently truncating audio,
545	     *   allow up to 3 consecutive timeouts (~1.5s total) before
546	     *   declaring end-of-stream.  A single stall just retries.
547	     * The initial 10s timeout was set by tts_tls_connect(), so we only
548	     * need to tighten it after the first audio chunk arrives. */
549	
550	#define TTS_MAX_CONSECUTIVE_TIMEOUTS 3
551	
552	    int chunks = 0;
553	    int consecutive_timeouts = 0;
554	    int err = 0;
555	
556	    while (1) {
557	        size_t flen;
558	        int opcode;
559	        int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);
560	
561	        if (ret != 0) {
562	            /* Timeout after audio started: retry up to N times to
563	             * tolerate transient stalls.  Only declare EOF after
564	             * consecutive timeouts exceed the threshold (~1.5s). */
565	            if (chunks > 0 && ret == -ETIMEDOUT) {
566	                consecutive_timeouts++;
567	                if (consecutive_timeouts < TTS_MAX_CONSECUTIVE_TIMEOUTS) {
568	                    syslog(LOG_DEBUG,
569	                        "[%s] recv timeout %d/%d, retrying\n",
570	                        TAG, consecutive_timeouts,
571	                        TTS_MAX_CONSECUTIVE_TIMEOUTS);
572	                    continue;
573	                }
574	                syslog(LOG_INFO,
575	                    "[%s] recv ended after %d chunks "
576	                    "(%d consecutive timeouts)\n",
577	                    TAG, chunks, consecutive_timeouts);
578	                break;
579	            }
580	
581	            /* Peer close after audio started is normal EOF. */
582	            if (chunks > 0 && ret == -ECONNRESET) {
583	                syslog(LOG_INFO, "[%s] recv ended after %d chunks (rc=%d)\n",
584	                    TAG, chunks, ret);
585	                break;
586	            }
587	
588	            syslog(LOG_ERR, "[%s] recv error before any audio: %d\n", TAG, ret);
589	            err = ret;
590	            break;
591	        }
592	
593	        /* Any successful frame resets the timeout counter. */
594	        consecutive_timeouts = 0;
595	
596	        if (opcode == WS_OPCODE_CLOSE) {
597	            syslog(LOG_INFO, "[%s] server closed WS\n", TAG);
598	            break;
599	        }
600	
601	        if (flen < 4) {
602	            continue;
603	        }
604	
605	        unsigned char msg_type = buf[1] & 0xF0;
606	        unsigned char msg_flags = buf[1] & 0x0F;
607	        size_t volc_hdr_len = (size_t)(buf[0] & 0x0F) * 4;
608	
609	
610	        if (volc_hdr_len < 4 || flen < volc_hdr_len) {
611	            continue;
612	        }
613	
614	        /* Error response */
615	        if (msg_type == VOLC_MSG_ERROR) {
616	            uint32_t code = 0;
617	
618	            if (flen >= volc_hdr_len + 4) {
619	                code = ((uint32_t)buf[volc_hdr_len] << 24) | ((uint32_t)buf[volc_hdr_len + 1] << 16) | ((uint32_t)buf[volc_hdr_len + 2] << 8) | (uint32_t)buf[volc_hdr_len + 3];
620	            }
621	
622	            syslog(LOG_ERR, "[%s] server error: %lu\n", TAG, (unsigned long)code);
623	            err = -EIO;
624	            break;
625	        }
626	
627	        /* Frontend response (e.g. duration info) — signals end of audio
628	         * when it arrives after audio chunks have been received. */
629	        if (msg_type == VOLC_MSG_FRONTEND) {
630	            if (chunks > 0) {
631	                break; /* All audio delivered, frontend is the epilogue */
632	            }
633	            continue;
634	        }
635	
636	        /* Audio-only response (0xB) */
637	        if (msg_type == VOLC_MSG_AUDIO_RESP) {
638	            /* flags: 0=ack(no audio), 1+=has audio data */
639	            if (msg_flags == 0) {
640	                continue; /* ACK, no audio data */
641	            }
642	
643	            /* After volc header: 4-byte sequence (signed) + 4-byte payload_size */
644	            size_t audio_off = volc_hdr_len + 8;
645	
646	            if (flen <= audio_off) {
647	                continue;
648	            }
649	
650	            /* Extract sequence as signed 32-bit (big-endian).
651	             * Per Volcengine binary protocol: sequence < 0 means last frame. */
652	            int32_t seq = (int32_t)(
653	                ((uint32_t)buf[volc_hdr_len] << 24) |
654	                ((uint32_t)buf[volc_hdr_len + 1] << 16) |
655	                ((uint32_t)buf[volc_hdr_len + 2] << 8) |
656	                (uint32_t)buf[volc_hdr_len + 3]);
657	
658	            unsigned char* pcm = buf + audio_off;
659	            size_t pcm_len = flen - audio_off;
660	
661	            cb(pcm, pcm_len, 0, user_data);
662	            chunks++;
663	
664	            /* After first chunk, tighten recv timeout so we detect
665	             * end-of-stream quickly (server may not send close frame). */
666	            if (chunks == 1 && ctx->net.fd >= 0) {
667	                struct timeval tv = { .tv_sec = 0, .tv_usec = 500000 };
668	                if (setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO,
669	                        &tv, sizeof(tv)) < 0) {
670	                    syslog(LOG_WARNING,
671	                        "[%s] setsockopt SO_RCVTIMEO failed: %d\n",
672	                        TAG, errno);
673	                }
674	            }
675	
676	            /* sequence < 0 = last audio frame */
677	            if (seq < 0) {
678	                break;
679	            }
680	        }
681	    }
682	
683	    free(buf);
684	
685	    if (chunks > 0 && err == 0) {
686	        cb(NULL, 0, 1, user_data);
687	    }
688	
689	    syslog(LOG_INFO, "[%s] %d audio chunks delivered\n", TAG, chunks);
690	
691	    if (chunks == 0 && err == 0) {
692	        return -EPROTO;
693	    }
694	
695	    return err;
696	}
697	
698	/* ── Init credentials ────────────────────────────────────────── */
699	
700	static void tts_ws_init(void)
701	{
702	    memset(s_appid, 0, sizeof(s_appid));
703	    memset(s_token, 0, sizeof(s_token));
704	    memset(s_cluster, 0, sizeof(s_cluster));
705	    memset(s_speaker, 0, sizeof(s_speaker));
706	
707	    claw_config_get(AGENT_CFG_KEY_VOLC_APPKEY, s_appid, sizeof(s_appid));
708	    claw_config_get(AGENT_CFG_KEY_VOLC_TOKEN, s_token, sizeof(s_token));
709	
710	    if (claw_config_get(AGENT_CFG_KEY_VOLC_CLUSTER, s_cluster,
711	            sizeof(s_cluster))
712	            != OK
713	        || s_cluster[0] == '\0') {
714	        strncpy(s_cluster, AGENT_VOICE_DEFAULT_CLUSTER, sizeof(s_cluster) - 1);
715	    }
716	
717	    if (claw_config_get(AGENT_CFG_KEY_VOLC_SPEAKER, s_speaker,
718	            sizeof(s_speaker))
719	            != OK
720	        || s_speaker[0] == '\0') {
721	        strncpy(s_speaker, AGENT_VOICE_DEFAULT_SPEAKER, sizeof(s_speaker) - 1);
722	    }
723	}
724	
725	/* ── Public API ──────────────────────────────────────────────── */
726	
727	int volc_tts_ws_synthesize_stream(const char* text, volc_tts_chunk_cb cb,
728	    void* user_data)
729	{
730	    if (!text || !cb) {
731	        return -EINVAL;
732	    }
733	
734	    tts_ws_init();
735	
736	    if (s_appid[0] == '\0' || s_token[0] == '\0') {
737	        syslog(LOG_ERR, "[%s] credentials not configured\n", TAG);
738	        return -ENOENT;
739	    }
740	
741	    tts_tls_ctx_t ctx;
742	    int ret = tts_tls_connect(&ctx, AGENT_DOUBAO_TTS_HOST, AGENT_DOUBAO_TTS_PORT);
743	
744	    if (ret != 0) {
745	        tts_tls_free(&ctx);
746	        return ret;
747	    }
748	
749	    ret = ws_upgrade(&ctx, AGENT_DOUBAO_TTS_HOST, TTS_WS_PATH, s_token);
750	    if (ret != 0) {
751	        tts_tls_free(&ctx);
752	        return ret;
753	    }
754	
755	    ret = send_tts_request(&ctx, text);
756	    if (ret != 0) {
757	        tts_tls_free(&ctx);
758	        return ret;
759	    }
760	
761	    ret = recv_tts_audio(&ctx, cb, user_data);
762	
763	    tts_tls_free(&ctx);
764	    return ret;
765	}
