268	        int32_t mixed = 0;
269	
270	        for (unsigned int ch = 0; ch < cap->hw_channels; ch++) {
271	            mixed += in[i * cap->hw_channels + ch];
272	        }
273	
274	        out[i] = (int16_t)(mixed / (int32_t)cap->hw_channels);
275	    }
