315	        cap->backend = AUDIO_CAPTURE_BACKEND_ALSA;
316	        cap->handle.pcm = pcm;
317	        cap->bits_per_sample = bits_per_sample;
318	        cap->requested_channels = channels;
319	        cap->hw_channels = hw_channels;
320	        cap->out_frame_bytes = (bits_per_sample / 8) * channels;
321	        cap->hw_frame_bytes = snd_vela_pcm_frames_to_bytes(pcm, 1);
322	
323	        syslog(LOG_INFO,
324	            "[%s] opened direct ALSA capture (%s, %uHz, req=%uch, hw=%uch, %ubit)\n",
325	            TAG, alsa_name, sample_rate, channels, hw_channels,
326	            bits_per_sample);
327	        return 0;
328	    }
329	
330	    return last_ret;
331	}
332	
333	#endif /* CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT */
334	
335	static int open_media_recorder_capture(audio_capture_t* cap,
336	    unsigned int sample_rate, unsigned int channels,
337	    unsigned int bits_per_sample)
338	{
339	    char opts[CAP_OPTIONS_LEN];
340	    int ret;
341	
342	    cap->handle.recorder = media_recorder_open(MEDIA_SOURCE_MIC);
343	    if (!cap->handle.recorder) {
344	        syslog(LOG_ERR, "[%s] media_recorder_open failed, errno=%d\n",
345	            TAG, errno);
346	        return -errno;
347	    }
348	
349	    snprintf(opts, sizeof(opts),
350	        "format=s%ule:sample_rate=%u:ch_layout=%s",
351	        bits_per_sample, sample_rate,
352	        (channels == 1) ? "mono" : "stereo");
353	
354	    ret = media_recorder_prepare(cap->handle.recorder, NULL, opts);
355	    if (ret < 0) {
356	        syslog(LOG_ERR, "[%s] prepare failed: %d\n", TAG, ret);
357	        media_recorder_close(cap->handle.recorder);
358	        cap->handle.recorder = NULL;
359	        return ret;
360	    }
361	
362	    cap->backend = AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER;
363	    cap->bits_per_sample = bits_per_sample;
364	    cap->requested_channels = channels;
365	    cap->hw_channels = channels;
366	    cap->out_frame_bytes = (bits_per_sample / 8) * channels;
367	    cap->hw_frame_bytes = cap->out_frame_bytes;
368	
369	    syslog(LOG_INFO, "[%s] opened media recorder (%uHz %uch %ubit)\n",
370	        TAG, sample_rate, channels, bits_per_sample);
371	    return 0;
372	}
373	
374	audio_capture_t* audio_capture_open(const char* dev_path,
375	    unsigned int sample_rate, unsigned int channels,
376	    unsigned int bits_per_sample)
377	{
378	    if (s_active_capture) {
379	        syslog(LOG_WARNING, "[%s] force closing stale capture\n", TAG);
380	        audio_capture_close(s_active_capture);
381	        usleep(100000);
382	    }
383	
384	    audio_capture_t* cap = calloc(1, sizeof(*cap));
385	    if (!cap) {
386	        return NULL;
387	    }
388	
389	    int ret = -ENOTSUP;
390	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
391	    ret = open_alsa_capture(cap, dev_path, sample_rate, channels,
392	        bits_per_sample);
393	    if (ret < 0) {
394	        syslog(LOG_WARNING,
395	            "[%s] direct ALSA capture unavailable (%d), falling back to media recorder\n",
396	            TAG, ret);
397	    }
398	#else
399	    (void)dev_path;
400	#endif
401	
402	    if (ret < 0) {
403	        ret = open_media_recorder_capture(cap, sample_rate, channels,
404	            bits_per_sample);
405	        if (ret < 0) {
406	            free(cap);
407	            return NULL;
408	        }
409	    }
410	
411	    s_active_capture = cap;
412	    return cap;
413	}
414	
415	int audio_capture_start(audio_capture_t* cap)
416	{
417	    if (!cap) {
418	        return -EINVAL;
419	    }
420	
421	    switch (cap->backend) {
422	    case AUDIO_CAPTURE_BACKEND_ALSA:
423	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
424	        if (!cap->handle.pcm) {
425	            return -EINVAL;
426	        }
427	
428	        if (cap->started) {
429	            return 0;
430	        }
431	
432	        if (snd_vela_pcm_prepare(cap->handle.pcm) < 0) {
433	            syslog(LOG_ERR, "[%s] ALSA prepare failed\n", TAG);
434	            return -EIO;
435	        }
436	
437	        cap->started = 1;
438	        syslog(LOG_INFO, "[%s] ALSA capture prepared\n", TAG);
439	        return 0;
440	#else
441	        return -ENOTSUP;
442	#endif
443	
444	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER: {
445	        int ret;
446	
447	        if (!cap->handle.recorder) {
448	            return -EINVAL;
449	        }
450	
451	        ret = media_recorder_start(cap->handle.recorder);
452	        if (ret < 0) {
453	            syslog(LOG_ERR, "[%s] start failed: %d\n", TAG, ret);
454	            return ret;
455	        }
456	
457	        syslog(LOG_INFO, "[%s] media recorder capture started\n", TAG);
458	        return 0;
459	    }
460	
461	    default:
462	        return -EINVAL;
463	    }
464	}
465	
466	int audio_capture_read(audio_capture_t* cap, void* buf, size_t len)
467	{
468	    if (!cap || !buf || len == 0) {
469	        return -EINVAL;
470	    }
471	
472	    switch (cap->backend) {
473	    case AUDIO_CAPTURE_BACKEND_ALSA: {
474	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
475	        snd_pcm_uframes_t frames;
476	        int nframes;
477	        size_t out_len;
478	
479	        if (!cap->handle.pcm || cap->out_frame_bytes == 0) {
480	            return -EINVAL;
481	        }
482	
483	        frames = len / cap->out_frame_bytes;
484	        if (frames == 0) {
485	            return -EINVAL;
486	        }
487	
488	        if (cap->hw_channels == cap->requested_channels) {
489	            nframes = alsa_read_frames(cap, buf, frames);
490	            if (nframes <= 0) {
491	                return nframes;
492	            }
493	
494	            out_len = (size_t)nframes * cap->out_frame_bytes;
495	            if (cap->bits_per_sample == 16) {
496	                apply_capture_gain(buf, out_len);
497	            }
498	            return (int)out_len;
499	        }
500	
501	        if (cap->bits_per_sample != 16 || cap->requested_channels != 1) {
502	            return -ENOTSUP;
503	        }
504	
505	        if (ensure_scratch_capacity(cap, frames * cap->hw_frame_bytes) < 0) {
506	            return -ENOMEM;
507	        }
508	
509	        nframes = alsa_read_frames(cap, cap->scratch, frames);
510	        if (nframes <= 0) {
511	            return nframes;
512	        }
513	
514	        downmix_interleaved_s16_to_mono(cap, buf, cap->scratch,
515	            (size_t)nframes);
516	        out_len = (size_t)nframes * cap->out_frame_bytes;
517	        apply_capture_gain(buf, out_len);
518	        return (int)out_len;
519	#else
520	        return -ENOTSUP;
521	#endif
522	    }
523	
524	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER: {
525	        ssize_t n;
526	
527	        if (!cap->handle.recorder) {
528	            return -EINVAL;
529	        }
530	
531	        n = media_recorder_read_data(cap->handle.recorder, buf, len);
532	        if (n > 0 && cap->bits_per_sample == 16) {
533	            apply_capture_gain(buf, (size_t)n);
534	        }
535	
536	        return (int)n;
537	    }
538	
539	    default:
540	        return -EINVAL;
541	    }
542	}
543	
544	int audio_capture_abort(audio_capture_t* cap)
545	{
546	    if (!cap) {
547	        return -EINVAL;
548	    }
549	
550	    switch (cap->backend) {
551	    case AUDIO_CAPTURE_BACKEND_ALSA:
552	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
553	        if (cap->handle.pcm && cap->started) {
554	            int ret = snd_vela_pcm_drop(cap->handle.pcm);
555	            cap->started = 0;
556	            return ret;
557	        }
558	        return 0;
559	#else
560	        return -ENOTSUP;
561	#endif
562	
563	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER:
564	        if (cap->handle.recorder) {
565	#ifdef CONFIG_MEDIA_GRAPH
566	            media_recorder_close_socket(cap->handle.recorder);
567	#endif
568	            return media_recorder_stop(cap->handle.recorder);
569	        }
570	        return 0;
571	
572	    default:
573	        return -EINVAL;
574	    }
575	}
576	
577	void audio_capture_close(audio_capture_t* cap)
578	{
579	    if (!cap) {
580	        return;
581	    }
582	
583	    switch (cap->backend) {
584	    case AUDIO_CAPTURE_BACKEND_ALSA:
585	#ifdef CONFIG_AI_AGENT_AUDIO_ALSA_DIRECT
586	        if (cap->handle.pcm) {
587	            if (cap->started) {
588	                snd_vela_pcm_drop(cap->handle.pcm);
589	            }
590	            snd_vela_pcm_close(cap->handle.pcm);
591	            cap->handle.pcm = NULL;
592	        }
593	        free(cap->scratch);
594	        cap->scratch = NULL;
595	        cap->scratch_size = 0;
596	#endif
597	        break;
598	
599	    case AUDIO_CAPTURE_BACKEND_MEDIA_RECORDER:
600	        if (cap->handle.recorder) {
601	            media_recorder_stop(cap->handle.recorder);
602	            usleep(50 * 1000);
603	            media_recorder_close(cap->handle.recorder);
604	            cap->handle.recorder = NULL;
605	        }
606	        break;
607	
608	    default:
609	        break;
610	    }
611	
612	    if (s_active_capture == cap) {
613	        s_active_capture = NULL;
614	    }
615	
616	    free(cap);
617	    syslog(LOG_INFO, "[%s] closed\n", TAG);
618	}
