121	        PREPROC_FRAME_SIZE, 0, &s_ns_cfg);
122	    pp->agc = compexp_create(AGENT_VOICE_SAMPLE_RATE,
123	        PREPROC_FRAME_SIZE, &s_agc_cfg);
