134	        return;
135	    }
136	    if (pp->agc) {
137	        compexp_destroy(pp->agc);
138	    }
139	    if (pp->ns) {
140	        ec2float_destroy(pp->ns);
141	    }
142	    free(pp->heap);
143	    free(pp);
