226	/* ── File-based helpers (kept for QEMU test commands) ──── */
227	
228	static int read_pcm_file(const char* path,
229	    unsigned char** out, size_t* out_len)
230	{
231	    int fd = open(path, O_RDONLY);
232	
233	    if (fd < 0) {
234	        syslog(LOG_ERR, "[%s] Cannot open %s: %d\n",
235	            TAG, path, errno);
236	        return -errno;
237	    }
238	
239	    off_t fsize = lseek(fd, 0, SEEK_END);
240	
241	    if (fsize <= 0 || (size_t)fsize > AGENT_VOICE_PCM_BUF_SIZE) {
242	        syslog(LOG_ERR, "[%s] File too large or empty: %ld\n",
243	            TAG, (long)fsize);
244	        close(fd);
245	        return -EFBIG;
246	    }
247	
248	    lseek(fd, 0, SEEK_SET);
249	
250	    unsigned char* buf = malloc((size_t)fsize);
251	
252	    if (!buf) {
253	        close(fd);
254	        return -ENOMEM;
255	    }
256	
257	    ssize_t nread = read(fd, buf, (size_t)fsize);
258	
259	    close(fd);
260	
261	    if (nread != (ssize_t)fsize) {
262	        free(buf);
263	        return -EIO;
264	    }
265	
266	    *out = buf;
267	    *out_len = (size_t)fsize;
268	    return 0;
269	}
270	
271	static int write_pcm_file(const char* path,
272	    const unsigned char* data, size_t len)
273	{
274	    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
275	
276	    if (fd < 0) {
277	        syslog(LOG_ERR, "[%s] Cannot create %s: %d\n",
278	            TAG, path, errno);
279	        return -errno;
280	    }
281	
282	    ssize_t nw = write(fd, data, len);
283	
284	    close(fd);
285	    return (nw == (ssize_t)len) ? 0 : -EIO;
286	}
287	
288	/* ── Recording cleanup helper ────────────────────────────── */
289	
290	static void recording_cleanup_locked(voice_asr_stream_t* stream)
291	{
292	    /* Abort streaming ASR if active */
293	    if (stream) {
294	        voice_asr_stream_abort(stream);
295	        s_voice.asr_stream = NULL;
296	    }
297	
298	    /* Close capture device */
299	    if (s_voice.cap) {
300	        audio_capture_close(s_voice.cap);
301	        s_voice.cap = NULL;
302	    }
303	
304	    /* Free PCM buffer */
305	    free(s_voice.pcm_buf);
306	    s_voice.pcm_buf = NULL;
307	    s_voice.pcm_len = 0;
308	
309	    /* Reset state to IDLE */
310	    s_voice.state = VOICE_IDLE;
311	}
312	
313	/* Allocate fallback PCM buffer (must hold lock) */
314	static int alloc_fallback_buffer_locked(void)
315	{
316	    if (s_voice.pcm_buf) {
317	        return 0;
318	    }
319	
320	    s_voice.pcm_buf = malloc(s_voice.pcm_cap);
321	    if (!s_voice.pcm_buf) {
322	        syslog(LOG_ERR, "[%s] fallback buffer alloc failed\n", TAG);
323	        return -ENOMEM;
324	    }
325	
326	    s_voice.pcm_len = 0;
327	    return 0;
328	}
329	
330	/* Accumulate PCM chunk to fallback buffer (must hold lock) */
331	static void accumulate_pcm_locked(const unsigned char* chunk, size_t len)
332	{
333	    if (s_voice.pcm_buf && s_voice.pcm_len + len <= s_voice.pcm_cap) {
334	        memcpy(s_voice.pcm_buf + s_voice.pcm_len, chunk, len);
335	        s_voice.pcm_len += len;
336	    }
337	}
338	
339	/* Process one audio chunk: send to ASR or accumulate for fallback */
340	static int process_audio_chunk(voice_asr_stream_t** stream_ptr,
341	    const unsigned char* chunk, size_t len, int* need_fallback,
342	    size_t* bytes_sent)
343	{
344	    if (*need_fallback) {
345	        pthread_mutex_lock(&s_voice.lock);
346	        accumulate_pcm_locked(chunk, len);
347	        pthread_mutex_unlock(&s_voice.lock);
348	    }
349	
350	    if (*stream_ptr) {
351	        int ret = voice_asr_stream_send(*stream_ptr, chunk, len);
352	
353	        if (ret != 0) {
354	            syslog(LOG_ERR,
355	                "[%s] stream send failed: %d, batch fallback\n", TAG, ret);
356	            voice_asr_stream_abort(*stream_ptr);
357	            *stream_ptr = NULL;
358	            *need_fallback = 1;
359	
360	            pthread_mutex_lock(&s_voice.lock);
361	            alloc_fallback_buffer_locked();
362	            pthread_mutex_unlock(&s_voice.lock);
363	        } else {
364	            *bytes_sent += len;
365	        }
366	    }
367	
368	    return 0;
369	}
370	
371	/* ── Recording thread (PTT mode — streaming ASR) ─────────── */
372	
373	static void* recording_thread(void* arg)
374	{
375	    (void)arg;
376	    unsigned char chunk[AGENT_ASR_CHUNK_SIZE];
377	    int need_fallback = 0;
378	    // int dump_fd = -1;
379	    size_t total_bytes_read = 0;
380	    size_t total_bytes_sent = 0;
381	    int chunk_count = 0;
382	    int abnormal_exit = 0;
383	
384	    syslog(LOG_INFO, "[%s] recording thread started (streaming)\n", TAG);
385	
386	    /* Use pre-connected ASR stream if available (opened in
387	     * voice_channel_start to avoid TLS handshake delay during
388	     * recording).  Fall back to opening a new session if not. */
389	    pthread_mutex_lock(&s_voice.lock);
390	    voice_asr_stream_t* stream = s_voice.asr_stream;
391	    s_voice.asr_stream = NULL; /* thread now owns it */
392	    pthread_mutex_unlock(&s_voice.lock);
393	
394	    if (!stream) {
395	        /* No pre-connected stream — open now (may lose first 300-800ms) */
396	        stream = voice_asr_stream_open();
397	        syslog(LOG_WARNING,
398	            "[%s] streaming ASR unavailable, batch fallback\n", TAG);
399	        need_fallback = 1;
400	
401	        pthread_mutex_lock(&s_voice.lock);
402	        if (alloc_fallback_buffer_locked() != 0) {
403	            s_voice.state = VOICE_IDLE;
404	            pthread_mutex_unlock(&s_voice.lock);
405	            sem_post(&s_voice.rec_ready);
406	            return NULL;
407	        }
408	        pthread_mutex_unlock(&s_voice.lock);
409	    } else {
410	        syslog(LOG_INFO, "[%s] using pre-connected ASR stream\n", TAG);
411	    }
412	
413	    /* Signal voice_channel_start() that we are ready to consume
414	     * audio frames. Without this, sem_wait in start() deadlocks. */
415	    sem_post(&s_voice.rec_ready);
416	
417	    /* No flush needed: the new start sequence guarantees that
418	     * audio_capture_start() runs AFTER this thread is ready,
419	     * so there is no stale data in the queue. The old flush
420	     * was harmful — audio_capture_read() blocks, so it would
421	     * consume real audio frames instead of stale ones. */
422	
423	    while (1) {
424	        pthread_mutex_lock(&s_voice.lock);
425	        enum voice_state st = s_voice.state;
426	        pthread_mutex_unlock(&s_voice.lock);
427	
428	        if (st != VOICE_RECORDING) {
429	            break;
430	        }
431	
432	        int n = audio_capture_read(s_voice.cap,
433	            chunk, sizeof(chunk));
434	
435	        if (n == -EAGAIN || n == -EWOULDBLOCK) {
436	            /* Non-blocking capture socket has no data yet (common right
437	             * after start before the first frames arrive). Retry instead
438	             * of treating it as a fatal error. */
439	            usleep(10000);
440	            continue;
441	        }
442	
443	        if (n <= 0) {
444	            syslog(LOG_WARNING,
445	                "[%s] capture read returned %d, stopping\n", TAG, n);
446	            abnormal_exit = 1;
447	            break;
448	        }
449	
450	        total_bytes_read += (size_t)n;
451	        chunk_count++;
452	
453	        /* Dump raw PCM to file */
454	        // if (dump_fd >= 0) {
455	        //     write(dump_fd, chunk, (size_t)n);
456	        // }
457	
458	        /* Log audio level for first few chunks and periodically
459	         * to diagnose silence vs actual speech from QEMU mic. */
460	        if (chunk_count <= 3 || chunk_count % 50 == 0) {
461	            int16_t* samples = (int16_t*)chunk;
462	            int sample_count = n / 2;
463	            int32_t peak = 0;
464	
465	            for (int i = 0; i < sample_count; i++) {
466	                int32_t v = samples[i] < 0 ? -samples[i] : samples[i];
467	                if (v > peak) {
468	                    peak = v;
469	                }
470	            }
471	            syslog(LOG_INFO,
472	                "[%s] chunk#%d: %d bytes, peak=%ld\n",
473	                TAG, chunk_count, n, (long)peak);
474	        }
475	
476	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
477	        preproc_chunk(pp, chunk, n);
478	#endif
479	
480	        process_audio_chunk(&stream, chunk, (size_t)n,
481	            &need_fallback, &total_bytes_sent);
482	    }
483	
484	#ifdef CONFIG_AI_AGENT_AUDIO_PREPROCESS
485	    preproc_destroy(pp);
486	#endif
487	
488	    /* Store stream handle for voice_channel_stop to finish */
489	    // if (dump_fd >= 0) {
490	    //     close(dump_fd);
491	    //     syslog(LOG_INFO, "[%s] PCM dump saved to /data/cap_dump.pcm\n", TAG);
492	    // }
493	
494	    pthread_mutex_lock(&s_voice.lock);
495	    s_voice.asr_stream = stream;
496	
497	    if (abnormal_exit && s_voice.state == VOICE_RECORDING) {
498	        syslog(LOG_WARNING, "[%s] abnormal exit, cleaning up\n", TAG);
499	        recording_cleanup_locked(stream);
500	    }
501	    pthread_mutex_unlock(&s_voice.lock);
502	
503	    syslog(LOG_INFO,
504	        "[%s] recording thread exit: %d chunks, %zu read, %zu sent%s\n",
505	        TAG, chunk_count, total_bytes_read, total_bytes_sent,
506	        abnormal_exit ? " (abnormal)" : "");
507	    return NULL;
508	}
509	
510	/* ── ASR worker thread ──────────────────────────────────── */
511	
512	#define ASR_THREAD_STACK (24 * 1024)
513	
514	static void* asr_and_dispatch(void* arg)
515	{
516	    unsigned char* pcm = (unsigned char*)arg;
517	    size_t pcm_len;
518	
519	    /* pcm_len is stored in the first sizeof(size_t) bytes */
520	    memcpy(&pcm_len, pcm, sizeof(size_t));
521	    const unsigned char* audio = pcm + sizeof(size_t);
522	
523	    syslog(LOG_INFO, "[%s] ASR: recognizing %zu bytes\n",
524	        TAG, pcm_len);
525	
526	    char text[512];
527	    int ret = voice_asr_recognize(audio, pcm_len,
528	        text, sizeof(text));
529	
530	    if (ret == 0 && text[0] != '\0') {
531	        syslog(LOG_INFO, "[%s] ASR result: %s\n", TAG, text);
532	        printf("ASR: %s\n", text);
533	
534	        agent_msg_t msg;
535	
536	        memset(&msg, 0, sizeof(msg));
537	        strncpy(msg.channel, AGENT_CHAN_VOICE,
538	            sizeof(msg.channel) - 1);
539	        strncpy(msg.chat_id, "voice",
540	            sizeof(msg.chat_id) - 1);
541	        msg.content = strdup(text);
542	        if (msg.content) {
543	            message_bus_push_inbound(&msg);
544	        }
545	    } else {
546	        syslog(LOG_WARNING, "[%s] ASR failed or empty: %d\n",
547	            TAG, ret);
548	    }
549	
550	    free(pcm);
551	    return NULL;
552	}
553	
554	/* ── TTS streaming callback ──────────────────────────────── */
555	
556	static struct timespec s_tts_start;
557	static int s_tts_first_chunk;
558	static struct timespec s_asr_done_ts;
559	
560	static void tts_stream_cb(const unsigned char* pcm_data,
561	    size_t pcm_len, int is_last, void* user_data)
562	{
563	    audio_playback_t* pb = (audio_playback_t*)user_data;
564	
565	    /* Abort early if PTT recording started */
566	    if (s_voice.tts_abort) {
567	        return;
568	    }
569	
570	    if (pcm_data && pcm_len > 0 && pb) {
571	        if (!s_tts_first_chunk) {
572	            struct timespec now;
573	            clock_gettime(CLOCK_MONOTONIC, &now);
574	            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
575	                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
576	            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n",
577	                TAG, ms);
578	            s_tts_first_chunk = 1;
579	        }
580	        audio_playback_write(pb, pcm_data, pcm_len);
581	    }
582	
583	    (void)is_last;
584	}
