587	
588	int voice_channel_init(void)
589	{
590	    syslog(LOG_INFO, "[%s] Voice channel initializing\n", TAG);
591	
592	    /* Reset state on init — static vars may persist across process restarts
593	     * in NuttX depending on how the binary is loaded. */
594	    s_voice.state = VOICE_IDLE;
595	    s_voice.cap = NULL;
596	    s_voice.pcm_buf = NULL;
597	    s_voice.pcm_len = 0;
598	    s_voice.asr_stream = NULL;
599	    s_voice.tts_abort = 0;
600	    s_voice.tts_pb = NULL;
601	    sem_init(&s_voice.rec_ready, 0, 0);
602	
603	    if (!s_backends_registered) {
604	        volc_tts_register();
605	        volc_asr_register();
606	        s_backends_registered = 1;
607	    }
608	
609	    return 0;
610	}
611	
612	int voice_channel_start(void)
613	{
614	    pthread_mutex_lock(&s_voice.lock);
615	    if (s_voice.state != VOICE_IDLE) {
616	        pthread_mutex_unlock(&s_voice.lock);
617	        syslog(LOG_WARNING, "[%s] already recording\n", TAG);
618	        return -EBUSY;
619	    }
620	
621	    /* Drain stale sem posts from previous sessions to prevent
622	     * sem_wait returning immediately before thread is ready. */
623	    while (sem_trywait(&s_voice.rec_ready) == 0)
624	        ;
625	
626	    /* ── AEC workaround: stop active TTS to prevent echo ── */
627	    if (s_voice.tts_pb) {
628	        syslog(LOG_INFO,
629	            "[%s] PTT: stopping active TTS to prevent echo\n", TAG);
630	        s_voice.tts_abort = 1;
631	        audio_playback_stop(s_voice.tts_pb);
632	
633	        /* Release lock so the speak thread can finish closing the
634	         * playback device.  Without this, we hold the lock through
635	         * the entire ASR pre-connect (300-800ms), blocking the speak
636	         * thread from calling audio_playback_close().  The playback
637	         * device stays open while we open the capture device, and on
638	         * BES hardware the shared codec (ci2s) gets confused, causing
639	         * incomplete or corrupted recording. */
640	        pthread_mutex_unlock(&s_voice.lock);
641	
642	        /* Wait for the speak thread to finish — speak_lock is held
643	         * for the entire duration of voice_channel_speak(). */
644	        pthread_mutex_lock(&s_voice.speak_lock);
645	        pthread_mutex_unlock(&s_voice.speak_lock);
646	
647	        syslog(LOG_INFO,
648	            "[%s] PTT: TTS playback fully closed\n", TAG);
649	
650	        /* Re-acquire state lock and re-check — another thread may
651	         * have started recording while we released the lock. */
652	        pthread_mutex_lock(&s_voice.lock);
653	        if (s_voice.state != VOICE_IDLE) {
654	            pthread_mutex_unlock(&s_voice.lock);
655	            syslog(LOG_WARNING, "[%s] state changed during TTS stop\n", TAG);
656	            return -EBUSY;
657	        }
658	    }
659	
660	    /* PCM buffer is lazy-allocated only when streaming ASR fails
661	     * (batch fallback). This saves 128KB RAM on the happy path. */
662	    s_voice.pcm_cap = AGENT_VOICE_PCM_BUF_SIZE;
663	    s_voice.pcm_buf = NULL;
664	    s_voice.pcm_len = 0;
665	    s_voice.asr_stream = NULL;
666	
667	    /* Pre-open streaming ASR session HERE (before spawning the
668	     * recording thread) so that TLS handshake (~300-800ms) completes
669	     * before audio capture starts.  Without this, the handshake runs
670	     * inside recording_thread while audio is already flowing, causing
671	     * the first 300-800ms of speech to be lost.
672	     *
673	     * If the pre-open fails we fall back to batch mode as before. */
674	    voice_asr_stream_t* pre_stream = voice_asr_stream_open();
675	    if (!pre_stream) {
676	        syslog(LOG_WARNING,
677	            "[%s] pre-open ASR failed, will retry in thread\n", TAG);
678	    } else {
679	        syslog(LOG_INFO, "[%s] ASR pre-connected\n", TAG);
680	        s_voice.asr_stream = pre_stream;
681	    }
682	
683	    /* Open capture device (but do NOT start yet — start after the
684	     * recording thread is spawned so the consumer is ready before
685	     * audio frames begin flowing, preventing media_recorder queue
686	     * overflow "data queue is more than max count(4)"). */
687	    s_voice.cap = audio_capture_open(
688	        AGENT_AUDIO_CAPTURE_DEV,
689	        AGENT_VOICE_SAMPLE_RATE,
690	        AGENT_VOICE_CHANNELS,
691	        AGENT_VOICE_BITS);
692	
693	    if (!s_voice.cap) {
694	        if (pre_stream) {
695	            voice_asr_stream_abort(pre_stream);
696	            s_voice.asr_stream = NULL;
697	        }
698	        pthread_mutex_unlock(&s_voice.lock);
699	        syslog(LOG_ERR, "[%s] capture open failed\n", TAG);
700	        return -EIO;
701	    }
702	
703	    s_voice.state = VOICE_RECORDING;
704	    pthread_mutex_unlock(&s_voice.lock);
705	
706	    /* Spawn recording thread BEFORE starting capture */
707	    pthread_attr_t attr;
708	
709	    pthread_attr_init(&attr);
710	    pthread_attr_setstacksize(&attr, AGENT_VOICE_STACK);
711	
712	    int ret = pthread_create(&s_voice.rec_thread, &attr,
713	        recording_thread, NULL);
714	
715	    pthread_attr_destroy(&attr);
716	
717	    if (ret != 0) {
718	        pthread_mutex_lock(&s_voice.lock);
719	        s_voice.state = VOICE_IDLE;
720	        audio_capture_close(s_voice.cap);
721	        s_voice.cap = NULL;
722	        if (s_voice.asr_stream) {
723	            voice_asr_stream_abort(s_voice.asr_stream);
724	            s_voice.asr_stream = NULL;
725	        }
726	        free(s_voice.pcm_buf);
727	        s_voice.pcm_buf = NULL;
728	        pthread_mutex_unlock(&s_voice.lock);
729	        return -ret;
730	    }
731	
732	    /* Now start capture — wait for recording thread to be ready first */
733	    sem_wait(&s_voice.rec_ready);
734	
735	    if (audio_capture_start(s_voice.cap) < 0) {
736	        pthread_mutex_lock(&s_voice.lock);
737	        s_voice.state = VOICE_IDLE;
738	        if (s_voice.asr_stream) {
739	            voice_asr_stream_abort(s_voice.asr_stream);
740	            s_voice.asr_stream = NULL;
741	        }
742	        pthread_mutex_unlock(&s_voice.lock);
743	        audio_capture_abort(s_voice.cap);
744	        pthread_join(s_voice.rec_thread, NULL);
745	        audio_capture_close(s_voice.cap);
746	        s_voice.cap = NULL;
747	        return -EIO;
748	    }
749	
750	    syslog(LOG_INFO, "[%s] PTT recording started\n", TAG);
751	    printf("Voice: recording... (use voice_stop to finish)\n");
752	    return 0;
753	}
754	
755	int voice_channel_stop(void)
756	{
757	    pthread_mutex_lock(&s_voice.lock);
758	    if (s_voice.state != VOICE_RECORDING) {
759	        pthread_mutex_unlock(&s_voice.lock);
760	        return -EINVAL;
761	    }
762	    s_voice.state = VOICE_STOPPING;
763	    pthread_mutex_unlock(&s_voice.lock);
764	
765	    audio_capture_abort(s_voice.cap);
766	
767	    /* Wait for recording thread to finish */
768	    pthread_join(s_voice.rec_thread, NULL);
769	
770	    /* Close capture device */
771	    audio_capture_close(s_voice.cap);
772	
773	    pthread_mutex_lock(&s_voice.lock);
774	    s_voice.cap = NULL;
775	    size_t pcm_len = s_voice.pcm_len;
776	    voice_asr_stream_t* stream = s_voice.asr_stream;
777	    s_voice.asr_stream = NULL;
778	    s_voice.state = VOICE_IDLE;
779	    pthread_mutex_unlock(&s_voice.lock);
780	
781	    syslog(LOG_INFO, "[%s] recorded %zu bytes (stream=%p)\n",
782	        TAG, pcm_len, (void*)stream);
783	
784	    /* If streaming ASR was active, finish it to get result.
785	     * Note: in streaming mode pcm_len is always 0 because audio
786	     * goes directly to the ASR server, not to pcm_buf. */
787	    if (stream) {
788	        printf("Voice: streaming ASR active, finishing...\n");
789	        struct timespec asr_t0;
790	        clock_gettime(CLOCK_MONOTONIC, &asr_t0);
791	        char text[512];
792	        int ret = voice_asr_stream_finish(stream, text,
793	            sizeof(text));
794	        struct timespec asr_t1;
795	        clock_gettime(CLOCK_MONOTONIC, &asr_t1);
796	        long asr_ms = (asr_t1.tv_sec - asr_t0.tv_sec) * 1000
797	            + (asr_t1.tv_nsec - asr_t0.tv_nsec) / 1000000;
798	        syslog(LOG_INFO, "[%s] ASR finish: %ldms\n", TAG, asr_ms);
799	
800	        free(s_voice.pcm_buf); /* may be NULL */
801	        s_voice.pcm_buf = NULL;
802	
803	        if (ret == 0 && text[0] != '\0') {
804	            syslog(LOG_INFO, "[%s] stream ASR: %s\n", TAG, text);
805	            printf("ASR: %s\n", text);
806	            clock_gettime(CLOCK_MONOTONIC, &s_asr_done_ts);
807	
808	            agent_msg_t msg;
809	
810	            memset(&msg, 0, sizeof(msg));
811	            strncpy(msg.channel, AGENT_CHAN_VOICE,
812	                sizeof(msg.channel) - 1);
813	            strncpy(msg.chat_id, "voice",
814	                sizeof(msg.chat_id) - 1);
815	            msg.content = strdup(text);
816	            if (msg.content) {
817	                message_bus_push_inbound(&msg);
818	            }
819	        } else {
820	            syslog(LOG_WARNING,
821	                "[%s] stream ASR failed: %d\n", TAG, ret);
822	        }
823	        return 0;
824	    }
825	
826	    /* Batch fallback: pcm_buf must exist if we reach here */
827	    if (!s_voice.pcm_buf || pcm_len == 0) {
828	        free(s_voice.pcm_buf);
829	        s_voice.pcm_buf = NULL;
830	        syslog(LOG_ERR, "[%s] no PCM data for batch ASR\n", TAG);
831	        return -ENODATA;
832	    }
833	
834	    /* Batch fallback: pack pcm_len + audio for ASR thread */
835	    size_t total = sizeof(size_t) + pcm_len;
836	    unsigned char* pkg = malloc(total);
837	
838	    if (!pkg) {
839	        free(s_voice.pcm_buf);
840	        s_voice.pcm_buf = NULL;
841	        return -ENOMEM;
842	    }
843	
844	    memcpy(pkg, &pcm_len, sizeof(size_t));
845	    memcpy(pkg + sizeof(size_t), s_voice.pcm_buf, pcm_len);
846	    free(s_voice.pcm_buf);
847	    s_voice.pcm_buf = NULL;
848	
849	    /* Spawn ASR worker thread */
850	    int ret = agent_task_create(asr_and_dispatch, "asr_worker",
851	        ASR_THREAD_STACK, pkg, AGENT_VOICE_PRIO);
852	
853	    if (ret != OK) {
854	        free(pkg);
855	        return -EIO;
856	    }
857	
858	    return 0;
859	}
860	
861	int voice_channel_stop_with_text(char* text_out, size_t text_cap)
862	{
863	    if (!text_out || text_cap == 0) {
864	        return -EINVAL;
865	    }
866	
867	    text_out[0] = '\0';
868	
869	    pthread_mutex_lock(&s_voice.lock);
870	    if (s_voice.state != VOICE_RECORDING) {
871	        pthread_mutex_unlock(&s_voice.lock);
872	        return -EINVAL;
873	    }
874	    s_voice.state = VOICE_STOPPING;
875	    pthread_mutex_unlock(&s_voice.lock);
876	
877	    audio_capture_abort(s_voice.cap);
878	
879	    /* Wait for recording thread to finish */
880	    pthread_join(s_voice.rec_thread, NULL);
881	
882	    /* Close capture device */
883	    audio_capture_close(s_voice.cap);
884	
885	    pthread_mutex_lock(&s_voice.lock);
886	    s_voice.cap = NULL;
887	    size_t pcm_len = s_voice.pcm_len;
888	    voice_asr_stream_t* stream = s_voice.asr_stream;
889	    s_voice.asr_stream = NULL;
890	    s_voice.state = VOICE_IDLE;
891	    pthread_mutex_unlock(&s_voice.lock);
892	
893	    syslog(LOG_INFO, "[%s] recorded %zu bytes (with_text, stream=%p)\n",
894	        TAG, pcm_len, (void*)stream);
895	
896	    /* Streaming ASR path: finish and copy text to caller.
897	     * In streaming mode audio goes directly to server, so
898	     * pcm_len may be 0 — that's OK, don't abort. */
899	    if (stream) {
900	        char text[512];
901	        int ret = voice_asr_stream_finish(stream, text,
902	            sizeof(text));
903	
904	        free(s_voice.pcm_buf);
905	        s_voice.pcm_buf = NULL;
906	
907	        if (ret == 0 && text[0] != '\0') {
908	            syslog(LOG_INFO, "[%s] stream ASR (with_text): %s\n",
909	                TAG, text);
910	            strncpy(text_out, text, text_cap - 1);
911	            text_out[text_cap - 1] = '\0';
912	        }
913	        return 0;
914	    }
915	
916	    /* Batch fallback: synchronous ASR inline (no thread) */
917	    if (!s_voice.pcm_buf || pcm_len == 0) {
918	        free(s_voice.pcm_buf);
919	        s_voice.pcm_buf = NULL;
920	        syslog(LOG_ERR, "[%s] no PCM data for batch ASR\n", TAG);
921	        return -ENODATA;
922	    }
923	
924	    syslog(LOG_INFO, "[%s] batch ASR (with_text): %zu bytes\n",
925	        TAG, pcm_len);
926	
927	    char text[512];
928	    int ret = voice_asr_recognize(s_voice.pcm_buf, pcm_len,
929	        text, sizeof(text));
930	
931	    free(s_voice.pcm_buf);
932	    s_voice.pcm_buf = NULL;
933	
934	    if (ret == 0 && text[0] != '\0') {
935	        syslog(LOG_INFO, "[%s] batch ASR result: %s\n", TAG, text);
936	        strncpy(text_out, text, text_cap - 1);
937	        text_out[text_cap - 1] = '\0';
938	    } else if (ret != 0) {
939	        syslog(LOG_WARNING, "[%s] batch ASR failed: %d\n",
940	            TAG, ret);
941	    }
942	
943	    return 0;
944	}
945	
946	/* Strip Markdown formatting that TTS would read aloud.
947	 * Removes: **bold**, *italic*, # headings, - list bullets.
948	 * Operates in-place, result is always <= original length. */
949	static void tts_strip_markdown(char* s)
950	{
951	    char* r = s; /* read pointer */
952	    char* w = s; /* write pointer */
953	
954	    while (*r) {
955	        /* Skip ** (bold markers) */
956	        if (r[0] == '*' && r[1] == '*') {
957	            r += 2;
958	            continue;
959	        }
960	
961	        /* Skip lone * (italic markers) \xe2\x80\x94 but keep * in
962	         * contexts like "3*4" (digit before and after) */
963	        if (r[0] == '*') {
964	            if ((r == s || !isdigit((unsigned char)r[-1]))
965	                || !isdigit((unsigned char)r[1])) {
966	                r++;
967	                continue;
968	            }
969	        }
970	
971	        /* Skip # at line start (headings) */
972	        if (r[0] == '#' && (r == s || r[-1] == '\n')) {
973	            while (*r == '#' || *r == ' ') {
974	                r++;
975	            }
976	            continue;
977	        }
978	
979	        /* Skip "- " at line start (list bullets) */
980	        if (r[0] == '-' && r[1] == ' '
981	            && (r == s || r[-1] == '\n')) {
982	            r += 2;
983	            continue;
984	        }
985	
986	        *w++ = *r++;
987	    }
988	
989	    *w = '\0';
990	}
991	
992	int voice_channel_speak(const char* text)
993	{
994	    if (!text || text[0] == '\0') {
995	        return -EINVAL;
996	    }
997	
998	    /* ── Serialize concurrent speak calls ── */
999	    /* If another thread is already speaking, abort its TTS playback
1000	     * so we don't overlap media_player sessions (which causes the
1001	     * media framework to attempt a ~1.3GB allocation and crash). */
1002	    pthread_mutex_lock(&s_voice.lock);
1003	    if (s_voice.tts_pb) {
1004	        syslog(LOG_INFO, "[%s] speak: aborting previous TTS\n", TAG);
1005	        s_voice.tts_abort = 1;
1006	        audio_playback_stop(s_voice.tts_pb);
1007	    }
1008	    pthread_mutex_unlock(&s_voice.lock);
1009	
1010	    pthread_mutex_lock(&s_voice.speak_lock);
1011	
1012	    /* ── AEC workaround: reject TTS while PTT is recording ── */
1013	    pthread_mutex_lock(&s_voice.lock);
1014	    if (s_voice.state != VOICE_IDLE) {
1015	        pthread_mutex_unlock(&s_voice.lock);
1016	        pthread_mutex_unlock(&s_voice.speak_lock);
1017	        syslog(LOG_INFO,
1018	            "[%s] speak: skipped, recording active\n", TAG);
1019	        return -EBUSY;
1020	    }
1021	    pthread_mutex_unlock(&s_voice.lock);
1022	
1023	    /* Work on a mutable copy so we can strip markdown in-place */
1024	    size_t text_len = strlen(text);
1025	    char* clean = malloc(text_len + 1);
1026	
1027	    if (!clean) {
1028	        pthread_mutex_unlock(&s_voice.speak_lock);
1029	        return -ENOMEM;
1030	    }
1031	
1032	    memcpy(clean, text, text_len + 1);
1033	    tts_strip_markdown(clean);
1034	
1035	    /* If stripping left nothing, bail out */
1036	    if (clean[0] == '\0') {
1037	        free(clean);
1038	        pthread_mutex_unlock(&s_voice.speak_lock);
1039	        return 0;
1040	    }
1041	
1042	    syslog(LOG_INFO, "[%s] speak: \"%.*s\" (%zu bytes)\n",
1043	        TAG, 60, clean, strlen(clean));
1044	
1045	    clock_gettime(CLOCK_MONOTONIC, &s_tts_start);
1046	    s_tts_first_chunk = 0;
1047	
1048	    if (s_asr_done_ts.tv_sec > 0) {
1049	        long llm_ms = (s_tts_start.tv_sec - s_asr_done_ts.tv_sec) * 1000
1050	            + (s_tts_start.tv_nsec - s_asr_done_ts.tv_nsec) / 1000000;
1051	        syslog(LOG_INFO, "[%s] LLM latency: %ldms\n", TAG, llm_ms);
1052	    }
1053	
1054	    /* Try streaming TTS first (callback per chunk) */
1055	    audio_playback_t* pb = audio_playback_open(
1056	        AGENT_AUDIO_PLAYBACK_DEV,
1057	        AGENT_TTS_WS_SAMPLE_RATE,
1058	        AGENT_VOICE_CHANNELS,
1059	        AGENT_VOICE_BITS);
1060	
1061	    if (!pb) {
1062	        syslog(LOG_ERR, "[%s] playback open failed\n", TAG);
1063	        free(clean);
1064	        pthread_mutex_unlock(&s_voice.speak_lock);
1065	        return -EIO;
1066	    }
1067	
1068	    /* Register active playback so voice_channel_start() can abort it */
1069	    pthread_mutex_lock(&s_voice.lock);
1070	    s_voice.tts_abort = 0;
1071	    s_voice.tts_pb = pb;
1072	    pthread_mutex_unlock(&s_voice.lock);
1073	
1074	    /* Use streaming TTS: each chunk writes to playback file */
1075	    int ret = voice_tts_speak_stream(clean,
1076	        tts_stream_cb, pb);
1077	
1078	    struct timespec tts_net;
1079	    clock_gettime(CLOCK_MONOTONIC, &tts_net);
1080	    long net_ms = (tts_net.tv_sec - s_tts_start.tv_sec) * 1000
1081	        + (tts_net.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1082	    syslog(LOG_INFO, "[%s] TTS network done: %ldms\n", TAG, net_ms);
1083	
1084	    /* Unregister active playback */
1085	    pthread_mutex_lock(&s_voice.lock);
1086	    s_voice.tts_pb = NULL;
1087	    s_voice.tts_abort = 0;
1088	    pthread_mutex_unlock(&s_voice.lock);
1089	
1090	    audio_playback_close(pb);
1091	    free(clean);
1092	
1093	    if (ret != 0) {
1094	        syslog(LOG_ERR, "[%s] TTS stream failed: %d\n", TAG, ret);
1095	        pthread_mutex_unlock(&s_voice.speak_lock);
1096	        return ret;
1097	    }
1098	
1099	    struct timespec tend;
1100	    clock_gettime(CLOCK_MONOTONIC, &tend);
1101	    long total_ms = (tend.tv_sec - s_tts_start.tv_sec) * 1000
1102	        + (tend.tv_nsec - s_tts_start.tv_nsec) / 1000000;
1103	    syslog(LOG_INFO, "[%s] speak done: total %ldms (play wait %ldms)\n",
1104	        TAG, total_ms, total_ms - net_ms);
1105	    pthread_mutex_unlock(&s_voice.speak_lock);
1106	    return 0;
1107	}
1108	
1109	/* ── Test commands (file-based, for QEMU) ───────────────── */
1110	
1111	int voice_channel_test_tts(const char* text, const char* out_path)
1112	{
1113	    if (!text || !out_path) {
1114	        printf("Usage: voice_test_tts <text> [output_path]\n");
1115	        return -EINVAL;
1116	    }
1117	
1118	    printf("TTS: synthesizing \"%s\" ...\n", text);
1119	
1120	    unsigned char* pcm = malloc(AGENT_VOICE_PCM_BUF_SIZE);
1121	
1122	    if (!pcm) {
1123	        printf("Error: out of memory\n");
1124	        return -ENOMEM;
1125	    }
1126	
1127	    size_t pcm_len;
1128	    int ret = voice_tts_speak(text, pcm,
1129	        AGENT_VOICE_PCM_BUF_SIZE, &pcm_len);
1130	
1131	    if (ret != 0) {
1132	        free(pcm);
1133	        printf("TTS failed: %d\n", ret);
1134	        return ret;
