57	/* ── TCP connect helper ────────────────────────────────────── */
58	
59	static int tcp_connect(const char *host, int port)
60	{
61	    char port_str[8];
62	
63	    snprintf(port_str, sizeof(port_str), "%d", port);
64	
65	    struct addrinfo hints;
66	    struct addrinfo *res;
67	
68	    memset(&hints, 0, sizeof(hints));
69	    hints.ai_family = AF_INET;
70	    hints.ai_socktype = SOCK_STREAM;
71	
72	    if (getaddrinfo(host, port_str, &hints, &res) != 0 || !res) {
73	        syslog(LOG_ERR, "[%s] DNS resolve failed: %s\n", TAG, host);
74	        return -1;
75	    }
76	
77	    int fd = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
78	
79	    if (fd < 0) {
80	        freeaddrinfo(res);
81	        return -1;
82	    }
83	
84	    if (connect(fd, res->ai_addr, res->ai_addrlen) < 0) {
85	        syslog(LOG_ERR, "[%s] TCP connect failed: %s:%d (%s)\n",
86	               TAG, host, port, strerror(errno));
87	        close(fd);
88	        freeaddrinfo(res);
89	        return -1;
90	    }
91	
92	    freeaddrinfo(res);
93	
94	    /* Set recv timeout so mqtt_sync is not blocked forever.
95	     * This allows MQTT-C to send PINGREQ on time. */
96	    struct timeval tv;
97	
98	    tv.tv_sec = 1;
99	    tv.tv_usec = 0;
100	    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
101	
102	    syslog(LOG_INFO, "[%s] TCP connected to %s:%d (fd=%d)\n",
103	           TAG, host, port, fd);
104	    return fd;
105	}
106	
107	/* ── Publish callback (incoming messages from broker) ──────── */
108	
109	static void on_publish(void **state, struct mqtt_response_publish *pub)
110	{
111	    (void)state;
112	
113	    if (pub->application_message_size == 0) {
114	        return;
115	    }
116	
117	    /* NUL-terminate the payload (MQTT-C does not guarantee it) */
118	    size_t len = pub->application_message_size;
119	    char *payload = malloc(len + 1);
120	
121	    if (!payload) {
122	        return;
123	    }
124	
125	    memcpy(payload, pub->application_message, len);
126	    payload[len] = '\0';
127	
128	    syslog(LOG_INFO, "[%s] Recv [%.*s]: %.64s\n",
129	           TAG, (int)pub->topic_name_size,
130	           (const char *)pub->topic_name, payload);
131	
132	    /* Parse JSON: {"type":"message","content":"...","chat_id":"..."} */
133	    cJSON *root = cJSON_Parse(payload);
134	
135	    if (!root) {
136	        /* Plain text fallback — treat entire payload as content */
137	        agent_msg_t msg;
138	
139	        memset(&msg, 0, sizeof(msg));
140	        strncpy(msg.channel, AGENT_CHAN_MQTT, sizeof(msg.channel) - 1);
141	        strncpy(msg.chat_id, "mqtt_default", sizeof(msg.chat_id) - 1);
142	        msg.content = payload; /* bus takes ownership on success */
143	        if (message_bus_push_inbound(&msg) != OK) {
144	            free(payload);
145	        }
146	        return;
147	    }
148	
149	    cJSON *content_item = cJSON_GetObjectItem(root, "content");
150	    cJSON *chat_id_item = cJSON_GetObjectItem(root, "chat_id");
151	
152	    if (cJSON_IsString(content_item) && content_item->valuestring[0]) {
153	        agent_msg_t msg;
154	
155	        memset(&msg, 0, sizeof(msg));
156	        strncpy(msg.channel, AGENT_CHAN_MQTT, sizeof(msg.channel) - 1);
157	
158	        if (cJSON_IsString(chat_id_item) && chat_id_item->valuestring[0]) {
159	            strncpy(msg.chat_id, chat_id_item->valuestring,
160	                    sizeof(msg.chat_id) - 1);
161	        } else {
162	            strncpy(msg.chat_id, "mqtt_default", sizeof(msg.chat_id) - 1);
163	        }
164	
165	        msg.content = strdup(content_item->valuestring);
166	        if (msg.content) {
167	            if (message_bus_push_inbound(&msg) != OK) {
168	                free(msg.content);
169	            }
170	        }
171	    }
172	
173	    cJSON_Delete(root);
174	    free(payload);
175	}
176	
177	/* ── Reconnect callback ────────────────────────────────────── */
178	
179	static void on_reconnect(struct mqtt_client *client, void **state)
180	{
181	    (void)state;
182	
183	    /* Close old socket if any */
184	    if (s_sockfd >= 0) {
185	        close(s_sockfd);
186	        s_sockfd = -1;
187	    }
188	
189	    syslog(LOG_INFO, "[%s] Reconnecting to %s:%d...\n",
190	           TAG, s_broker_host, s_broker_port);
191	
192	    s_sockfd = tcp_connect(s_broker_host, s_broker_port);
193	    if (s_sockfd < 0) {
194	        syslog(LOG_ERR, "[%s] Reconnect TCP failed\n", TAG);
195	        /* Reinit with invalid fd so MQTT-C stays in error state
196	         * and will call reconnect_callback again on next mqtt_sync. */
197	        mqtt_reinit(client, -1,
198	                    s_sendbuf, sizeof(s_sendbuf),
199	                    s_recvbuf, sizeof(s_recvbuf));
200	        return;
201	    }
202	
203	    mqtt_reinit(client, s_sockfd,
204	                s_sendbuf, sizeof(s_sendbuf),
205	                s_recvbuf, sizeof(s_recvbuf));
206	
207	    uint8_t flags = MQTT_CONNECT_CLEAN_SESSION;
208	    const char *user = s_username[0] ? s_username : NULL;
209	    const char *pass = s_password[0] ? s_password : NULL;
210	
211	    enum MQTTErrors err = mqtt_connect(client, s_client_id,
212	                                       NULL, NULL, 0,
213	                                       user, pass, flags,
214	                                       AGENT_MQTT_KEEPALIVE);
215	    if (err != MQTT_OK) {
216	        syslog(LOG_ERR, "[%s] mqtt_connect failed: %d\n", TAG, (int)err);
217	        return;
218	    }
219	
220	    /* Subscribe to inbound topic */
221	    mqtt_subscribe(client, s_topic_in, 1);
222	    syslog(LOG_INFO, "[%s] Subscribed to %s\n", TAG, s_topic_in);
223	}
224	
225	/* ── Sync thread (calls mqtt_sync periodically) ───────────── */
226	
227	static void *mqtt_sync_thread(void *arg)
228	{
229	    (void)arg;
230	
231	    syslog(LOG_INFO, "[%s] Sync thread started\n", TAG);
232	
233	    while (s_running) {
234	        enum MQTTErrors err = mqtt_sync(&s_client);
235	
236	        if (err != MQTT_OK) {
237	            syslog(LOG_WARNING, "[%s] mqtt_sync error: %d\n", TAG, (int)err);
238	            /* MQTT-C will call reconnect_callback automatically */
239	        }
240	
241	        usleep(AGENT_MQTT_SYNC_INTERVAL_MS * 1000);
242	    }
243	
244	    syslog(LOG_INFO, "[%s] Sync thread exited\n", TAG);
245	    return NULL;
246	}
247	
248	/* ── Parse broker URL "host:port" ──────────────────────────── */
249	
250	static void parse_broker(const char *broker, char *host, size_t host_sz,
251	                         int *port)
252	{
253	    const char *colon = strrchr(broker, ':');
254	
255	    if (colon && colon != broker) {
256	        size_t hlen = (size_t)(colon - broker);
257	
258	        if (hlen >= host_sz) {
259	            hlen = host_sz - 1;
260	        }
261	
262	        memcpy(host, broker, hlen);
263	        host[hlen] = '\0';
264	        *port = atoi(colon + 1);
265	    } else {
266	        strncpy(host, broker, host_sz - 1);
267	        host[host_sz - 1] = '\0';
268	        *port = AGENT_MQTT_DEFAULT_PORT;
269	    }
270	
271	    if (*port <= 0 || *port > 65535) {
272	        *port = AGENT_MQTT_DEFAULT_PORT;
273	    }
274	}
275	
276	/* ── Public API ────────────────────────────────────────────── */
277	
278	int mqtt_channel_init(void)
279	{
280	    char broker_buf[192];
281	
282	    memset(broker_buf, 0, sizeof(broker_buf));
283	    memset(s_broker_host, 0, sizeof(s_broker_host));
284	    memset(s_client_id, 0, sizeof(s_client_id));
285	    memset(s_topic_in, 0, sizeof(s_topic_in));
286	    memset(s_topic_out, 0, sizeof(s_topic_out));
287	    memset(s_username, 0, sizeof(s_username));
288	    memset(s_password, 0, sizeof(s_password));
289	    s_broker_port = AGENT_MQTT_DEFAULT_PORT;
290	
291	    /* Read config from config store */
292	    claw_config_get(AGENT_CFG_KEY_MQTT_BROKER,
293	                    broker_buf, sizeof(broker_buf));
294	    claw_config_get(AGENT_CFG_KEY_MQTT_CLIENT_ID,
295	                    s_client_id, sizeof(s_client_id));
296	    claw_config_get(AGENT_CFG_KEY_MQTT_TOPIC_IN,
297	                    s_topic_in, sizeof(s_topic_in));
298	    claw_config_get(AGENT_CFG_KEY_MQTT_TOPIC_OUT,
299	                    s_topic_out, sizeof(s_topic_out));
300	    claw_config_get(AGENT_CFG_KEY_MQTT_USERNAME,
301	                    s_username, sizeof(s_username));
302	    claw_config_get(AGENT_CFG_KEY_MQTT_PASSWORD,
303	                    s_password, sizeof(s_password));
304	
305	    /* Parse broker host:port */
306	    if (broker_buf[0]) {
307	        parse_broker(broker_buf, s_broker_host,
308	                     sizeof(s_broker_host), &s_broker_port);
309	    }
310	
311	    /* Defaults */
312	    if (!s_client_id[0]) {
313	        snprintf(s_client_id, sizeof(s_client_id),
314	                 "agent-%s", AGENT_NODE_ID);
315	    }
316	
317	    if (!s_topic_in[0]) {
318	        strncpy(s_topic_in, AGENT_MQTT_TOPIC_IN_DEFAULT,
319	                sizeof(s_topic_in) - 1);
320	    }
321	
322	    if (!s_topic_out[0]) {
323	        strncpy(s_topic_out, AGENT_MQTT_TOPIC_OUT_DEFAULT,
324	                sizeof(s_topic_out) - 1);
325	    }
326	
327	    syslog(LOG_INFO, "[%s] MQTT channel initialized (broker=%s:%d)\n",
328	           TAG, s_broker_host[0] ? s_broker_host : "(not set)",
329	           s_broker_port);
330	    return OK;
331	}
332	
333	int mqtt_channel_start(void)
334	{
335	    if (!s_broker_host[0]) {
336	        syslog(LOG_INFO, "[%s] No mqtt_broker configured, MQTT disabled\n",
337	               TAG);
338	        return OK;
339	    }
340	
341	    /* Use mqtt_init_reconnect so MQTT-C handles auto-reconnect */
342	    mqtt_init_reconnect(&s_client, on_reconnect, NULL, on_publish);
343	
344	    s_running = true;
345	
346	    int ret = agent_task_create(mqtt_sync_thread, "mqtt_sync",
347	                                   AGENT_MQTT_STACK, NULL,
348	                                   AGENT_MQTT_PRIO);
349	    if (ret != OK) {
350	        syslog(LOG_ERR, "[%s] Failed to create sync thread\n", TAG);
351	        s_running = false;
352	        return ERROR;
353	    }
354	
355	    syslog(LOG_INFO, "[%s] MQTT channel started → %s:%d\n",
356	           TAG, s_broker_host, s_broker_port);
357	    return OK;
358	}
359	
360	int mqtt_channel_send(const char *chat_id, const char *text)
361	{
362	    if (!s_running || s_sockfd < 0 || !chat_id || !text) {
363	        return ERROR;
364	    }
365	
366	    /* Build JSON: {"type":"response","content":"...","chat_id":"..."} */
367	    cJSON *resp = cJSON_CreateObject();
368	
369	    cJSON_AddStringToObject(resp, "type", "response");
370	    cJSON_AddStringToObject(resp, "content", text);
371	    cJSON_AddStringToObject(resp, "chat_id", chat_id);
372	
373	    char *json = cJSON_PrintUnformatted(resp);
374	
375	    cJSON_Delete(resp);
376	    if (!json) {
377	        return ERROR;
378	    }
379	
380	    enum MQTTErrors err = mqtt_publish(&s_client, s_topic_out,
381	                                       json, strlen(json),
382	                                       MQTT_PUBLISH_QOS_1);
383	    if (err != MQTT_OK) {
384	        syslog(LOG_ERR, "[%s] Publish failed: %d\n", TAG, (int)err);
385	        free(json);
386	        return ERROR;
387	    }
388	
389	    syslog(LOG_INFO, "[%s] Published to %s (%d bytes)\n",
390	           TAG, s_topic_out, (int)strlen(json));
391	    free(json);
392	    return OK;
393	}
394	
395	void mqtt_channel_stop(void)
396	{
397	    if (!s_running) {
398	        return;
399	    }
400	
401	    s_running = false;
402	
403	    /* Close socket first to unblock any blocking recv in sync thread */
404	    if (s_sockfd >= 0) {
405	        close(s_sockfd);
406	        s_sockfd = -1;
407	    }
408	
409	    /* Give sync thread time to notice s_running=false and exit */
410	    usleep(AGENT_MQTT_SYNC_INTERVAL_MS * 2 * 1000);
411	
412	    syslog(LOG_INFO, "[%s] MQTT channel stopped\n", TAG);
413	}
