79	static int tokenise(char* line, char** argv, int max_argc)
80	{
81	    int argc = 0;
82	    char* tok = strtok(line, " \t\r\n");
83	    while (tok && argc < max_argc) {
84	        argv[argc++] = tok;
85	        tok = strtok(NULL, " \t\r\n");
86	    }
87	    return argc;
88	}
