219	static void cmd_net_diag(int argc, char** argv)
220	{
221	    if (argc < 2) {
222	        /* Basic diagnostics */
223	        printf("=== Network Diagnostics ===\n");
224	        printf("Interface: %s\n",
225	            network_is_connected() ? "UP" : "DOWN");
226	        printf("IP: %s\n", network_get_ip());
227	        printf("State: %s\n",
228	            network_get_state() == NET_STATE_CONNECTED
229	                ? "CONNECTED"
230	                : "DISCONNECTED");
231	        printf("IOB: %d%%\n", network_get_iob_usage());
232	        printf("===========================\n");
233	        return;
234	    }
235	
236	    if (strcmp(argv[1], "ping") == 0 && argc >= 3) {
237	        char cmd[128];
238	        snprintf(cmd, sizeof(cmd), "ping -c 3 %s", argv[2]);
239	        system(cmd);
240	    } else if (strcmp(argv[1], "http") == 0 && argc >= 3) {
241	        printf("HTTP HEAD %s ...\n", argv[2]);
242	        /* Simple connectivity test using existing TLS layer */
243	        char resp[256] = { 0 };
244	        struct timespec t0, t1;
245	        clock_gettime(CLOCK_MONOTONIC, &t0);
246	        int status = vela_https_get(argv[2], "443", "/",
247	            resp, sizeof(resp));
248	        clock_gettime(CLOCK_MONOTONIC, &t1);
249	        long ms = (t1.tv_sec - t0.tv_sec) * 1000L
250	            + (t1.tv_nsec - t0.tv_nsec) / 1000000L;
251	        printf("Status: %d, Latency: %ldms\n", status, ms);
252	    } else {
253	        printf("Usage: net_diag [ping <host> | http <host>]\n");
254	    }
255	}
256	#endif
