574	static void cmd_ask(int argc, char** argv)
575	{
576	    if (argc < 2) {
577	        printf("Usage: ask <message>\n");
578	        return;
579	    }
580	
581	    /* Concatenate all arguments as the message */
582	    char content[256] = { 0 };
583	    for (int i = 1; i < argc; i++) {
584	        strncat(content, argv[i], sizeof(content) - strlen(content) - 1);
585	        if (i < argc - 1)
586	            strncat(content, " ", sizeof(content) - strlen(content) - 1);
587	    }
588	
589	    agent_msg_t msg = { 0 };
590	    strncpy(msg.channel, "cli", sizeof(msg.channel) - 1);
591	    strncpy(msg.chat_id, "console", sizeof(msg.chat_id) - 1);
592	    msg.content = strdup(content);
593	    if (msg.content)
594	        message_bus_push_inbound(&msg);
595	    printf("Sent to agent: %s\n", content);
596	    syslog(LOG_INFO, "[agent] ask: %s\n", content);
597	}
