775	/* ── install_skill: install a skill from URL ──────────────── */
776	
777	static void cmd_install_skill(int argc, char** argv)
778	{
779	    if (argc < 3) {
780	        printf("Usage: install_skill <name> <url>\n"
781	               "  name: skill filename (without .md)\n"
782	               "  url:  HTTPS URL to download skill markdown\n");
783	        return;
784	    }
785	
786	    const char* name = argv[1];
787	    const char* url = argv[2];
788	
789	    /* Validate name (lowercase + digits + hyphens) */
790	    for (const char* p = name; *p; p++) {
791	        if (!(*p >= 'a' && *p <= 'z') && !(*p >= '0' && *p <= '9')
792	            && *p != '-' && *p != '_') {
793	            printf("Invalid skill name: use a-z, 0-9, hyphens\n");
794	            return;
795	        }
796	    }
797	
798	    /* Validate URL starts with https:// */
799	    if (strncmp(url, "https://", 8) != 0) {
800	        printf("Only HTTPS URLs are allowed\n");
801	        return;
802	    }
803	
804	    char path[128];
805	    int n = snprintf(path, sizeof(path), "%s%s.md",
806	        AGENT_SKILLS_DIR, name);
807	    if (n < 0 || (size_t)n >= sizeof(path)) {
808	        printf("Skill name too long\n");
809	        return;
810	    }
811	
812	    char* buf = malloc(8192);
813	    if (!buf) {
814	        printf("OOM\n");
815	        return;
816	    }
817	
818	    memset(buf, 0, 8192);
819	    int rc = vela_https_get(url, "443", NULL, buf, 8192);
820	    if (rc < 200 || rc >= 300) {
821	        printf("Download failed: HTTP %d\n", rc);
822	        free(buf);
823	        return;
824	    }
825	
826	    /* Validate content looks like a markdown skill file */
827	    if (buf[0] == '\0') {
828	        printf("Downloaded content is empty\n");
829	        free(buf);
830	        return;
831	    }
832	
833	    /* Basic content validation: must start with # or --- (frontmatter) */
834	    const char* p = buf;
835	    while (*p == ' ' || *p == '\n' || *p == '\r')
836	        p++;
837	    if (*p != '#' && strncmp(p, "---", 3) != 0) {
838	        printf("Invalid skill format: must start with # or ---\n");
839	        free(buf);
840	        return;
841	    }
842	
843	    /* Size sanity check */
844	    size_t content_len = strlen(buf);
845	    if (content_len < 10) {
846	        printf("Downloaded content too small (%zu bytes)\n", content_len);
847	        free(buf);
848	        return;
849	    }
850	
851	    FILE* f = fopen(path, "w");
852	    if (!f) {
853	        printf("Cannot write: %s\n", path);
854	        free(buf);
855	        return;
856	    }
857	
858	    fputs(buf, f);
859	    fclose(f);
860	    free(buf);
861	    printf("Skill installed: %s (%zu bytes)\n", path, content_len);
862	}
