879	static void* cli_thread(void* arg)
880	{
881	    (void)arg;
882	    char line[LINE_LEN];
883	    char* argv[MAX_ARGS];
884	
885	    syslog(LOG_INFO, "[%s] NSH CLI started. Type 'help' for commands.\n", TAG);
886	    pthread_mutex_lock(&g_stdout_lock);
887	    printf("vela> ");
888	    fflush(stdout);
889	    pthread_mutex_unlock(&g_stdout_lock);
890	
891	    while (fgets(line, sizeof(line), stdin) != NULL) {
892	        /* Strip trailing newline */
893	        size_t len = strlen(line);
894	        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
895	            line[--len] = '\0';
896	
897	        if (len == 0) {
898	            pthread_mutex_lock(&g_stdout_lock);
899	            printf("vela> ");
900	            fflush(stdout);
901	            pthread_mutex_unlock(&g_stdout_lock);
902	            continue;
903	        }
904	
905	        int argc = tokenise(line, argv, MAX_ARGS);
906	        if (argc == 0) {
907	            pthread_mutex_lock(&g_stdout_lock);
908	            printf("vela> ");
909	            fflush(stdout);
910	            pthread_mutex_unlock(&g_stdout_lock);
911	            continue;
912	        }
913	
914	        const char* cmd = argv[0];
915	
916	        if (strcmp(cmd, "help") == 0)
917	            cmd_help();
918	        else if (strcmp(cmd, "net_status") == 0)
919	            cmd_net_status();
920	        else if (strcmp(cmd, "net_test") == 0)
