934	        else if (strcmp(cmd, "memory_write") == 0)
935	            cmd_memory_write(argc, argv);
936	        else if (strcmp(cmd, "session_list") == 0)
937	            cmd_session_list();
938	        else if (strcmp(cmd, "session_clear") == 0)
939	            cmd_session_clear(argc, argv);
940	        else if (strcmp(cmd, "session_clear_all") == 0)
941	            cmd_session_clear_all();
942	        else if (strcmp(cmd, "heap_info") == 0)
943	            cmd_heap_info();
944	        else if (strcmp(cmd, "set_proxy") == 0)
945	            cmd_set_proxy(argc, argv);
946	        else if (strcmp(cmd, "clear_proxy") == 0)
947	            cmd_clear_proxy();
948	        else if (strcmp(cmd, "set_wifi") == 0)
949	            cmd_set_wifi(argc, argv);
950	        else if (strcmp(cmd, "wifi_reconnect") == 0)
951	            cmd_wifi_reconnect();
952	#ifdef CONFIG_AI_AGENT_NET_RPMSG
953	        else if (strcmp(cmd, "net_diag") == 0)
954	            cmd_net_diag(argc, argv);
955	        else if (strcmp(cmd, "net_reconnect") == 0)
956	            cmd_net_reconnect();
