970	        else if (strcmp(cmd, "config_show") == 0)
971	            cmd_config_show();
972	        else if (strcmp(cmd, "config_reset") == 0)
973	            cmd_config_reset();
974	        else if (strcmp(cmd, "heartbeat_trigger") == 0)
