static const char* TAG = "cli";

#define MAX_ARGS 8
#define LINE_LEN 256

/* ── Helpers ──────────────────────────────────────────────────── */

static int tokenise(char* line, char** argv, int max_argc)
{
    int argc = 0;
    char* tok = strtok(line, " \t\r\n");
    while (tok && argc < max_argc) {
        argv[argc++] = tok;
        tok = strtok(NULL, " \t\r\n");
    }
    return argc;
}

static void cmd_help(void)
{
    printf(
