#pragma once

#include "agent_compat.h"
#include <pthread.h>

/* Shared stdout mutex — prevents concurrent printf from outbound_dispatch_task
 * and cli_thread which causes adbd shell_service_uv assert. */
extern pthread_mutex_t g_stdout_lock;

