307	
308	/* ---- list_models helpers ---- */
309	
310	#define LIST_MODELS_BUF_SIZE (256 * 1024)
311	#define LIST_MODELS_PATH "/api/v1/models"
312	
313	static int list_models_fetch(const char* api_key, char** out, size_t* out_len)
314	{
315	    char* buf = malloc(LIST_MODELS_BUF_SIZE);
316	
317	    if (!buf) {
318	        printf("Error: OOM allocating response buffer\n");
319	        return ERROR;
320	    }
321	
322	    vela_header_t hdrs[3];
323	    char auth[160];
324	
325	    snprintf(auth, sizeof(auth), "Bearer %s", api_key);
326	    hdrs[0].name = "Authorization";
327	    hdrs[0].value = auth;
328	    hdrs[1].name = "Accept";
329	    hdrs[1].value = "application/json";
330	    hdrs[2].name = NULL;
331	    hdrs[2].value = NULL;
332	
333	    size_t body_len;
334	    int status = vela_https_request(
335	        AGENT_LLM_OPENROUTER_HOST, "443", "GET",
336	        LIST_MODELS_PATH, hdrs, NULL, 0,
337	        buf, LIST_MODELS_BUF_SIZE, &body_len);
338	
339	    if (status < 200 || status >= 300) {
340	        printf("Error: HTTP %d from models API\n", status);
341	        free(buf);
342	        return ERROR;
343	    }
344	
345	    *out = buf;
346	    *out_len = body_len;
347	    return OK;
348	}
349	
350	static int list_models_fetch_proxy(const char* api_key,
351	    char** out, size_t* out_len)
352	{
353	    proxy_conn_t* conn = proxy_conn_open(
354	        AGENT_LLM_OPENROUTER_HOST, 443, 30000);
355	
356	    if (!conn) {
357	        printf("Error: proxy connection failed\n");
358	        return ERROR;
359	    }
360	
361	    char hdr[512];
362	    int hlen = snprintf(hdr, sizeof(hdr),
363	        "GET %s HTTP/1.1\r\n"
364	        "Host: %s\r\n"
365	        "Authorization: Bearer %s\r\n"
366	        "Accept: application/json\r\n"
367	        "Connection: close\r\n\r\n",
368	        LIST_MODELS_PATH, AGENT_LLM_OPENROUTER_HOST, api_key);
369	
370	    if (proxy_conn_write(conn, hdr, hlen) < 0) {
371	        proxy_conn_close(conn);
372	        printf("Error: write failed\n");
373	        return ERROR;
374	    }
375	
376	    char* buf = malloc(LIST_MODELS_BUF_SIZE);
377	
378	    if (!buf) {
379	        proxy_conn_close(conn);
380	        printf("Error: OOM\n");
381	        return ERROR;
382	    }
383	
384	    size_t total = 0;
385	    char tmp[4096];
386	
387	    while (total < LIST_MODELS_BUF_SIZE - 1) {
388	        int n = proxy_conn_read(conn, tmp, sizeof(tmp), 60000);
389	
390	        if (n <= 0) {
391	            break;
392	        }
393	        size_t avail = LIST_MODELS_BUF_SIZE - 1 - total;
394	        size_t copy = (size_t)n < avail ? (size_t)n : avail;
395	
396	        memcpy(buf + total, tmp, copy);
397	        total += copy;
398	    }
399	    proxy_conn_close(conn);
400	    buf[total] = '\0';
401	
402	    /* Strip HTTP header */
403	    char* body = strstr(buf, "\r\n\r\n");
404	
405	    if (body) {
406	        body += 4;
407	        size_t blen = total - (size_t)(body - buf);
408	        memmove(buf, body, blen);
409	        buf[blen] = '\0';
410	        *out_len = blen;
411	    } else {
412	        *out_len = total;
413	    }
414	
415	    *out = buf;
416	    return OK;
417	}
418	
419	static bool model_is_free(cJSON* item)
420	{
421	    cJSON* pricing = cJSON_GetObjectItem(item, "pricing");
422	
423	    if (!pricing) {
424	        return false;
425	    }
426	
427	    const cJSON* prompt = cJSON_GetObjectItem(pricing, "prompt");
428	    const cJSON* completion = cJSON_GetObjectItem(pricing, "completion");
429	
430	    if (!prompt || !completion) {
431	        return false;
432	    }
433	
434	    const char* p = prompt->valuestring;
435	    const char* c = completion->valuestring;
436	
437	    if (!p || !c) {
438	        return false;
439	    }
440	    return (atof(p) == 0.0 && atof(c) == 0.0);
441	}
442	
443	static void list_models_print(cJSON* data, bool free_only,
444	    const char* keyword)
445	{
446	    int count = 0;
447	    int total = cJSON_GetArraySize(data);
448	
449	    for (int i = 0; i < total; i++) {
450	        cJSON* item = cJSON_GetArrayItem(data, i);
451	        cJSON* id = cJSON_GetObjectItem(item, "id");
452	
453	        if (!id || !id->valuestring) {
454	            continue;
455	        }
456	
457	        bool is_free = model_is_free(item);
458	
459	        if (free_only && !is_free) {
460	            continue;
461	        }
462	        if (keyword && !strstr(id->valuestring, keyword)) {
463	            continue;
464	        }
465	
466	        printf("  %-45s %s\n", id->valuestring,
467	            is_free ? "[FREE]" : "[PAID]");
468	        count++;
469	    }
470	
471	    printf("\n%d model(s) shown (total: %d)\n", count, total);
472	}
