474	void cmd_list_models(int argc, char** argv)
475	{
476	    char host[128];
477	    char api_key[128];
478	
479	    claw_config_get(AGENT_CFG_KEY_LLM_HOST, host, sizeof(host));
480	    claw_config_get(AGENT_CFG_KEY_API_KEY, api_key, sizeof(api_key));
481	
482	    if (!strstr(host, "openrouter.ai")) {
483	        printf("list_models only works with openrouter.ai backend.\n"
484	               "Use: set_llm openrouter\n");
485	        return;
486	    }
487	    if (!api_key[0]) {
488	        printf("No API key set. Use: set_llm <preset> <key>\n");
489	        return;
490	    }
491	
492	    bool free_only = false;
493	    const char* keyword = NULL;
494	
495	    for (int i = 1; i < argc; i++) {
496	        if (strcmp(argv[i], "--free") == 0) {
497	            free_only = true;
498	        } else {
499	            keyword = argv[i];
500	        }
501	    }
502	
503	    printf("Fetching models from %s ...\n", AGENT_LLM_OPENROUTER_HOST);
504	
505	    char* buf;
506	    size_t buf_len;
507	    int ret;
508	
509	    if (http_proxy_is_enabled()) {
510	        ret = list_models_fetch_proxy(api_key, &buf, &buf_len);
511	    } else {
512	        ret = list_models_fetch(api_key, &buf, &buf_len);
513	    }
514	    if (ret != OK) {
515	        return;
516	    }
517	
518	    cJSON* root = cJSON_Parse(buf);
519	
520	    free(buf);
521	    buf = NULL;
522	
523	    if (!root) {
524	        printf("Error: failed to parse JSON response\n");
525	        return;
526	    }
527	
528	    cJSON* data = cJSON_GetObjectItem(root, "data");
529	
530	    if (!data || !cJSON_IsArray(data)) {
531	        printf("Error: unexpected response format\n");
532	        cJSON_Delete(root);
533	        return;
534	    }
535	
536	    list_models_print(data, free_only, keyword);
537	    cJSON_Delete(root);
538	}
