585	void cmd_router_set(int argc, char** argv)
586	{
587	    if (argc < 3) {
588	        printf("Usage: router_set <preset> <api_key>\n\n"
589	               "Presets:\n"
590	               "  deepseek  - DeepSeek (cheap, fast)\n"
591	               "  kimi      - Moonshot Kimi (mid-tier)\n"
592	               "  qwen      - Alibaba Qwen (cheap)\n"
593	               "  glm       - Zhipu GLM-4 (cheap)\n"
594	               "  openai    - OpenAI GPT-4o (premium)\n"
595	               "  claude    - Anthropic Claude (premium)\n"
596	               "  mimo      - Xiaomi MiMo (cheap)\n\n"
597	               "Example:\n"
598	               "  router_set deepseek sk-xxx\n"
599	               "  router_set openai sk-xxx\n");
600	        return;
601	    }
602	
603	    const char* preset_name = argv[1];
604	    const char* api_key = REDACTED
605	    const router_preset_t* preset = NULL;
606	
607	    for (int i = 0; g_router_presets[i].name; i++) {
608	        if (strcmp(g_router_presets[i].name, preset_name) == 0) {
609	            preset = &g_router_presets[i];
610	            break;
611	        }
612	    }
613	
614	    if (!preset) {
615	        printf("Unknown preset: %s\n", preset_name);
616	        return;
617	    }
618	
619	    /* Find first empty slot or reuse existing */
620	    int slot = -1;
621	    for (int i = 0; i < LLM_ROUTER_MAX_BACKENDS; i++) {
622	        llm_backend_t b;
623	        if (llm_router_get_backend(i, &b) != 0 || !b.enabled) {
624	            slot = i;
625	            break;
626	        }
627	        if (strcmp(b.host, preset->host) == 0) {
628	            slot = i; /* Update existing */
629	            break;
630	        }
631	    }
632	
633	    if (slot < 0) {
634	        printf("Error: All 4 slots full. Use router_clear first.\n");
635	        return;
636	    }
637	
638	    llm_backend_t backend = { 0 };
639	    strncpy(backend.host, preset->host, sizeof(backend.host) - 1);
640	    strncpy(backend.path, preset->path, sizeof(backend.path) - 1);
641	    strncpy(backend.port, "443", sizeof(backend.port) - 1);
642	    strncpy(backend.model, preset->model, sizeof(backend.model) - 1);
643	    strncpy(backend.api_key, api_key, sizeof(backend.api_key) - 1);
644	    backend.priority = slot;
645	    backend.cost_tier = preset->cost_tier;
646	    backend.enabled = true;
647	
648	    if (llm_router_set_backend(slot, &backend) == 0) {
649	        printf("Added [%d]: %s (%s, tier=%d)\n",
650	            slot, preset_name, preset->model, preset->cost_tier);
651	    } else {
652	        printf("Failed to add backend.\n");
653	    }
654	}
