656	void cmd_router_clear(int argc, char** argv)
657	{
658	    if (argc >= 2) {
659	        /* Validate numeric input */
660	        const char* arg = argv[1];
661	        if (arg[0] < '0' || arg[0] > '9') {
662	            printf("Error: index must be a number (0-%d)\n",
663	                LLM_ROUTER_MAX_BACKENDS - 1);
664	            return;
665	        }
666	        int idx = atoi(arg);
667	        if (idx >= 0 && idx < LLM_ROUTER_MAX_BACKENDS) {
668	            llm_backend_t empty = { 0 };
669	            llm_router_set_backend(idx, &empty);
670	            printf("Slot %d cleared.\n", idx);
671	        } else {
672	            printf("Error: index must be 0-%d\n", LLM_ROUTER_MAX_BACKENDS - 1);
673	        }
674	    } else {
675	        for (int i = 0; i < LLM_ROUTER_MAX_BACKENDS; i++) {
676	            llm_backend_t empty = { 0 };
677	            llm_router_set_backend(i, &empty);
678	        }
679	        printf("All router backends cleared.\n");
680	    }
681	}
