683	void cmd_router_model(int argc, char** argv)
684	{
685	    if (argc < 3) {
686	        printf("Usage: router_model <index> <model_name>\n"
687	               "Example: router_model 1 gpt-4o-mini\n");
688	        return;
689	    }
