692	    if (idx < 0 || idx >= LLM_ROUTER_MAX_BACKENDS) {
693	        printf("Error: index must be 0-%d\n", LLM_ROUTER_MAX_BACKENDS - 1);
694	        return;
695	    }
696	
697	    llm_backend_t b;
