17	#include "channels/feishu_internal.h"
18	#include "infra/config_store.h"
19	#include "cJSON.h"
20	
21	#include <fcntl.h>
22	#include <semaphore.h>
23	#include <stdlib.h>
24	#include <string.h>
25	#include <time.h>
26	#include <unistd.h>
27	
28	static const char* TAG = "feishu";
29	
30	/* ── Shared state definitions (extern'd in feishu_internal.h) ──── */
31	
32	char s_app_id[64] = AGENT_SECRET_FEISHU_APP_ID;
33	char s_app_secret[64] = AGENT_SECRET_FEISHU_APP_SECRET;
34	char s_access_token[512] = { 0 };
35	char s_user_token[512] = { 0 };
36	char s_bot_open_id[64] = { 0 };
37	int64_t s_token_expire_ts = 0;
38	feishu_ws_t s_ws;
39	mbedtls_ctr_drbg_context s_ctr_drbg;
40	bool s_rng_ready = false;
41	
42	static sem_t s_cred_sem;
43	
44	/* ── Simple entropy function (works on NuttX/QEMU) ─────────────── */
45	
46	static int simple_entropy_func(void* data, unsigned char* output, size_t len)
47	{
48	    (void)data;
49	    if (agent_secure_random(output, len) == 0) {
50	        return 0;
51	    }
52	    syslog(LOG_ERR, "[feishu] CRITICAL: No secure entropy source available\n");
53	    return -1;  /* Generic error - TLS handshake will fail safely */
54	}
55	
56	/* ── Background polling task ─────────────────────────────────── */
57	
58	static void* feishu_poll_task(void* arg)
59	{
60	    (void)arg;
61	    syslog(LOG_INFO, "[%s] Feishu polling task started\n", TAG);
62	
63	    const size_t frame_buf_size = 65536;
64	    uint8_t* frame_buf = malloc(frame_buf_size);
65	
66	    if (!frame_buf) {
67	        syslog(LOG_ERR, "[%s] OOM for frame_buf\n", TAG);
68	        return NULL;
69	    }
70	
71	    char* ws_host = malloc(128);
72	    char* ws_path = malloc(768);
73	
74	    if (!ws_host || !ws_path) {
75	        syslog(LOG_ERR, "[%s] OOM for ws_host/ws_path\n", TAG);
76	        free(frame_buf);
77	        free(ws_host);
78	        free(ws_path);
79	        return NULL;
80	    }
81	
82	    int32_t svc_id = 0;
83	
84	    while (1) {
85	        /* Credentials check */
86	        if (s_app_id[0] == '\0' || s_app_secret[0] == '\0') {
87	            static int s_no_cred_logged = 0;
88	            if (!s_no_cred_logged) {
89	                syslog(LOG_WARNING,
90	                    "[%s] No app_id/app_secret. Use: "
91	                    "set_feishu_app <id> <secret>\n", TAG);
92	                s_no_cred_logged = 1;
93	            }
94	            struct timespec ts;
95	            clock_gettime(CLOCK_REALTIME, &ts);
96	            ts.tv_sec += 60;
97	            sem_timedwait(&s_cred_sem, &ts);
98	            continue;
99	        }
100	
101	        /* Refresh access token */
102	        if (feishu_token_expired()) {
103	            if (feishu_get_app_token() != OK) {
104	                syslog(LOG_WARNING, "[%s] Token refresh failed; retry in 30s\n", TAG);
105	                sleep(30);
106	                continue;
107	            }
108	        }
109	
110	        /* Get WS endpoint */
111	        memset(ws_host, 0, 128);
112	        memset(ws_path, 0, 768);
113	        if (feishu_create_connection(ws_host, 128, ws_path, 768) != OK) {
114	            syslog(LOG_WARNING, "[%s] create_connection failed; retry in 10s\n", TAG);
115	            sleep(10);
116	            continue;
117	        }
118	
119	        /* Extract service_id from path query string */
120	        svc_id = 0;
121	        const char* sid_p = strstr(ws_path, "service_id=");
122	        if (sid_p) {
123	            svc_id = (int32_t)atol(sid_p + 11);
124	        }
125	
126	        /* WebSocket connect */
127	        ws_free(&s_ws);
128	        if (ws_connect(&s_ws, ws_host, ws_path, s_access_token) != 0) {
129	            syslog(LOG_WARNING, "[%s] ws_connect failed; retry in 10s\n", TAG);
130	            sleep(10);
131	            continue;
132	        }
133	
134	        /* Event receive loop */
135	        syslog(LOG_INFO, "[%s] Feishu Event Streaming active (svc_id=%ld)\n",
136	            TAG, (long)svc_id);
137	
138	        while (s_ws.connected) {
139	            uint8_t opcode = 0;
140	            int n = ws_recv_frame(&s_ws, &opcode, (char*)frame_buf, frame_buf_size);
141	
142	            if (n < 0) {
143	                if (feishu_token_expired()) {
144	                    break;
145	                }
146	                /* Socket timeout → send protobuf ping */
147	                if (svc_id) {
148	                    static uint8_t ping_buf[128];
149	                    int plen = fk_encode_ping(ping_buf, sizeof(ping_buf), svc_id);
150	                    if (plen > 0) {
151	                        ws_send_frame(&s_ws, 0x02, (const char*)ping_buf, (size_t)plen);
152	                    }
153	                } else {
154	                    ws_send_frame(&s_ws, 0x09, NULL, 0);
155	                }
156	                continue;
157	            }
158	
159	            switch (opcode) {
160	            case 0x02: /* binary frame — protobuf pbbp2 */
161	                feishu_process_binary_frame(frame_buf, n, svc_id);
162	                break;
163	            case 0x01: /* text frame — unexpected */
164	                frame_buf[n < (int)frame_buf_size - 1 ? n : (int)frame_buf_size - 1] = 0;
165	                syslog(LOG_WARNING, "[%s] Text WS frame (unexpected): %.80s\n",
166	                    TAG, (char*)frame_buf);
167	                break;
168	            case 0x09: /* WS ping → pong */
169	                ws_send_frame(&s_ws, 0x0A, (const char*)frame_buf, (size_t)n);
170	                break;
171	            case 0x08: /* WS close */
172	                syslog(LOG_INFO, "[%s] Server WS close; reconnecting\n", TAG);
173	                s_ws.connected = false;
174	                break;
175	            default:
176	                break;
177	            }
178	        }
179	
180	        ws_free(&s_ws);
181	        syslog(LOG_WARNING, "[%s] WS disconnected; reconnecting in 5s\n", TAG);
182	        sleep(5);
183	    }
184	
185	    return NULL;
186	}
187	
188	/* ── Public API ──────────────────────────────────────────────── */
189	
190	int feishu_bot_init(void)
191	{
192	    memset(&s_ws, 0, sizeof(s_ws));
193	    mbedtls_net_init(&s_ws.net);
194	    sem_init(&s_cred_sem, 0, 0);
195	
196	    /* Initialize RNG */
197	    if (!s_rng_ready) {
198	        mbedtls_ctr_drbg_init(&s_ctr_drbg);
199	        int ret = mbedtls_ctr_drbg_seed(&s_ctr_drbg, simple_entropy_func, NULL,
