16	
17	#include "channels/feishu_internal.h"
18	#include "infra/http_proxy.h"
19	
20	#include <stdlib.h>
21	#include <string.h>
22	#include <unistd.h>
23	#include <sys/socket.h>
24	
25	#include "mbedtls/base64.h"
26	
27	static const char* TAG = "feishu_ws";
28	
29	/* ── Low-level TLS helpers ──────────────────────────────────── */
30	
31	void ws_free(feishu_ws_t* ws)
32	{
33	    if (ws->connected) {
34	        mbedtls_ssl_close_notify(&ws->ssl);
35	    }
36	    mbedtls_ssl_free(&ws->ssl);
37	    mbedtls_ssl_config_free(&ws->conf);
38	
39	    if (ws->net.fd >= 0) {
40	        close(ws->net.fd);
41	        ws->net.fd = -1;
42	    }
43	
44	    mbedtls_net_init(&ws->net);
45	    mbedtls_ssl_init(&ws->ssl);
46	    mbedtls_ssl_config_init(&ws->conf);
47	    ws->connected = false;
48	}
49	
50	/* Read exactly `len` bytes from TLS stream; returns -1 on error. */
51	static int ws_read_exact(feishu_ws_t* ws, uint8_t* buf, size_t len)
52	{
53	    size_t total = 0;
54	
55	    while (total < len) {
56	        int n = mbedtls_ssl_read(&ws->ssl, buf + total, len - total);
57	        if (n == MBEDTLS_ERR_SSL_WANT_READ) {
58	            continue;
59	        }
60	        if (n <= 0) {
61	            return -1;
62	        }
63	        total += (size_t)n;
64	    }
65	    return (int)total;
66	}
67	
68	/* Write `len` bytes to TLS stream; returns -1 on error. */
69	static int ws_write_all(feishu_ws_t* ws, const uint8_t* buf, size_t len)
70	{
71	    size_t written = 0;
72	
73	    while (written < len) {
74	        int n = mbedtls_ssl_write(&ws->ssl, buf + written, len - written);
75	        if (n == MBEDTLS_ERR_SSL_WANT_WRITE) {
76	            continue;
77	        }
78	        if (n <= 0) {
79	            return -1;
80	        }
81	        written += (size_t)n;
82	    }
83	    return (int)written;
84	}
85	
86	/* ── WebSocket handshake ─────────────────────────────────────── */
87	
88	int ws_connect(feishu_ws_t* ws, const char* host, const char* path,
89	    const char* token)
90	{
91	    mbedtls_net_init(&ws->net);
92	    mbedtls_ssl_init(&ws->ssl);
93	    mbedtls_ssl_config_init(&ws->conf);
94	
95	    if (!s_rng_ready) {
96	        syslog(LOG_ERR, "[%s] ws_connect: RNG not initialised\n", TAG);
97	        goto fail;
98	    }
99	
100	    int ret;
101	
102	    /* TCP connect — via proxy tunnel if configured, direct otherwise */
103	    if (http_proxy_is_enabled()) {
104	        int sock = proxy_open_tunnel(host, 443, 30000);
105	        if (sock < 0) {
106	            syslog(LOG_ERR, "[%s] proxy_open_tunnel %s:443 failed\n", TAG, host);
107	            goto fail;
108	        }
109	        ws->net.fd = sock;
110	    } else {
111	        ret = mbedtls_net_connect(&ws->net, host, "443", MBEDTLS_NET_PROTO_TCP);
112	        if (ret != 0) {
113	            syslog(LOG_ERR, "[%s] net_connect %s: -0x%04x\n", TAG, host, -ret);
114	            goto fail;
115	        }
116	    }
117	
118	    mbedtls_net_set_block(&ws->net);
119	    {
120	        struct timeval tv = { .tv_sec = 90, .tv_usec = 0 };
121	        setsockopt(ws->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
122	    }
123	
124	    /* TLS configuration */
125	    ret = mbedtls_ssl_config_defaults(&ws->conf, MBEDTLS_SSL_IS_CLIENT,
126	        MBEDTLS_SSL_TRANSPORT_STREAM, MBEDTLS_SSL_PRESET_DEFAULT);
127	    if (ret != 0) {
128	        syslog(LOG_ERR, "[%s] ssl_config_defaults: -0x%04x\n", TAG, -ret);
129	        goto fail;
130	    }
131	
132	    mbedtls_ssl_conf_min_tls_version(&ws->conf, MBEDTLS_SSL_VERSION_TLS1_2);
133	#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
134	    mbedtls_ssl_conf_max_tls_version(&ws->conf, MBEDTLS_SSL_VERSION_TLS1_3);
135	#else
136	    mbedtls_ssl_conf_max_tls_version(&ws->conf, MBEDTLS_SSL_VERSION_TLS1_2);
137	#endif
138	
139	#if defined(MBEDTLS_SSL_ALPN)
140	    {
141	        static const char* alpn_protos[] = { "http/1.1", NULL };
142	        ret = mbedtls_ssl_conf_alpn_protocols(&ws->conf, alpn_protos);
143	        if (ret != 0) {
144	            syslog(LOG_WARNING, "[%s] alpn_protocols: -0x%04x (non-fatal)\n",
145	                TAG, -ret);
146	        }
147	    }
148	#endif
149	
150	    mbedtls_ssl_conf_authmode(&ws->conf, MBEDTLS_SSL_VERIFY_OPTIONAL);
151	    mbedtls_ssl_conf_rng(&ws->conf, mbedtls_ctr_drbg_random, &s_ctr_drbg);
152	
153	    ret = mbedtls_ssl_setup(&ws->ssl, &ws->conf);
154	    if (ret != 0) {
155	        syslog(LOG_ERR, "[%s] ssl_setup: -0x%04x\n", TAG, -ret);
156	        goto fail;
157	    }
158	
159	    mbedtls_ssl_set_hostname(&ws->ssl, host);
160	    mbedtls_ssl_set_bio(&ws->ssl, &ws->net, mbedtls_net_send, mbedtls_net_recv,
161	        NULL);
162	
163	    /* TLS handshake */
164	    while ((ret = mbedtls_ssl_handshake(&ws->ssl)) != 0) {
165	        if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
166	            ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
167	            syslog(LOG_ERR, "[%s] ssl_handshake: -0x%04x\n", TAG, -ret);
168	            goto fail;
169	        }
170	    }
171	
172	    /* ── WebSocket upgrade ──────────────────────────────────── */
173	    uint8_t raw_key[16];
174	
175	    ret = mbedtls_ctr_drbg_random(&s_ctr_drbg, raw_key, sizeof(raw_key));
176	    if (ret != 0) {
177	        syslog(LOG_ERR, "[%s] ctr_drbg_random for ws key: REDACTED\n", TAG, -ret);
178	        goto fail;
179	    }
180	
181	    unsigned char b64_key[32] = { 0 };
182	    size_t b64_len = 0;
183	
184	    mbedtls_base64_encode(b64_key, sizeof(b64_key) - 1, &b64_len, raw_key, 16);
185	    b64_key[b64_len] = '\0';
186	
187	    char* req = malloc(2048);
188	
189	    if (!req) {
190	        syslog(LOG_ERR, "[%s] OOM for WS req\n", TAG);
191	        goto fail;
192	    }
193	
194	    int rlen = snprintf(req, 2048,
195	        "GET %s HTTP/1.1\r\n"
196	        "Host: %s\r\n"
197	        "Upgrade: websocket\r\n"
198	        "Connection: Upgrade\r\n"
199	        "Sec-WebSocket-Key: REDACTED\r\n"
200	        "Sec-WebSocket-Version: 13\r\n"
201	        "Authorization: Bearer %s\r\n"
202	        "\r\n",
203	        path, host, (char*)b64_key, token);
204	
205	    if (ws_write_all(ws, (uint8_t*)req, rlen) < 0) {
206	        syslog(LOG_ERR, "[%s] ws upgrade write error\n", TAG);
207	        free(req);
208	        goto fail;
209	    }
210	    free(req);
211	
212	    /* Read upgrade response until \r\n\r\n */
213	    char* resp = malloc(2048);
214	
215	    if (!resp) {
216	        syslog(LOG_ERR, "[%s] OOM for WS resp\n", TAG);
217	        goto fail;
218	    }
219	    memset(resp, 0, 2048);
220	    int resp_len = 0;
221	    uint8_t ch;
222	
223	    while (resp_len < 2048 - 1) {
224	        if (ws_read_exact(ws, &ch, 1) < 0) {
225	            free(resp);
226	            goto fail;
227	        }
228	        resp[resp_len++] = (char)ch;
229	        if (resp_len >= 4 && memcmp(resp + resp_len - 4, "\r\n\r\n", 4) == 0) {
230	            break;
231	        }
232	    }
233	    resp[resp_len] = '\0';
234	
235	    if (!strstr(resp, " 101 ")) {
236	        syslog(LOG_ERR, "[%s] WS upgrade failed (no 101): %.160s\n", TAG, resp);
237	        free(resp);
238	        goto fail;
239	    }
240	    free(resp);
241	
242	    ws->connected = true;
243	    syslog(LOG_INFO, "[%s] WebSocket connected to wss://%s%s\n", TAG, host, path);
244	    return 0;
245	
246	fail:
247	    ws_free(ws);
248	    return -1;
249	}
250	
251	/* ── WebSocket frame I/O ─────────────────────────────────────── */
252	
253	int ws_send_frame(feishu_ws_t* ws, uint8_t opcode, const void* data, size_t len)
254	{
255	    if (!ws->connected) {
256	        return -1;
257	    }
258	
259	    uint8_t header[14];
260	    int hlen = 0;
261	
262	    header[hlen++] = (uint8_t)(0x80 | (opcode & 0x0F)); /* FIN=1 */
263	
264	    if (len < 126) {
265	        header[hlen++] = (uint8_t)(0x80 | len); /* MASK=1 */
266	    } else if (len < 65536) {
267	        header[hlen++] = (uint8_t)(0x80 | 126);
268	        header[hlen++] = (uint8_t)((len >> 8) & 0xFF);
269	        header[hlen++] = (uint8_t)(len & 0xFF);
270	    } else {
271	        header[hlen++] = (uint8_t)(0x80 | 127);
272	        for (int i = 7; i >= 0; i--) {
273	            header[hlen++] = (uint8_t)((len >> (i * 8)) & 0xFF);
274	        }
275	    }
276	
277	    /* Masking key */
278	    uint8_t mask[4];
279	
280	    mask[0] = (uint8_t)(rand() & 0xFF);
281	    mask[1] = (uint8_t)(rand() & 0xFF);
282	    mask[2] = (uint8_t)(rand() & 0xFF);
283	    mask[3] = (uint8_t)(rand() & 0xFF);
284	    header[hlen++] = mask[0];
285	    header[hlen++] = mask[1];
286	    header[hlen++] = mask[2];
287	    header[hlen++] = mask[3];
288	
289	    if (ws_write_all(ws, header, hlen) < 0) {
290	        return -1;
291	    }
292	
293	    /* Send masked payload in 256-byte chunks */
294	    const uint8_t* src = (const uint8_t*)data;
295	    uint8_t chunk[256];
296	
297	    for (size_t offset = 0; offset < len;) {
298	        size_t todo = len - offset;
299	        if (todo > sizeof(chunk)) {
300	            todo = sizeof(chunk);
301	        }
302	        for (size_t i = 0; i < todo; i++) {
303	            chunk[i] = src[offset + i] ^ mask[(offset + i) & 3];
304	        }
305	        if (ws_write_all(ws, chunk, todo) < 0) {
306	            return -1;
307	        }
308	        offset += todo;
309	    }
310	    return 0;
311	}
