19	#include <stdlib.h>
20	#include <string.h>
21	
22	/* ── Minimal protobuf decoder/encoder for Feishu pbbp2 frames ── */
23	/*
24	 * Frame struct (from pbbp2.proto):
25	 *   SeqID    uint64 field=1
26	 *   LogID    uint64 field=2
27	 *   service  int32  field=3
28	 *   method   int32  field=4  (0=control, 1=data)
29	 *   headers  Header field=5  (repeated)
30	 *   payload_encoding string field=6
31	 *   payload_type     string field=7
32	 *   payload  bytes  field=8
33	 *
34	 * Header: key string field=1, value string field=2
35	 */
36	
37	static uint64_t pb_read_varint(const uint8_t* buf, int* pos, int len)
38	{
39	    uint64_t v = 0;
40	    int s = 0;
41	
42	    while (*pos < len) {
43	        uint8_t b = buf[(*pos)++];
44	        v |= (uint64_t)(b & 0x7f) << s;
45	        if (!(b & 0x80)) {
46	            break;
47	        }
48	        s += 7;
49	    }
50	    return v;
51	}
52	
53	static void pb_skip_field(const uint8_t* buf, int* pos, int len, int wtype)
54	{
55	    switch (wtype) {
56	    case 0:
57	        pb_read_varint(buf, pos, len);
58	        break;
59	    case 1:
60	        *pos += 8;
61	        break;
62	    case 2: {
63	        int n = (int)pb_read_varint(buf, pos, len);
64	        if (n > 0 && *pos + n <= len) {
65	            *pos += n;
66	        }
67	        break;
68	    }
69	    case 5:
70	        *pos += 4;
71	        break;
72	    default:
73	        break;
74	    }
75	}
76	
77	static void pb_decode_header_msg(const uint8_t* buf, int len, fk_frame_t* f)
78	{
79	    char key[32] = { 0 };
80	    char val[128] = { 0 };
81	    int i = 0;
82	
83	    while (i < len) {
84	        uint64_t tag = pb_read_varint(buf, &i, len);
85	        int fn = (int)(tag >> 3);
86	        int wt = (int)(tag & 7);
87	
88	        if (wt == 2) {
89	            int slen = (int)pb_read_varint(buf, &i, len);
90	            if (slen < 0 || i + slen > len) {
91	                break;
92	            }
93	            if (fn == 1) {
94	                int n = slen < 31 ? slen : 31;
95	                memcpy(key, buf + i, n);
96	                key[n] = 0;
97	            } else if (fn == 2) {
98	                int n = slen < 127 ? slen : 127;
99	                memcpy(val, buf + i, n);
100	                val[n] = 0;
101	            }
102	            i += slen;
103	        } else {
104	            pb_skip_field(buf, &i, len, wt);
105	        }
106	    }
107	
108	    if (!strcmp(key, "type")) {
109	        strncpy(f->h_type, val, sizeof(f->h_type) - 1);
110	    } else if (!strcmp(key, "message_id")) {
111	        strncpy(f->h_msg_id, val, sizeof(f->h_msg_id) - 1);
112	    } else if (!strcmp(key, "trace_id")) {
113	        strncpy(f->h_trace_id, val, sizeof(f->h_trace_id) - 1);
114	    } else if (!strcmp(key, "sum")) {
115	        f->h_sum = atoi(val);
116	    } else if (!strcmp(key, "seq")) {
117	        f->h_seq = atoi(val);
118	    }
119	}
120	
121	int pb_decode_frame(const uint8_t* buf, int len, fk_frame_t* f)
122	{
123	    memset(f, 0, sizeof(*f));
124	    int i = 0;
125	
126	    while (i < len) {
127	        uint64_t tag = pb_read_varint(buf, &i, len);
128	        int fn = (int)(tag >> 3);
129	        int wt = (int)(tag & 7);
130	
131	        switch (fn) {
132	        case 1:
133	            f->seq_id = pb_read_varint(buf, &i, len);
134	            break;
135	        case 2:
136	            pb_read_varint(buf, &i, len);
137	            break; /* LogID */
138	        case 3:
139	            f->service = (int32_t)pb_read_varint(buf, &i, len);
140	            break;
141	        case 4:
142	            f->method = (int32_t)pb_read_varint(buf, &i, len);
143	            break;
144	        case 5: { /* repeated Header sub-message */
145	            if (wt != 2) {
146	                pb_skip_field(buf, &i, len, wt);
147	                break;
148	            }
149	            int mlen = (int)pb_read_varint(buf, &i, len);
150	            if (mlen < 0 || i + mlen > len) {
151	                return -1;
152	            }
153	            pb_decode_header_msg(buf + i, mlen, f);
154	            i += mlen;
155	            break;
156	        }
157	        case 8: { /* payload bytes */
158	            if (wt != 2) {
159	                pb_skip_field(buf, &i, len, wt);
160	                break;
161	            }
162	            int plen = (int)pb_read_varint(buf, &i, len);
163	            if (plen < 0 || i + plen > len) {
164	                return -1;
165	            }
166	            f->payload = buf + i;
167	            f->payload_len = plen;
168	            i += plen;
169	            break;
170	        }
171	        default:
172	            pb_skip_field(buf, &i, len, wt);
173	            break;
174	        }
175	    }
176	    return 0;
177	}
178	
179	/* --- Encoder --- */
180	
181	static int pb_put_varint(uint8_t* buf, int pos, int cap, uint64_t v)
182	{
183	    do {
184	        if (pos >= cap) {
185	            return -1;
186	        }
187	        buf[pos++] = (v > 0x7f) ? (uint8_t)((v & 0x7f) | 0x80) : (uint8_t)v;
188	        v >>= 7;
189	    } while (v);
190	    return pos;
191	}
192	
193	int pb_put_len_field(uint8_t* buf, int pos, int cap, int fnum,
194	    const void* data, int dlen)
195	{
196	    pos = pb_put_varint(buf, pos, cap, ((uint64_t)fnum << 3) | 2);
197	    if (pos < 0) {
198	        return -1;
199	    }
200	    pos = pb_put_varint(buf, pos, cap, (uint64_t)dlen);
201	    if (pos < 0 || pos + dlen > cap) {
202	        return -1;
203	    }
204	    if (data && dlen > 0) {
205	        memcpy(buf + pos, data, dlen);
206	    }
207	    return pos + dlen;
208	}
209	
210	int pb_put_varint_field(uint8_t* buf, int pos, int cap, int fnum, uint64_t v)
211	{
212	    pos = pb_put_varint(buf, pos, cap, (uint64_t)fnum << 3); /* wire type 0 */
213	    if (pos < 0) {
214	        return -1;
215	    }
216	    return pb_put_varint(buf, pos, cap, v);
217	}
218	
219	int pb_encode_header_entry(uint8_t* buf, int pos, int cap,
220	    const char* key, const char* val)
221	{
222	    uint8_t tmp[256];
223	    int tp = 0;
224	
225	    tp = pb_put_len_field(tmp, tp, 256, 1, key, (int)strlen(key));
226	    if (tp < 0) {
227	        return -1;
228	    }
229	    tp = pb_put_len_field(tmp, tp, 256, 2, val, (int)strlen(val));
230	    if (tp < 0) {
231	        return -1;
232	    }
233	    return pb_put_len_field(buf, pos, cap, 5, tmp, tp);
234	}
235	
236	/* ACK response for an incoming data frame */
237	int fk_encode_ack(uint8_t* out, int cap, const fk_frame_t* req)
238	{
239	    static const char ack_pl[] = "{\"code\":200}";
240	    int p = 0;
241	
242	    p = pb_put_varint_field(out, p, cap, 1, req->seq_id);
243	    if (p < 0) {
244	        return -1;
245	    }
246	    p = pb_put_varint_field(out, p, cap, 2, 0);
247	    if (p < 0) {
248	        return -1;
249	    }
250	    p = pb_put_varint_field(out, p, cap, 3, (uint32_t)req->service);
251	    if (p < 0) {
252	        return -1;
253	    }
254	    p = pb_put_varint_field(out, p, cap, 4, (uint32_t)req->method);
255	    if (p < 0) {
256	        return -1;
257	    }
258	    p = pb_encode_header_entry(out, p, cap, "type", "ack");
259	    if (p < 0) {
260	        return -1;
261	    }
262	    if (req->h_msg_id[0]) {
263	        p = pb_encode_header_entry(out, p, cap, "message_id", req->h_msg_id);
264	        if (p < 0) {
265	            return -1;
266	        }
267	    }
268	    if (req->h_trace_id[0]) {
269	        p = pb_encode_header_entry(out, p, cap, "trace_id", req->h_trace_id);
270	        if (p < 0) {
271	            return -1;
272	        }
273	    }
274	    p = pb_put_len_field(out, p, cap, 8, ack_pl, (int)strlen(ack_pl));
275	    return p;
276	}
277	
278	/* Protobuf ping frame (sent periodically to keep connection alive) */
279	int fk_encode_ping(uint8_t* out, int cap, int32_t svc_id)
280	{
281	    static uint64_t ping_seq = 1;
282	    int p = 0;
283	
284	    p = pb_put_varint_field(out, p, cap, 1, ping_seq++);
285	    if (p < 0) {
286	        return -1;
287	    }
288	    p = pb_put_varint_field(out, p, cap, 2, 0);
289	    if (p < 0) {
290	        return -1;
291	    }
292	    p = pb_put_varint_field(out, p, cap, 3, (uint32_t)svc_id);
293	    if (p < 0) {
294	        return -1;
295	    }
296	    p = pb_put_varint_field(out, p, cap, 4, 0); /* control */
297	    if (p < 0) {
298	        return -1;
299	    }
300	    p = pb_encode_header_entry(out, p, cap, "type", "ping");
