26	
27	/* ── Message deduplication ring buffer ─────────────────────────── */
28	
29	#define DEDUP_RING_SIZE 16
30	#define CONTENT_DEDUP_WINDOW_MS 120000 /* 120 seconds window for content dedup */
31	
32	static char s_dedup_ring[DEDUP_RING_SIZE][64];
33	static int s_dedup_idx = 0;
34	
35	/* Content-based dedup: (chat_id hash + content hash + timestamp) */
36	typedef struct {
37	    uint32_t hash;
38	    uint32_t timestamp; /* UNIX epoch seconds */
39	} content_dedup_entry_t;
40	
41	static content_dedup_entry_t s_content_dedup[DEDUP_RING_SIZE];
42	static int s_content_dedup_idx = 0;
43	
44	/* Feishu message_id dedup ring (om_xxx is stable across event retries) */
45	static char s_msgid_ring[DEDUP_RING_SIZE][64];
46	static int s_msgid_idx = 0;
47	
48	/* ── Bot-to-bot ping-pong rate limiter ───────────────────────── */
49	
50	#define BOT_RATE_SLOTS    8
51	#define BOT_RATE_MAX      2   /* max bot msgs per chat within window */
52	#define BOT_RATE_WINDOW_S 120 /* seconds */
53	
54	typedef struct {
55	    char chat_id[64];
56	    uint32_t timestamps[BOT_RATE_MAX];
57	    int idx;
58	} bot_rate_entry_t;
59	
60	static bot_rate_entry_t s_bot_rate[BOT_RATE_SLOTS];
61	
62	/* ── Dedup helper functions ────────────────────────────────────── */
63	
64	static bool dedup_check_and_record(const char* msg_id)
65	{
66	    if (!msg_id || msg_id[0] == '\0') {
67	        return false;
68	    }
69	
70	    for (int i = 0; i < DEDUP_RING_SIZE; i++) {
71	        if (s_dedup_ring[i][0] && strcmp(s_dedup_ring[i], msg_id) == 0) {
72	            return true;
73	        }
74	    }
75	
76	    strncpy(s_dedup_ring[s_dedup_idx], msg_id, sizeof(s_dedup_ring[0]) - 1);
77	    s_dedup_ring[s_dedup_idx][sizeof(s_dedup_ring[0]) - 1] = '\0';
78	    s_dedup_idx = (s_dedup_idx + 1) % DEDUP_RING_SIZE;
79	    return false;
80	}
81	
82	static bool msgid_dedup_check(const char* msg_id)
83	{
84	    if (!msg_id || !msg_id[0]) {
85	        return false;
86	    }
87	    for (int i = 0; i < DEDUP_RING_SIZE; i++) {
88	        if (s_msgid_ring[i][0] && strcmp(s_msgid_ring[i], msg_id) == 0) {
89	            return true;
90	        }
91	    }
92	    strncpy(s_msgid_ring[s_msgid_idx], msg_id, sizeof(s_msgid_ring[0]) - 1);
93	    s_msgid_ring[s_msgid_idx][sizeof(s_msgid_ring[0]) - 1] = '\0';
94	    s_msgid_idx = (s_msgid_idx + 1) % DEDUP_RING_SIZE;
95	    return false;
96	}
97	
98	static uint32_t simple_hash(const char* chat_id, const char* content)
99	{
100	    uint32_t h = 5381;
101	
102	    if (chat_id) {
103	        for (const char* p = chat_id; *p; p++) {
104	            h = ((h << 5) + h) ^ (uint8_t)*p;
105	        }
106	    }
107	    if (content) {
108	        for (const char* p = content; *p; p++) {
109	            h = ((h << 5) + h) ^ (uint8_t)*p;
110	        }
111	    }
112	    return h;
113	}
114	
115	static bool content_dedup_check(const char* chat_id, const char* content)
116	{
117	    uint32_t hash = simple_hash(chat_id, content);
118	    uint32_t now = (uint32_t)time(NULL);
119	    uint32_t window_sec = CONTENT_DEDUP_WINDOW_MS / 1000;
120	
121	    for (int i = 0; i < DEDUP_RING_SIZE; i++) {
122	        if (s_content_dedup[i].hash == hash && s_content_dedup[i].timestamp > 0) {
123	            uint32_t age = now - s_content_dedup[i].timestamp;
124	            if (age < window_sec) {
125	                syslog(LOG_WARNING, "[%s] Duplicate content within %lus, skipping\n",
126	                    TAG, (unsigned long)age);
127	                return true;
128	            }
129	        }
130	    }
131	
132	    s_content_dedup[s_content_dedup_idx].hash = hash;
133	    s_content_dedup[s_content_dedup_idx].timestamp = now;
134	    s_content_dedup_idx = (s_content_dedup_idx + 1) % DEDUP_RING_SIZE;
135	    return false;
136	}
