138	static bool bot_rate_limited(const char* chat_id)
139	{
140	    uint32_t now = (uint32_t)time(NULL);
141	    bot_rate_entry_t* slot = NULL;
142	
143	    for (int i = 0; i < BOT_RATE_SLOTS; i++) {
144	        if (s_bot_rate[i].chat_id[0] &&
145	            strcmp(s_bot_rate[i].chat_id, chat_id) == 0) {
146	            slot = &s_bot_rate[i];
147	            break;
148	        }
149	    }
150	
151	    if (!slot) {
152	        uint32_t oldest = UINT32_MAX;
153	        int oldest_i = 0;
154	
155	        for (int i = 0; i < BOT_RATE_SLOTS; i++) {
156	            if (!s_bot_rate[i].chat_id[0]) {
157	                oldest_i = i;
158	                break;
159	            }
160	            uint32_t ts = s_bot_rate[i].timestamps[0];
161	            for (int j = 1; j < BOT_RATE_MAX; j++) {
162	                if (s_bot_rate[i].timestamps[j] < ts) {
163	                    ts = s_bot_rate[i].timestamps[j];
164	                }
165	            }
166	            if (ts < oldest) {
167	                oldest = ts;
168	                oldest_i = i;
169	            }
170	        }
171	        slot = &s_bot_rate[oldest_i];
172	        memset(slot, 0, sizeof(*slot));
173	        strncpy(slot->chat_id, chat_id, sizeof(slot->chat_id) - 1);
174	    }
175	
176	    int recent = 0;
177	
178	    for (int i = 0; i < BOT_RATE_MAX; i++) {
179	        if (slot->timestamps[i] > 0 &&
180	            (now - slot->timestamps[i]) < BOT_RATE_WINDOW_S) {
181	            recent++;
182	        }
183	    }
184	
185	    if (recent >= BOT_RATE_MAX) {
186	        syslog(LOG_WARNING,
187	            "[%s] Bot rate limit hit for chat %.24s (%d msgs in %ds), dropping\n",
188	            TAG, chat_id, recent, BOT_RATE_WINDOW_S);
189	        return true;
190	    }
191	
192	    slot->timestamps[slot->idx] = now;
193	    slot->idx = (slot->idx + 1) % BOT_RATE_MAX;
194	    return false;
195	}
