198	
199	static bool handle_control_frame(const fk_frame_t* f)
200	{
201	    if (f->method != 0) {
202	        return false;
203	    }
204	
205	    if (strcmp(f->h_type, "pong") == 0) {
206	        syslog(LOG_DEBUG, "[%s] pong received (alive)\n", TAG);
207	        return true;
208	    }
209	
210	    if (strcmp(f->h_type, "ping") == 0) {
211	        syslog(LOG_INFO, "[%s] Control ping (seq=%llu), sending pong ACK\n",
212	            TAG, (unsigned long long)f->seq_id);
213	        uint8_t buf[512];
214	        int p = 0;
215	
216	        p = pb_put_varint_field(buf, p, (int)sizeof(buf), 1, f->seq_id);
217	        if (p >= 0) {
218	            p = pb_put_varint_field(buf, p, (int)sizeof(buf), 2, 0);
219	        }
220	        if (p >= 0) {
221	            p = pb_put_varint_field(buf, p, (int)sizeof(buf), 3,
222	                (uint32_t)f->service);
223	        }
224	        if (p >= 0) {
225	            p = pb_put_varint_field(buf, p, (int)sizeof(buf), 4, 0);
226	        }
227	        if (p >= 0) {
228	            p = pb_encode_header_entry(buf, p, (int)sizeof(buf), "type", "pong");
229	        }
230	        if (p >= 0 && f->payload && f->payload_len > 0) {
231	            p = pb_put_len_field(buf, p, (int)sizeof(buf), 8,
232	                f->payload, f->payload_len);
233	        }
234	        if (p > 0) {
235	            ws_send_frame(&s_ws, 0x02, buf, (size_t)p);
236	        } else {
237	            syslog(LOG_ERR, "[%s] Failed to encode pong frame\n", TAG);
238	        }
239	        return true;
240	    }
241	
242	    syslog(LOG_DEBUG, "[%s] Control frame type=%s (ignored)\n", TAG, f->h_type);
243	    return true;
244	}
