320	static bool validate_image_data(const char* buf, size_t len)
321	{
322	    if (len < 4) {
323	        syslog(LOG_ERR, "[%s] Image too small (%d bytes)\n", TAG, (int)len);
324	        return false;
325	    }
326	
327	    if (buf[0] == '{') {
328	        syslog(LOG_ERR, "[%s] Image API returned JSON error: %.300s\n", TAG, buf);
329	        return false;
330	    }
331	
332	    bool is_jpeg = ((unsigned char)buf[0] == 0xFF &&
333	                    (unsigned char)buf[1] == 0xD8);
334	    bool is_png = ((unsigned char)buf[0] == 0x89 &&
335	                   buf[1] == 'P' && buf[2] == 'N' && buf[3] == 'G');
336	
337	    if (!is_jpeg && !is_png) {
338	        syslog(LOG_ERR,
339	            "[%s] Unsupported image format (magic: 0x%02x%02x%02x%02x)\n", TAG,
340	            (unsigned char)buf[0], (unsigned char)buf[1],
341	            (unsigned char)buf[2], (unsigned char)buf[3]);
342	        return false;
343	    }
344	    return true;
345	}
