347	static int download_feishu_image(const char* message_id, const char* image_key)
348	{
349	    if (feishu_token_expired()) {
350	        if (feishu_get_app_token() != OK) {
351	            syslog(LOG_WARNING,
352	                "[%s] Cannot download image: token refresh failed\n", TAG);
353	            return -1;
354	        }
355	    }
356	
357	    char img_path[512];
358	    snprintf(img_path, sizeof(img_path),
359	        "/open-apis/im/v1/messages/%s/resources/%s?type=image",
360	        message_id, image_key);
361	    syslog(LOG_INFO, "[%s] Downloading image: %s\n", TAG, img_path);
362	
363	    FEISHU_AUTH_HDR(hdrs, s_access_token);
364	
365	    char* img_buf = malloc(AGENT_VISION_MAX_IMAGE_SIZE);
366	    if (!img_buf) {
367	        syslog(LOG_ERR, "[%s] OOM for image download buffer\n", TAG);
368	        return -1;
369	    }
370	
371	    size_t img_len = 0;
372	    int status = feishu_https_request("GET", img_path, hdrs, NULL, 0,
373	        img_buf, AGENT_VISION_MAX_IMAGE_SIZE, &img_len);
374	
375	    if (status != 200) {
376	        syslog(LOG_ERR, "[%s] Image download HTTP %d: %.200s\n",
377	            TAG, status, img_buf);
378	        free(img_buf);
379	        return -1;
380	    }
381	
382	    if (!validate_image_data(img_buf, img_len)) {
383	        free(img_buf);
384	        return -1;
385	    }
386	
387	    FILE* fp = fopen(AGENT_CAPTURE_PATH, "wb");
388	    if (!fp) {
389	        syslog(LOG_ERR, "[%s] Cannot open %s for writing\n",
390	            TAG, AGENT_CAPTURE_PATH);
391	        free(img_buf);
392	        return -1;
393	    }
394	
395	    fwrite(img_buf, 1, img_len, fp);
396	    fclose(fp);
397	    free(img_buf);
398	    syslog(LOG_INFO, "[%s] Image saved to %s (%d bytes)\n",
399	        TAG, AGENT_CAPTURE_PATH, (int)img_len);
400	    return 0;
401	}
