479	static char* extract_post_text(cJSON* cj, char* post_img_key, size_t img_key_cap)
480	{
481	    cJSON* paragraphs = NULL;
482	    cJSON* lang = cJSON_GetObjectItem(cj, "zh_cn");
483	
484	    if (!lang) {
485	        lang = cJSON_GetObjectItem(cj, "en_us");
486	    }
487	    if (lang) {
488	        paragraphs = cJSON_GetObjectItem(lang, "content");
489	    } else {
490	        paragraphs = cJSON_GetObjectItem(cj, "content");
491	    }
492	
493	    if (!paragraphs || !cJSON_IsArray(paragraphs)) {
494	        return NULL;
495	    }
496	
497	    char* buf = calloc(1, 2048);
498	    if (!buf) {
499	        return NULL;
500	    }
501	
502	    size_t off = 0;
503	    cJSON* para;
504	
505	    cJSON_ArrayForEach(para, paragraphs) {
506	        cJSON* elem;
507	        cJSON_ArrayForEach(elem, para) {
508	            const char* tag = cJSON_GetStringValue(
509	                cJSON_GetObjectItem(elem, "tag"));
510	            const char* etxt = cJSON_GetStringValue(
511	                cJSON_GetObjectItem(elem, "text"));
512	            const char* href = cJSON_GetStringValue(
513	                cJSON_GetObjectItem(elem, "href"));
514	
515	            if (etxt && off < 2048 - 2) {
516	                off += snprintf(buf + off, 2048 - off, "%s", etxt);
517	            }
518	            if (href && href[0] && off < 2048 - 4) {
519	                off += snprintf(buf + off, 2048 - off, " %s", href);
520	            }
521	            if (tag && strcmp(tag, "img") == 0 && post_img_key[0] == '\0') {
522	                const char* ik = cJSON_GetStringValue(
523	                    cJSON_GetObjectItem(elem, "image_key"));
524	                if (ik && ik[0]) {
525	                    strncpy(post_img_key, ik, img_key_cap - 1);
526	                }
527	            }
528	        }
529	        if (off < 2048 - 2) {
530	            buf[off++] = '\n';
531	        }
532	    }
533	
534	    if (buf[0]) {
535	        char* result = strdup(buf);
536	        free(buf);
537	        return result;
538	    }
539	    free(buf);
540	    return NULL;
541	}
