576	
577	static char* trim_unicode_whitespace(char* text)
578	{
579	    char* t = text;
580	
581	    while (*t == ' ' || *t == '\n' || *t == '\r' || *t == '\t' ||
582	           ((unsigned char)t[0] == 0xE2 && (unsigned char)t[1] == 0x80 &&
583	            ((unsigned char)t[2] >= 0x8B && (unsigned char)t[2] <= 0x8F)) ||
584	           ((unsigned char)t[0] == 0xEF && (unsigned char)t[1] == 0xBB &&
585	            (unsigned char)t[2] == 0xBF) ||
586	           ((unsigned char)t[0] == 0xC2 && (unsigned char)t[1] == 0xA0)) {
587	        if ((unsigned char)t[0] >= 0xC0) {
588	            t += ((unsigned char)t[0] >= 0xE0 ? 3 : 2);
589	        } else {
590	            t++;
591	        }
592	    }
593	    return t;
594	}
595	
596	static bool validate_text_content(const char* text)
597	{
598	    const char* p = text;
599	    int printable = 0;
600	    int chinese = 0;
601	
602	    while (*p) {
603	        unsigned char c = (unsigned char)*p;
604	        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
605	            (c >= '0' && c <= '9')) {
606	            printable++;
607	        } else if (c >= 0xE4 && c <= 0xE9 && (unsigned char)p[1] >= 0x80) {
608	            chinese++;
609	        } else if (c >= 0xC0 && c < 0xE4) {
610	            printable++;
611	        }
612	        p++;
613	    }
614	
615	    if (printable < 2 && chinese < 1) {
616	        syslog(LOG_WARNING,
617	            "[%s] Content too short or garbled (%d ascii, %d cjk), skipping\n",
618	            TAG, printable, chinese);
619	        return false;
620	    }
621	    return true;
622	}
