627	static void strip_placeholder(char* text, const char* key)
628	{
629	    size_t klen = strlen(key);
630	    char* pos;
631	
632	    while ((pos = strstr(text, key)) != NULL) {
633	        memmove(pos, pos + klen, strlen(pos + klen) + 1);
