636	
637	static void replace_placeholder(char** text_ptr, const char* key, const char* replacement)
638	{
639	    char* text = *text_ptr;
640	    size_t klen = strlen(key);
641	    size_t rlen = strlen(replacement);
642	    char* pos;
643	
644	    while ((pos = strstr(text, key)) != NULL) {
645	        size_t tail_len = strlen(pos + klen);
646	
647	        if (rlen > klen) {
648	            size_t cur_len = strlen(text);
649	            size_t pos_off = pos - text;
650	            char* new_text = realloc(text, cur_len + (rlen - klen) + 1);
651	            if (!new_text) {
652	                break;
653	            }
654	            pos = new_text + pos_off;
655	            text = new_text;
656	        }
657	        memmove(pos + rlen, pos + klen, tail_len + 1);
658	        memcpy(pos, replacement, rlen);
659	    }
660	    *text_ptr = text;
661	}
