713	    char* mention_map, size_t map_cap, size_t* map_off)
714	{
715	    cJSON* key_j = cJSON_GetObjectItem(m_item, "key");
716	    cJSON* name_j = cJSON_GetObjectItem(m_item, "name");
717	    cJSON* id_j = cJSON_GetObjectItem(m_item, "id");
718	
719	    if (!cJSON_IsString(key_j) || !key_j->valuestring[0]) {
720	        return;
721	    }
722	
723	    const char* mention_oid = NULL;
724	    if (cJSON_IsObject(id_j)) {
725	        cJSON* oid = cJSON_GetObjectItem(id_j, "open_id");
726	        if (cJSON_IsString(oid)) {
727	            mention_oid = oid->valuestring;
728	        }
729	    }
730	
731	    const char* key = REDACTED
732	
733	    if (is_bot_self_mention(key, mention_oid)) {
734	        strip_placeholder(*text_ptr, key);
735	        return;
736	    }
737	
738	    const char* display = (cJSON_IsString(name_j) && name_j->valuestring[0])
739	        ? name_j->valuestring : "user";
740	    char repl[128];
741	    snprintf(repl, sizeof(repl), "@%s", display);
742	    replace_placeholder(text_ptr, key, repl);
743	
744	    if (mention_oid && mention_oid[0]) {
745	        *map_off += snprintf(mention_map + *map_off, map_cap - *map_off,
746	            "%s%s=%s", *map_off > 0 ? ", " : "", display, mention_oid);
747	    }
748	}
749	
750	static bool process_group_mentions(cJSON* msg, char** text_ptr)
751	{
752	    cJSON* chat_type_j = cJSON_GetObjectItem(msg, "chat_type");
753	    const char* chat_type = cJSON_IsString(chat_type_j)
754	        ? chat_type_j->valuestring : "p2p";
755	
756	    if (strcmp(chat_type, "group") != 0) {
757	        return false;
758	    }
759	
760	    cJSON* mentions = cJSON_GetObjectItem(msg, "mentions");
761	    if (!cJSON_IsArray(mentions) || cJSON_GetArraySize(mentions) == 0) {
762	        syslog(LOG_DEBUG, "[%s] Group msg without @mention, skipping\n", TAG);
763	        return true;
764	    }
765	
766	    char mention_map[512];
767	    size_t map_off = 0;
768	    mention_map[0] = '\0';
769	
770	    cJSON* m_item;
771	    cJSON_ArrayForEach(m_item, mentions) {
772	        apply_single_mention(m_item, text_ptr, mention_map,
773	            sizeof(mention_map), &map_off);
774	    }
775	
776	    return finalize_mention_text(text_ptr, mention_map);
777	}
778	
779	/* ── Main event processing function ────────────────────────────── */
780	
781	void feishu_process_binary_frame(const uint8_t* data, int len, int32_t svc_id)
782	{
783	    fk_frame_t f;
784	
785	    if (pb_decode_frame(data, len, &f) != 0) {
786	        syslog(LOG_WARNING, "[%s] pb_decode_frame failed\n", TAG);
787	        return;
788	    }
789	
790	    /* Frame-level logging disabled to reduce noise */
791	
792	    if (handle_control_frame(&f)) {
793	        return;
794	    }
795	
796	    if (strcmp(f.h_type, "event") != 0 || !f.payload || f.payload_len <= 0) {
797	        return;
798	    }
799	
800	    send_data_ack(&f);
801	
802	    char* payload_str = malloc((size_t)f.payload_len + 1);
803	    if (!payload_str) {
804	        syslog(LOG_ERR, "[%s] OOM for payload_str (%d bytes)\n", TAG, f.payload_len);
805	        return;
806	    }
807	
808	    memcpy(payload_str, f.payload, f.payload_len);
809	    payload_str[f.payload_len] = '\0';
810	
811	    if (payload_str[0] != '{') {
812	        syslog(LOG_WARNING, "[%s] payload not JSON (starts with 0x%02x), dropping\n",
813	            TAG, (unsigned char)payload_str[0]);
814	        free(payload_str);
815	        return;
816	    }
817	
818	    cJSON* root = cJSON_Parse(payload_str);
819	    if (!root) {
820	        syslog(LOG_WARNING, "[%s] payload JSON parse failed\n", TAG);
821	        free(payload_str);
822	        return;
823	    }
824	
825	    cJSON* hdr = cJSON_GetObjectItem(root, "header");
826	    cJSON* ev = cJSON_GetObjectItem(root, "event");
827	    char* text = NULL;
828	
829	    /* Deduplicate by event_id */
830	    if (cJSON_IsObject(hdr)) {
831	        cJSON* eid = cJSON_GetObjectItem(hdr, "event_id");
832	        if (cJSON_IsString(eid) && eid->valuestring[0]) {
833	            if (dedup_check_and_record(eid->valuestring)) {
834	                goto cleanup; /* Duplicate event, skip silently */
835	            }
836	        }
837	    }
838	
839	    /* Check event type */
840	    {
841	        const char* event_type = "";
842	        if (cJSON_IsObject(hdr)) {
843	            cJSON* et = cJSON_GetObjectItem(hdr, "event_type");
844	            if (cJSON_IsString(et)) {
845	                event_type = et->valuestring;
846	            }
847	        }
848	        if (strcmp(event_type, "im.message.receive_v1") != 0) {
849	            syslog(LOG_DEBUG, "[%s] ignored event_type=%s\n", TAG, event_type);
850	            goto cleanup;
851	        }
852	    }
853	
854	    if (!cJSON_IsObject(ev)) {
855	        goto cleanup;
856	    }
857	
858	    if (filter_sender(ev)) {
859	        goto cleanup;
860	    }
861	
862	    /* Check if sender is a bot (for rate limiting) */
863	    bool is_bot_sender = false;
864	    {
865	        cJSON* sender = cJSON_GetObjectItem(ev, "sender");
866	        if (cJSON_IsObject(sender)) {
867	            cJSON* sender_type = cJSON_GetObjectItem(sender, "sender_type");
868	            if (cJSON_IsString(sender_type) &&
869	                strcmp(sender_type->valuestring, "app") == 0) {
870	                is_bot_sender = true;
871	            }
872	        }
873	    }
874	
875	    cJSON* msg = cJSON_GetObjectItem(ev, "message");
876	    if (!cJSON_IsObject(msg)) {
877	        goto cleanup;
878	    }
879	
880	    cJSON* chat_id_j = cJSON_GetObjectItem(msg, "chat_id");
881	    cJSON* content_j = cJSON_GetObjectItem(msg, "content");
882	    cJSON* msg_type_j = cJSON_GetObjectItem(msg, "message_type");
883	    const char* msg_type = cJSON_IsString(msg_type_j) ? msg_type_j->valuestring : "text";
884	
885	    syslog(LOG_DEBUG, "[%s] msg_type=%s\n", TAG, msg_type);
886	
887	    /* Bot-to-bot rate limiting */
888	    if (is_bot_sender && cJSON_IsString(chat_id_j)) {
889	        if (bot_rate_limited(chat_id_j->valuestring)) {
890	            goto cleanup;
891	        }
892	    }
893	
894	    if (filter_stale_message(msg)) {
895	        goto cleanup;
896	    }
897	
898	    if (!cJSON_IsString(chat_id_j)) {
899	        goto cleanup;
900	    }
901	
902	    if (!cJSON_IsString(content_j) && strcmp(msg_type, "image") != 0) {
903	        goto cleanup;
904	    }
905	
906	    bool is_text = (strcmp(msg_type, "text") == 0);
907	    bool is_post = (strcmp(msg_type, "post") == 0);
908	    bool is_image = (strcmp(msg_type, "image") == 0);
909	
910	    if (!is_text && !is_post && !is_image) {
911	        syslog(LOG_DEBUG, "[%s] Unsupported msg_type=%s, skipping\n", TAG, msg_type);
912	        goto cleanup;
913	    }
914	
915	    if (is_image) {
916	        handle_image_message(msg, chat_id_j->valuestring, content_j);
917	        goto cleanup;
918	    }
919	
920	    /* Text/Post message handling */
921	    {
922	        char post_image_key[128] = { 0 };
923	        cJSON* cj = cJSON_Parse(content_j->valuestring);
924	
925	        if (!cj) {
926	            syslog(LOG_WARNING, "[%s] content JSON parse failed, dropping\n", TAG);
927	            goto cleanup;
928	        }
929	
930	        if (is_post) {
931	            text = extract_post_text(cj, post_image_key, sizeof(post_image_key));
932	        } else {
933	            cJSON* ti = cJSON_GetObjectItem(cj, "text");
934	            if (cJSON_IsString(ti)) {
935	                text = strdup(ti->valuestring);
936	            }
937	        }
938	        cJSON_Delete(cj);
939	
940	        if (post_image_key[0] && text) {
941	            download_post_image(post_image_key, msg, &text);
942	        }
943	
944	        if (!text || !text[0]) {
945	            free(text);
946	            text = NULL;
947	            goto cleanup;
948	        }
949	
950	        char* trimmed = trim_unicode_whitespace(text);
951	        if (!*trimmed) {
952	            syslog(LOG_DEBUG, "[%s] Empty text after trim, skipping\n", TAG);
953	            free(text);
954	            text = NULL;
955	            goto cleanup;
956	        }
957	        if (trimmed != text) {
958	            memmove(text, trimmed, strlen(trimmed) + 1);
959	        }
960	
961	        if (!validate_text_content(text)) {
962	            free(text);
963	            text = NULL;
964	            goto cleanup;
965	        }
966	
967	        if (process_group_mentions(msg, &text)) {
968	            text = NULL;
969	            goto cleanup;
970	        }
971	
972	        cJSON* msg_id_j = cJSON_GetObjectItem(msg, "message_id");
973	        if (cJSON_IsString(msg_id_j) && msgid_dedup_check(msg_id_j->valuestring)) {
974	            syslog(LOG_WARNING, "[%s] Duplicate message_id %s, skipping\n",
975	                TAG, msg_id_j->valuestring);
976	            free(text);
977	            text = NULL;
978	            goto cleanup;
979	        }
980	
981	        if (!post_image_key[0] && content_dedup_check(chat_id_j->valuestring, text)) {
982	            free(text);
983	            text = NULL;
984	            goto cleanup;
985	        }
986	
987	        /* Final empty check */
988	        {
989	            const char* p = text;
990	            while (*p && ((unsigned char)*p <= 0x20)) {
991	                p++;
992	            }
993	            if (!*p) {
994	                syslog(LOG_WARNING, "[%s] Final check: empty content, dropping\n", TAG);
995	                free(text);
996	                text = NULL;
997	                goto cleanup;
998	            }
999	        }
1000	
1001	        syslog(LOG_INFO, "[%s] MSG from [%.24s] len=%zu\n", TAG,
1002	            chat_id_j->valuestring, strlen(text));
1003	
1004	        agent_msg_t m = { 0 };
1005	        strncpy(m.channel, AGENT_CHAN_FEISHU, sizeof(m.channel) - 1);
1006	        strncpy(m.chat_id, chat_id_j->valuestring, sizeof(m.chat_id) - 1);
1007	        m.content = text;
1008	        message_bus_push_inbound(&m);
1009	        text = NULL; /* ownership transferred */
1010	    }
1011	
1012	cleanup:
1013	    free(text);
1014	    free(payload_str);
1015	    cJSON_Delete(root);
1016	}
