25	/* ── Outgoing @mention conversion ──────────────────────────────── */
26	
27	static char* convert_outgoing_mentions(const char* text, size_t* clean_end)
28	{
29	    typedef struct {
30	        char name[64];
31	        char oid[64];
32	    } mention_entry_t;
33	
34	    mention_entry_t mmap[8];
35	    int mcount = 0;
36	
37	    const char* block = strstr(text, "\n[mentioned_users:");
38	    if (!block) {
39	        block = strstr(text, "[mentioned_users:");
40	    }
41	
42	    size_t text_end = strlen(text);
43	
44	    if (block) {
45	        text_end = (size_t)(block - text);
46	        const char* start = strchr(block, ':');
47	        const char* end = strchr(block, ']');
48	
49	        if (start && end && start < end) {
50	            start++;
51	            while (start < end && mcount < 8) {
52	                while (start < end && *start == ' ') {
53	                    start++;
54	                }
55	
56	                const char* eq = memchr(start, '=', (size_t)(end - start));
57	                if (!eq) {
58	                    break;
59	                }
60	
61	                const char* comma = memchr(eq, ',', (size_t)(end - eq));
62	                if (!comma) {
63	                    comma = end;
64	                }
65	
66	                size_t nlen = (size_t)(eq - start);
67	                size_t olen = (size_t)(comma - eq - 1);
68	
69	                if (nlen > 0 && nlen < 64 && olen > 0 && olen < 64) {
