  /* 发送 AT 指令 */
  write(fd, cmd, strlen(cmd));
  write(fd, "\r\n", 2);

  /* 接收响应（超时 5s） */
  struct pollfd fds[1];
  fds[0].fd = fd;
  fds[0].events = POLLIN;

