static void butler_print_banner(void)
{
  syslog(LOG_INFO, "\n");
  syslog(LOG_INFO, "╔══════════════════════════════════════╗\n");
  syslog(LOG_INFO, "║       AI 管家 - 智能环境管家         ║\n");
