  syslog(LOG_INFO, "╚══════════════════════════════════════╝\n");
  syslog(LOG_INFO, "\n");
}

static int butler_parse_args(int argc, char *argv[])
{
  int opt;

  while ((opt = getopt(argc, argv, "h")) != -1)
    {
      switch (opt)
        {
          case 'h':
          default:
            syslog(LOG_INFO, "Usage: ai_butler [-h]\n");
            syslog(LOG_INFO, "  -h  显示帮助信息\n");
