  ret = board_pwmInitialize();
  if (ret < 0)
    {
      syslog(LOG_WARNING, "[%s] PWM 初始化失败: %d\n", TAG, ret);
    }
  else
    {
      syslog(LOG_INFO, "[%s] PWM 初始化成功 (扬声器)\n", TAG);
    }
#endif

#ifdef CONFIG_I2S
  ret = board_i2sInitialize();
  if (ret < 0)
    {
      syslog(LOG_WARNING, "[%s] I2S 初始化失败: %d\n", TAG, ret);
    }
  else
    {
      syslog(LOG_INFO, "[%s] I2S 初始化成功 (麦克风)\n", TAG);
    }
#endif

  /* 启动 AI Agent */
  syslog(LOG_INFO, "[%s] 启动 AI Agent...\n", TAG);

  /* 创建环境监控任务 */
  ret = env_monitor_start();
  if (ret < 0)
    {
      syslog(LOG_WARNING, "[%s] 环境监控启动失败: %d\n", TAG, ret);
    }
  else
    {
      syslog(LOG_INFO, "[%s] 环境监控已启动 (每 5 分钟巡检)\n", TAG);
    }

  g_butler_running = true;
  syslog(LOG_INFO, "[%s] AI 管家启动完成！\n", TAG);
  syslog(LOG_INFO, "[%s] 语音唤醒: 你好，openvela\n", TAG);
  syslog(LOG_INFO, "[%s] CLI 命令: ask <消息>\n", TAG);

  /* 主循环 */
  while (g_butler_running)
    {
      /* 等待事件 */
      sleep(1);
    }

  syslog(LOG_INFO, "[%s] AI 管家已停止\n", TAG);
  return OK;
}

