/****************************************************************************
 * AI 管家项目 - 环境监控模块
 * 定时巡检 SHT30 + MH-Z19B，超阈值主动告警
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <nuttx/timers/timer.h>

#include "ai_butler.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define TAG "env_monitor"

/* 巡检间隔: 5 分钟 */
#define INSPECTION_INTERVAL_SEC  (5 * 60)

/* 阈值定义 */
#define TEMP_WARNING_THRESHOLD   28.0f   /* 温度警告阈值 (°C) */
#define TEMP_CRITICAL_THRESHOLD  32.0f   /* 温度严重阈值 (°C) */
#define HUMI_WARNING_THRESHOLD   70.0f   /* 湿度警告阈值 (%) */
#define HUMI_CRITICAL_THRESHOLD  80.0f   /* 湿度严重阈值 (%) */
#define CO2_WARNING_THRESHOLD    1000    /* CO₂ 警告阈值 (ppm) */
#define CO2_CRITICAL_THRESHOLD   1500    /* CO₂ 严重阈值 (ppm) */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static timer_t g_inspection_timer;
static bool g_monitor_running = false;
static env_data_t g_last_env_data;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int read_env_data(env_data_t *data)
{
  int ret;

  /* 读取 SHT30 温湿度 */
#ifdef CONFIG_I2C
  ret = board_sht30_read(&data->temperature, &data->humidity);
  if (ret < 0)
    {
      syslog(LOG_WARNING, "[%s] SHT30 读取失败: %d\n", TAG, ret);
      data->temperature = 0;
      data->humidity = 0;
    }
#else
  data->temperature = 25.0f;
  data->humidity = 50.0f;
#endif

  /* 读取 CO₂ 浓度 (MH-Z19B) */
#ifdef CONFIG_UART2
  /* TODO: 实现 MH-Z19B UART 读取 */
  data->co2 = 800;  /* 默认值 */
#else
  data->co2 = 800;
#endif

  /* 获取时间戳 */
  clock_gettime(CLOCK_REALTIME, &data->timestamp);

  return OK;
}

static const char *get_env_status(env_data_t *data)
{
  if (data->co2 >= CO2_CRITICAL_THRESHOLD ||
      data->temperature >= TEMP_CRITICAL_THRESHOLD)
    {
      return "🔴 严重";
    }
  else if (data->co2 >= CO2_WARNING_THRESHOLD ||
           data->temperature >= TEMP_WARNING_THRESHOLD ||
           data->humidity >= HUMI_WARNING_THRESHOLD)
    {
      return "🟡 警告";
    }
  else
    {
      return "🟢 正常";
    }
}

static void trigger_warning(const char *reason)
{
  syslog(LOG_WARNING, "[%s] ⚠️  环境告警: %s\n", TAG, reason);

  /* 播放告警音 */
#ifdef CONFIG_PWM
  board_pwm_set_frequency(1000);  /* 1kHz */
  board_pwm_set_duty(50);        /* 50% 占空比 */
  usleep(500000);                 /* 持续 500ms */
  board_pwm_set_duty(0);         /* 停止 */
#endif

  /* 触发继电器联动 */
  if (strstr(reason, "CO₂"))
    {
      /* CO₂ 超标，打开换气扇 */
      board_relay_control(2, true);  /* 继电器3: 换气扇 */
      syslog(LOG_INFO, "[%s] 自动开启换气扇\n", TAG);
    }

  if (strstr(reason, "温度"))
    {
      /* 温度过高，打开风扇 */
      board_relay_control(1, true);  /* 继电器2: 风扇 */
      syslog(LOG_INFO, "[%s] 自动开启风扇\n", TAG);
    }
}

static void env_inspection_handler(void)
{
  env_data_t data;
  char warning_msg[128];

  /* 读取环境数据 */
  read_env_data(&data);
  g_last_env_data = data;

  syslog(LOG_INFO, "[%s] 巡检结果: 温度=%.1f°C, 湿度=%.1f%%, CO₂=%dppm, 状态=%s\n",
         TAG, data.temperature, data.humidity, data.co2,
         get_env_status(&data));

  /* 检查阈值 */
  if (data.co2 >= CO2_WARNING_THRESHOLD)
    {
      snprintf(warning_msg, sizeof(warning_msg),
               "CO₂ 浓度 %d ppm，超过警告阈值 %d ppm",
               data.co2, CO2_WARNING_THRESHOLD);
      trigger_warning(warning_msg);
    }

  if (data.temperature >= TEMP_WARNING_THRESHOLD)
    {
      snprintf(warning_msg, sizeof(warning_msg),
               "温度 %.1f°C，超过警告阈值 %.0f°C",
               data.temperature, TEMP_WARNING_THRESHOLD);
      trigger_warning(warning_msg);
    }

  if (data.humidity >= HUMI_WARNING_THRESHOLD)
    {
      snprintf(warning_msg, sizeof(warning_msg),
               "湿度 %.1f%%，超过警告阈值 %.0f%%",
               data.humidity, HUMI_WARNING_THRESHOLD);
      trigger_warning(warning_msg);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int env_monitor_start(void)
{
  struct sigevent event;
  struct itimerspec its;

  if (g_monitor_running)
    {
      return OK;
    }

  /* 创建定时器 */
  event.sigev_notify = SIGEV_THREAD;
  event.sigev_notify_function = (void (*)(union sigval))env_inspection_handler;
  event.sigev_value.sival_ptr = NULL;

  if (timer_create(CLOCK_REALTIME, &event, &g_inspection_timer) < 0)
    {
      syslog(LOG_ERR, "[%s] 创建定时器失败\n", TAG);
      return -errno;
    }

  /* 设置 5 分钟间隔 */
  its.it_value.tv_sec = INSPECTION_INTERVAL_SEC;
  its.it_value.tv_nsec = 0;
  its.it_interval.tv_sec = INSPECTION_INTERVAL_SEC;
  its.it_interval.tv_nsec = 0;

  if (timer_settime(g_inspection_timer, 0, &its, NULL) < 0)
    {
      syslog(LOG_ERR, "[%s] 设置定时器失败\n", TAG);
