/****************************************************************************
 * AI Butler - Main Application
 * 基于 openvela + ai_agent 框架
 *
 * 功能：
 *   1. 连续对话
 *   2. 模糊意图理解
 *   3. 主动提醒
 *   4. 场景联动
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/board.h>
#include <nuttx/arch.h>
#include <debug.h>
#include <string.h>
#include <stdlib.h>

#include "ai_agent.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define AI_BUTLER_STACKSIZE  8192
#define AI_BUTLER_PRIORITY   100

/****************************************************************************
 * Private Data
 ****************************************************************************/

static bool g_ai_butler_running = false;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_butler_task
 *
 * Description:
 *   AI 管家主任务
 *
 ****************************************************************************/

static int ai_butler_task(int argc, char *argv[])
{
  board_info("AI Butler: Starting...\n");

  /* 初始化 AI Agent */
  ai_agent_init();

  /* 加载 Skills */
  board_info("AI Butler: Loading Skills...\n");
  ai_agent_load_skills("/data/ai_agent/skills");

  /* 启动对话循环 */
  board_info("AI Butler: Ready for conversation!\n");
  g_ai_butler_running = true;

  /* 主循环 */
  while (g_ai_butler_running)
    {
      /* 处理用户输入 */
      ai_agent_process_input();

      /* 处理主动提醒 */
      ai_agent_process_reminders();

      /* 处理场景联动 */
      ai_agent_process_scenes();

      /* 延时 10ms */
      usleep(10000);
    }

  /* 清理 */
  ai_agent_deinit();
  board_info("AI Butler: Stopped.\n");

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_butler_start
 *
 * Description:
 *   启动 AI 管家
 *
 ****************************************************************************/

int ai_butler_start(void)
{
  pid_t pid;

  if (g_ai_butler_running)
    {
      board_info("AI Butler: Already running!\n");
      return -EALREADY;
    }

  /* 创建 AI 管家任务 */
  pid = task_create("ai_butler",
                    AI_BUTLER_PRIORITY,
                    AI_BUTLER_STACKSIZE,
                    ai_butler_task,
                    NULL);

  if (pid < 0)
    {
      board_err("AI Butler: Failed to start!\n");
      return -errno;
    }

  board_info("AI Butler: Started (PID=%d)\n", pid);
  return OK;
}

/****************************************************************************
 * Name: ai_butler_stop
 *
 * Description:
 *   停止 AI 管家
 *
 ****************************************************************************/

int ai_butler_stop(void)
{
  if (!g_ai_butler_running)
    {
      board_info("AI Butler: Not running!\n");
      return -ENOTCONN;
    }

  board_info("AI Butler: Stopping...\n");
  g_ai_butler_running = false;

  return OK;
}

