            {
              new_scene->id = i;
              break;
            }
        }
    }

  board_info("Scene Manager: Created scene '%s' (id=%d)\n",
             new_scene->name, new_scene->id);

  return new_scene->id;
}

/****************************************************************************
 * Name: scene_manager_delete
 *
 * Description:
 *   删除场景
 *
 ****************************************************************************/

int scene_manager_delete(int scene_id)
{
  struct scene_s *scene = scene_manager_find_scene(scene_id);
  if (!scene)
    {
      return -ENOENT;
    }

  /* 如果是当前活动场景，先停用 */
  if (g_active_scene == scene_id)
    {
      g_active_scene = SCENE_ID_NONE;
    }

  /* 清零场景 */
  memset(scene, 0, sizeof(struct scene_s));

  board_info("Scene Manager: Deleted scene %d\n", scene_id);
  return OK;
}

/****************************************************************************
 * Name: scene_manager_activate
 *
 * Description:
 *   激活场景
 *
 ****************************************************************************/

int scene_manager_activate(int scene_id)
{
  struct scene_s *scene = scene_manager_find_scene(scene_id);
  if (!scene)
    {
      return -ENOENT;
    }

  /* 执行场景动作 */
  scene_manager_execute_actions(scene);

  /* 更新状态 */
  scene->status = SCENE_STATUS_ACTIVE;
  g_active_scene = scene_id;

  board_info("Scene Manager: Activated scene '%s'\n", scene->name);
  return OK;
}

/****************************************************************************
 * Name: scene_manager_deactivate
 *
 * Description:
 *   停用场景
 *
 ****************************************************************************/

int scene_manager_deactivate(int scene_id)
{
  struct scene_s *scene = scene_manager_find_scene(scene_id);
  if (!scene)
    {
      return -ENOENT;
    }

  /* 更新状态 */
  scene->status = SCENE_STATUS_ENABLED;

  if (g_active_scene == scene_id)
    {
      g_active_scene = SCENE_ID_NONE;
    }

  board_info("Scene Manager: Deactivated scene '%s'\n", scene->name);
  return OK;
}

/****************************************************************************
 * Name: scene_manager_process
 *
 * Description:
 *   处理场景（主循环调用）
 *
 ****************************************************************************/

int scene_manager_process(void)
{
  if (!g_scene_manager_initialized)
    {
      return -EINVAL;
    }

  /* 读取当前环境数据 */
  struct env_data_s env_data;
  memset(&env_data, 0, sizeof(struct env_data_s));

  /* 获取环境数据（简化实现，实际应该调用 env_monitor_read） */
  env_data.temperature = 25.0f;
  env_data.humidity = 50.0f;
  env_data.co2 = 500;

  /* 检查所有启用的场景 */
  for (int i = 0; i < MAX_SCENES; i++)
    {
      struct scene_s *scene = &g_scenes[i];

      /* 跳过空场景和禁用的场景 */
      if (scene->id == 0 || scene->status != SCENE_STATUS_ENABLED)
        {
          continue;
        }

      /* 跳过已经是活动状态的场景 */
      if (scene->id == g_active_scene)
        {
          continue;
        }

      /* 检查触发条件 */
      if (scene_manager_check_trigger(scene, &env_data))
        {
          /* 触发场景 */
          board_info("Scene: Scene '%s' triggered\n", scene->name);
          scene_manager_activate(scene->id);
        }
    }

  return OK;
}

/****************************************************************************
 * Name: scene_manager_get_scene
 *
 * Description:
 *   获取场景信息
 *
 ****************************************************************************/

struct scene_s *scene_manager_get_scene(int scene_id)
{
  return scene_manager_find_scene(scene_id);
}

/****************************************************************************
 * Name: scene_manager_list_scenes
 *
 * Description:
 *   列出所有场景
 *
 ****************************************************************************/

int scene_manager_list_scenes(void)
{
  board_info("=== Scene List ===\n");

  for (int i = 0; i < MAX_SCENES; i++)
    {
      struct scene_s *scene = &g_scenes[i];

      if (scene->id == 0)
        {
          continue;
        }

      const char *status_str;
      switch (scene->status)
        {
          case SCENE_STATUS_DISABLED:
            status_str = "DISABLED";
            break;
          case SCENE_STATUS_ENABLED:
            status_str = "ENABLED";
            break;
          case SCENE_STATUS_ACTIVE:
            status_str = "ACTIVE";
            break;
          default:
            status_str = "UNKNOWN";
            break;
        }

      board_info("  [%d] %s - %s (%s)\n",
                 scene->id, scene->name, scene->description, status_str);
    }

  board_info("==================\n");
  return OK;
}

