#define AI_BUTLER_PRIORITY   100

/* 环境监测间隔 (毫秒) */
#define ENV_MONITOR_INTERVAL  30000  /* 30秒 */

/****************************************************************************
 * Private Data
 ****************************************************************************/

static bool g_ai_butler_running = false;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_butler_process_env_alerts
 *
 * Description:
 *   处理环境告警
 *
 ****************************************************************************/

static int ai_butler_process_env_alerts(void)
{
  struct env_data_s env_data;
  struct env_alert_s alert;

  /* 读取环境数据 */
  int ret = env_monitor_read(&env_data);
  if (ret < 0)
    {
      board_err("AI Butler: Failed to read environment data\n");
      return ret;
    }

  /* 检查告警 */
  ret = env_monitor_check_alerts(&env_data, &alert);
  if (ret < 0)
    {
      board_err("AI Butler: Failed to check alerts\n");
      return ret;
    }

  /* 处理告警 */
  if (alert.type != ALERT_TYPE_NONE)
    {
      board_warn("AI Butler: %s\n", alert.message);

      /* 如果需要自动执行动作 */
      if (alert.auto_action)
        {
          switch (alert.type)
            {
              case ALERT_TYPE_TEMP_HIGH:
                /* 温度过高，自动开风扇 */
                board_info("AI Butler: Auto-opening fan due to high temperature\n");
                env_monitor_control_relay(RELAY_FAN, true);
                break;

              case ALERT_TYPE_HUMIDITY_LOW:
                /* 湿度过低，自动开加湿器 */
                board_info("AI Butler: Auto-opening humidifier due to low humidity\n");
                env_monitor_control_relay(RELAY_HUMIDIFIER, true);
                break;

              default:
                break;
            }
        }
    }

  return OK;
}

/****************************************************************************
 * Name: ai_butler_task
 *
 * Description:
 *   AI 管家主任务
 *
 ****************************************************************************/

static int ai_butler_task(int argc, char *argv[])
{
  board_info("AI Butler: Starting...\n");

  /* 初始化各模块 */
  board_info("AI Butler: Initializing modules...\n");

  /* 初始化环境监测 */
  env_monitor_init();

  /* 初始化定时器管理 */
  timer_manager_init();

  /* 初始化场景管理 */
  scene_manager_init();

  /* 启动对话循环 */
  board_info("AI Butler: Ready!\n");
  board_info("AI Butler: Features enabled:\n");
  board_info("  - Continuous conversation\n");
  board_info("  - Fuzzy intent understanding\n");
  board_info("  - Proactive reminders\n");
  board_info("  - Scene automation\n");

  g_ai_butler_running = true;

  /* 主循环 */
  uint32_t env_monitor_counter = 0;

  while (g_ai_butler_running)
    {
      /* 处理定时器 */
      timer_manager_process();

      /* 处理场景联动 */
      scene_manager_process();

      /* 定时读取环境数据并检查告警 */
      env_monitor_counter++;
      if (env_monitor_counter >= (ENV_MONITOR_INTERVAL / 10))
        {
          ai_butler_process_env_alerts();
          env_monitor_counter = 0;
        }

      /* 延时 10ms */
      usleep(10000);
    }

  /* 清理 */
  board_info("AI Butler: Shutting down...\n");

  scene_manager_deinit();
  timer_manager_deinit();
  env_monitor_deinit();

  board_info("AI Butler: Stopped.\n");

  return OK;
}

