/****************************************************************************
 * AI Butler - Cloud Connector Header
 * 云连接模块 - ESP32 WiFi、火山引擎 ASR/TTS、DeepSeek LLM
 ****************************************************************************/

#ifndef __CLOUD_CONNECTOR_H
#define __CLOUD_CONNECTOR_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdint.h>
#include <stdbool.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* WiFi 配置默认值 */
#define DEFAULT_WIFI_SSID       "your-wifi-ssid"
#define DEFAULT_WIFI_PASS       "your-wifi-password"
#define DEFAULT_ESP32_BAUD      115200

/* 火山引擎配置 */
#define VOLCENGINE_ASR_URL      "wss://openspeech.bytedance.com/api/v1/asr"
#define VOLCENGINE_TTS_URL      "wss://openspeech.bytedance.com/api/v1/tts"
#define VOLCENGINE_APP_ID       "your-app-id"
#define VOLCENGINE_ACCESS_TOKEN "your-access-token"

/* DeepSeek 配置 */
#define DEEPSEEK_API_URL       "https://api.deepseek.com/v1/chat/completions"
#define DEEPSEEK_API_KEY       "your-api-key"
#define DEEPSEEK_MODEL         "deepseek-chat"

/* 连接状态 */
#define CLOUD_STATUS_DISCONNECTED  0
#define CLOUD_STATUS_CONNECTING    1
#define CLOUD_STATUS_CONNECTED     2
#define CLOUD_STATUS_ERROR         3

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* WiFi 配置结构 */
struct wifi_config_s
{
  char ssid[32];              /* WiFi SSID */
  char password[64];          /* WiFi 密码 */
  int baudrate;               /* ESP32 波特率 */
};

/* 云连接状态结构 */
struct cloud_status_s
{
  int wifi_status;            /* WiFi 连接状态 */
  int asr_status;             /* ASR 服务状态 */
  int tts_status;             /* TTS 服务状态 */
  int llm_status;             /* LLM 服务状态 */
  char ip_address[16];        /* IP 地址 */
  bool internet_available;    /* 是否可以访问互联网 */
};

/* ASR 结果回调 */
typedef void (*asr_result_cb_t)(const char *text, void *arg);

/* TTS 完成回调 */
typedef void (*tts_done_cb_t)(void *arg);

/* LLM 响应回调 */
typedef void (*llm_response_cb_t)(const char *text, bool is_final, void *arg);

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/****************************************************************************
 * Name: cloud_connector_init
 *
 * Description:
 *   初始化云连接模块
 *
 ****************************************************************************/

int cloud_connector_init(void);

/****************************************************************************
 * Name: cloud_connector_deinit
 *
 * Description:
 *   反初始化云连接模块
 *
 ****************************************************************************/

int cloud_connector_deinit(void);

/****************************************************************************
 * Name: cloud_connector_wifi_connect
 *
 * Description:
 *   连接 WiFi
 *
 ****************************************************************************/

int cloud_connector_wifi_connect(const char *ssid, const char *password);

/****************************************************************************
 * Name: cloud_connector_wifi_disconnect
 *
 * Description:
 *   断开 WiFi
 *
 ****************************************************************************/

int cloud_connector_wifi_disconnect(void);

/****************************************************************************
 * Name: cloud_connector_get_status
 *
 * Description:
 *   获取云连接状态
 *
 ****************************************************************************/

int cloud_connector_get_status(struct cloud_status_s *status);

/****************************************************************************
 * Name: cloud_connector_asr_start
 *
 * Description:
 *   开始 ASR 语音识别
 *
 ****************************************************************************/

int cloud_connector_asr_start(asr_result_cb_t callback, void *arg);

/****************************************************************************
 * Name: cloud_connector_asr_feed
 *
 * Description:
 *   喂入音频数据到 ASR
