269	### 3.2 环境监测模块
270	
271	#### 3.2.1 功能设计
272	
273	- **监测参数**: 温度、湿度、CO2 浓度
274	- **采样周期**: 30 秒
275	- **告警阈值**:
276	  - 温度 > 28°C
277	  - 湿度 < 40%
278	  - CO2 > 1000 ppm
279	
280	#### 3.2.2 数据结构
281	
282	```c
283	// 环境数据
284	struct env_data_s {
285	    float temperature;      // 温度 (°C)
286	    float humidity;         // 湿度 (%)
287	    int   co2;              // CO2 浓度 (ppm)
288	    time_t timestamp;       // 时间戳
289	};
290	
291	// 告警阈值
292	struct env_threshold_s {
293	    float temp_high;        // 温度上限
294	    float temp_low;         // 温度下限
295	    float humidity_high;    // 湿度上限
296	    float humidity_low;     // 湿度下限
297	    int   co2_high;         // CO2 上限
298	    int   co2_low;          // CO2 下限
299	};
300	
301	// 告警类型
302	enum env_alert_type_e {
303	    ALERT_TEMP_HIGH,        // 温度过高
304	    ALERT_TEMP_LOW,         // 温度过低
305	    ALERT_HUMIDITY_HIGH,    // 湿度过高
306	    ALERT_HUMIDITY_LOW,     // 湿度过低
307	    ALERT_CO2_HIGH,         // CO2 过高
308	    ALERT_CO2_LOW           // CO2 过低
309	};
310	```
311	
312	#### 3.2.3 核心算法
313	
314	```c
315	// 环境监测主循环
316	void env_monitor_process(void) {
317	    static time_t last_sample = 0;
318	    time_t now = time(NULL);
319	    
320	    // 每 30 秒采样一次
321	    if (now - last_sample >= 30) {
322	        // 读取传感器数据
323	        struct env_data_s data;
324	        sht30_read(&data.temperature, &data.humidity);
325	        data.co2 = mhz19b_read();
326	        data.timestamp = now;
327	        
328	        // 检查告警
329	        check_alerts(&data);
330	        
331	        // 更新全局数据
332	        g_env_data = data;
333	        
334	        last_sample = now;
335	    }
336	}
337	
338	// 告警检查
339	void check_alerts(struct env_data_s *data) {
340	    // 温度告警
341	    if (data->temperature > g_threshold.temp_high) {
342	        trigger_alert(ALERT_TEMP_HIGH, data->temperature);
343	        // 自动开风扇
344	        relay_control(RELAY_FAN, true);
345	    }
346	    
347	    // 湿度告警
348	    if (data->humidity < g_threshold.humidity_low) {
349	        trigger_alert(ALERT_HUMIDITY_LOW, data->humidity);
350	        // 自动开加湿器
351	        relay_control(RELAY_HUMIDIFIER, true);
352	    }
353	    
354	    // CO2 告警
355	    if (data->co2 > g_threshold.co2_high) {
356	        trigger_alert(ALERT_CO2_HIGH, data->co2);
357	        // 自动开风扇通风
358	        relay_control(RELAY_FAN, true);
359	    }
360	}
361	```
362	
363	### 3.3 定时管理模块
364	
365	#### 3.3.1 功能设计
366	
367	- **定时器类型**:
368	  - 单次定时 (TIMER_TYPE_ONCE)
369	  - 每日定时 (TIMER_TYPE_DAILY)
370	  - 每周定时 (TIMER_TYPE_WEEKLY)
371	  - 间隔定时 (TIMER_TYPE_INTERVAL)
372	
373	- **动作类型**:
374	  - 继电器开 (RELAY_ON)
375	  - 继电器关 (RELAY_OFF)
376	  - 提醒 (REMIND)
377	  - 问候 (GREETING)
378	
379	#### 3.3.2 数据结构
380	
381	```c
382	// 定时器结构
383	struct timer_s {
384	    int id;                     // 定时器ID
385	    char name[32];              // 定时器名称
386	    int type;                   // 定时器类型
387	    int hour;                   // 小时
388	    int minute;                 // 分钟
389	    int weekday;                // 星期 (0-6)
390	    int interval;               // 间隔 (秒)
391	    int action;                 // 动作类型
392	    int relay_id;               // 继电器ID
393	    bool enabled;               // 启用状态
394	    time_t next_trigger;        // 下次触发时间
395	};
396	
397	// 定时器管理器
398	struct timer_manager_s {
399	    struct timer_s timers[MAX_TIMERS];  // 定时器数组
400	    int count;                          // 定时器数量
401	};
402	```
403	
404	#### 3.3.3 核心算法
405	
406	```c
407	// 定时器处理主循环
408	void timer_manager_process(void) {
409	    time_t now = time(NULL);
410	    
411	    for (int i = 0; i < g_timer_manager.count; i++) {
412	        struct timer_s *timer = &g_timer_manager.timers[i];
413	        
414	        if (!timer->enabled) {
415	            continue;
416	        }
417	        
418	        // 检查是否到达触发时间
419	        if (now >= timer->next_trigger) {
420	            // 执行动作
421	            execute_timer_action(timer);
422	            
423	            // 计算下次触发时间
424	            calculate_next_trigger(timer);
425	        }
426	    }
427	}
428	
429	// 执行定时动作
430	void execute_timer_action(struct timer_s *timer) {
431	    switch (timer->action) {
432	        case RELAY_ON:
433	            relay_control(timer->relay_id, true);
434	            break;
435	        case RELAY_OFF:
436	            relay_control(timer->relay_id, false);
437	            break;
438	        case REMIND:
439	            send_reminder(timer->name);
440	            break;
441	        case GREETING:
442	            send_greeting(timer->name);
443	            break;
444	    }
445	}
446	
447	// 计算下次触发时间
448	void calculate_next_trigger(struct timer_s *timer) {
449	    time_t now = time(NULL);
450	    struct tm *tm = localtime(&now);
451	    
452	    switch (timer->type) {
453	        case TIMER_TYPE_ONCE:
454	            // 单次定时，禁用定时器
455	            timer->enabled = false;
456	            break;
457	            
458	        case TIMER_TYPE_DAILY:
459	            // 每日定时
460	            tm->tm_hour = timer->hour;
461	            tm->tm_min = timer->minute;
462	            tm->tm_sec = 0;
463	            timer->next_trigger = mktime(tm);
464	            if (timer->next_trigger <= now) {
465	                timer->next_trigger += 86400;  // 加一天
466	            }
467	            break;
468	            
469	        case TIMER_TYPE_WEEKLY:
470	            // 每周定时
471	            int days_ahead = timer->weekday - tm->tm_wday;
472	            if (days_ahead < 0) {
473	                days_ahead += 7;
474	            }
475	            tm->tm_hour = timer->hour;
476	            tm->tm_min = timer->minute;
477	            tm->tm_sec = 0;
478	            timer->next_trigger = mktime(tm) + days_ahead * 86400;
479	            break;
480	            
481	        case TIMER_TYPE_INTERVAL:
482	            // 间隔定时
483	            timer->next_trigger = now + timer->interval;
484	            break;
485	    }
486	}
487	```
488	
489	### 3.4 场景管理模块
490	
491	#### 3.4.1 功能设计
492	
493	- **场景类型**:
494	  - 起床场景 (07:00)
495	  - 睡眠场景 (23:00)
496	  - 工作场景 (手动)
497	  - 休息场景 (手动)
498	
499	- **触发方式**:
500	  - 时间触发 (SCENE_TRIGGER_TIME)
501	  - 传感器触发 (SCENE_TRIGGER_SENSOR)
502	  - 手动触发 (SCENE_TRIGGER_MANUAL)
503	  - 语音触发 (SCENE_TRIGGER_VOICE)
504	
505	#### 3.4.2 数据结构
506	
507	```c
508	// 场景动作
509	struct scene_action_s {
510	    int relay_id;           // 继电器ID
511	    bool state;             // 动作状态
512	    int delay_ms;           // 延时 (毫秒)
513	};
514	
515	// 场景触发
516	struct scene_trigger_s {
517	    int type;               // 触发类型
518	    int hour;               // 小时
519	    int minute;             // 分钟
520	    int sensor_type;        // 传感器类型
521	    float threshold;        // 阈值
522	};
523	
524	// 场景结构
525	struct scene_s {
526	    int id;                     // 场景ID
527	    char name[32];              // 场景名称
528	    struct scene_trigger_s trigger;  // 触发条件
529	    struct scene_action_s actions[4]; // 动作列表
530	    int action_count;           // 动作数量
531	    bool enabled;               // 启用状态
532	};
533	
534	// 场景管理器
535	struct scene_manager_s {
536	    struct scene_s scenes[MAX_SCENES];  // 场景数组
537	    int count;                          // 场景数量
538	    int active_scene;                   // 当前活动场景
539	};
540	```
541	
542	#### 3.4.3 核心算法
543	
544	```c
545	// 场景处理主循环
546	void scene_manager_process(void) {
547	    time_t now = time(NULL);
548	    struct tm *tm = localtime(&now);
549	    
550	    for (int i = 0; i < g_scene_manager.count; i++) {
551	        struct scene_s *scene = &g_scene_manager.scenes[i];
552	        
553	        if (!scene->enabled) {
554	            continue;
555	        }
556	        
557	        // 检查触发条件
558	        if (check_scene_trigger(scene, tm)) {
559	            // 执行场景动作
560	            execute_scene(scene);
561	            
562	            // 更新活动场景
563	            g_scene_manager.active_scene = scene->id;
564	        }
565	    }
566	}
567	
568	// 检查场景触发
569	bool check_scene_trigger(struct scene_s *scene, struct tm *tm) {
570	    switch (scene->trigger.type) {
571	        case SCENE_TRIGGER_TIME:
572	            // 时间触发
573	            return (tm->tm_hour == scene->trigger.hour &&
574	                    tm->tm_min == scene->trigger.minute);
575	                    
576	        case SCENE_TRIGGER_SENSOR:
577	            // 传感器触发
578	            float value = read_sensor(scene->trigger.sensor_type);
579	            return (value > scene->trigger.threshold);
580	            
581	        case SCENE_TRIGGER_MANUAL:
582	            // 手动触发，不自动触发
583	            return false;
584	            
585	        case SCENE_TRIGGER_VOICE:
586	            // 语音触发，不自动触发
587	            return false;
588	            
589	        default:
590	            return false;
591	    }
592	}
593	
594	// 执行场景动作
595	void execute_scene(struct scene_s *scene) {
596	    printf("执行场景: %s\n", scene->name);
597	    
598	    for (int i = 0; i < scene->action_count; i++) {
599	        struct scene_action_s *action = &scene->actions[i];
600	        
601	        // 延时执行
602	        if (action->delay_ms > 0) {
603	            usleep(action->delay_ms * 1000);
604	        }
605	        
606	        // 控制继电器
607	        relay_control(action->relay_id, action->state);
608	        
609	        printf("  继电器 %d: %s\n", 
610	               action->relay_id, 
611	               action->state ? "开启" : "关闭");
612	    }
613	}
614	```
615	
616	### 3.5 云连接模块
617	
618	#### 3.5.1 功能设计
619	
620	- **WiFi 连接**: ESP32 AT 指令
621	- **云端服务**:
622	  - 火山引擎 ASR (语音识别)
623	  - 火山引擎 TTS (语音合成)
624	  - DeepSeek LLM (大语言模型)
625	
626	#### 3.5.2 数据结构
627	
628	```c
629	// 云连接状态
630	struct cloud_status_s {
631	    int wifi_status;            // WiFi 状态
632	    int asr_status;             // ASR 状态
633	    int tts_status;             // TTS 状态
634	    int llm_status;             // LLM 状态
635	    char wifi_ssid[32];         // WiFi SSID
636	    char wifi_ip[16];           // WiFi IP 地址
637	};
638	
639	// ASR 配置
640	struct asr_config_s {
641	    char app_id[32];            // 应用ID
642	    char access_token[64];      // 访问令牌
643	    char cluster_id[32];        // 集群ID
