/****************************************************************************
 * AI Butler - Environment Monitor
 * 环境监测模块 - 温湿度、CO2浓度监测
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/board.h>
#include <debug.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>

#include "env_monitor.h"

#ifdef CONFIG_I2C
#  include <nuttx/i2c/i2c_master.h>
#endif

#ifdef CONFIG_DEV_GPIO
#  include <nuttx/ioexpander/gpio.h>
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* SHT30 I2C 地址 */
#define SHT30_I2C_ADDR     0x44

/* MH-Z19B UART 命令 */
static const uint8_t g_mhz19b_read_cmd[] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct env_data_s g_env_data;
static bool g_relay_state[4] = {false, false, false, false};  /* 继电器状态 */
static bool g_env_monitor_initialized = false;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

#ifdef CONFIG_I2C
/****************************************************************************
 * Name: sht30_read
 *
 * Description:
 *   从 SHT30 读取温湿度数据
 *
 ****************************************************************************/

static int sht30_read(float *temperature, float *humidity)
{
  struct i2c_msg_s msg[2];
  uint8_t cmd[2] = {0x2C, 0x06};  /* 高精度测量命令 */
  uint8_t data[6];
  int ret;

  /* 发送测量命令 */
  msg[0].frequency = 400000;
  msg[0].addr = SHT30_I2C_ADDR;
  msg[0].flags = 0;
  msg[0].buffer = cmd;
  msg[0].length = 2;

  ret = i2c_transfer(I2C0, msg, 1);
  if (ret < 0)
    {
      board_err("SHT30: Failed to send command\n");
      return ret;
    }

  /* 等待测量完成 */
  usleep(20000);  /* 20ms */

  /* 读取数据 */
  msg[0].frequency = 400000;
  msg[0].addr = SHT30_I2C_ADDR;
  msg[0].flags = I2C_M_READ;
  msg[0].buffer = data;
  msg[0].length = 6;

  ret = i2c_transfer(I2C0, msg, 1);
  if (ret < 0)
    {
      board_err("SHT30: Failed to read data\n");
      return ret;
    }

  /* 解析温湿度数据 */
  uint16_t raw_temp = (data[0] << 8) | data[1];
  uint16_t raw_humi = (data[3] << 8) | data[4];

  *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
  *humidity = 100.0f * (float)raw_humi / 65535.0f;

  /* 限制范围 */
  if (*humidity > 100.0f) *humidity = 100.0f;
  if (*humidity < 0.0f) *humidity = 0.0f;

  return OK;
}
#endif

/****************************************************************************
 * Name: mhz19b_read
 *
 * Description:
 *   从 MH-Z19B 读取 CO2 浓度
 *
 ****************************************************************************/

#ifdef CONFIG_UART3
static int mhz19b_read(int *co2)
{
  uint8_t response[9];
  int ret;

  /* 发送读取命令 */
  ret = board_uart3_write(g_mhz19b_read_cmd, sizeof(g_mhz19b_read_cmd));
  if (ret < 0)
    {
      board_err("MH-Z19B: Failed to send command\n");
      return ret;
    }

  /* 等待响应 */
  usleep(100000);  /* 100ms */

  /* 读取响应 */
  ret = board_uart3_read(response, sizeof(response));
  if (ret < 0)
    {
      board_err("MH-Z19B: Failed to read response\n");
      return ret;
    }

  /* 校验数据 */
  if (response[0] != 0xFF || response[1] != 0x86)
    {
      board_err("MH-Z19B: Invalid response header\n");
      return -EIO;
    }

  /* 计算校验和 */
  uint8_t checksum = 0;
  for (int i = 1; i < 8; i++)
    {
      checksum += response[i];
    }
  checksum = 0xFF - checksum + 1;

  if (checksum != response[8])
    {
      board_err("MH-Z19B: Checksum error\n");
      return -EIO;
    }

  /* 解析 CO2 浓度 */
  *co2 = (response[2] << 8) | response[3];

  return OK;
}
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: env_monitor_init
 *
 * Description:
 *   初始化环境监测模块
 *
 ****************************************************************************/

int env_monitor_init(void)
{
  board_info("Env Monitor: Initializing...\n");

  /* 清零环境数据 */
  memset(&g_env_data, 0, sizeof(g_env_data));
  memset(g_relay_state, false, sizeof(g_relay_state));

#ifdef CONFIG_I2C
  /* 初始化 I2C */
  board_info("Env Monitor: I2C initialized\n");
#endif

#ifdef CONFIG_UART3
  /* 初始化 UART3 (MH-Z19B) */
  board_info("Env Monitor: UART3 initialized\n");
#endif

  g_env_monitor_initialized = true;
  board_info("Env Monitor: Initialized successfully\n");

  return OK;
}

/****************************************************************************
 * Name: env_monitor_deinit
 *
 * Description:
 *   反初始化环境监测模块
 *
 ****************************************************************************/

int env_monitor_deinit(void)
{
  board_info("Env Monitor: Deinitializing...\n");
  g_env_monitor_initialized = false;
  return OK;
}

/****************************************************************************
 * Name: env_monitor_read
 *
 * Description:
 *   读取环境数据
 *
 ****************************************************************************/

int env_monitor_read(struct env_data_s *data)
{
  if (!g_env_monitor_initialized || !data)
    {
      return -EINVAL;
    }

  int ret = OK;

#ifdef CONFIG_I2C
  /* 读取温湿度 */
  ret = sht30_read(&data->temperature, &data->humidity);
  if (ret < 0)
    {
      board_err("Env Monitor: Failed to read SHT30\n");
      /* 使用默认值 */
      data->temperature = 25.0f;
      data->humidity = 50.0f;
    }
#else
  /* 模拟数据 */
  data->temperature = 25.0f;
  data->humidity = 50.0f;
#endif

#ifdef CONFIG_UART3
  /* 读取 CO2 */
  ret = mhz19b_read(&data->co2);
  if (ret < 0)
    {
      board_err("Env Monitor: Failed to read MH-Z19B\n");
      /* 使用默认值 */
      data->co2 = 500;
    }
#else
  /* 模拟数据 */
  data->co2 = 500;
#endif

  /* 更新时间戳 */
  data->timestamp = clock_systime_ticks();

  /* 保存到全局变量 */
  memcpy(&g_env_data, data, sizeof(struct env_data_s));

  board_info("Env Monitor: Temp=%.1f°C, Humidity=%.1f%%, CO2=%dppm\n",
             data->temperature, data->humidity, data->co2);

  return OK;
}

/****************************************************************************
 * Name: env_monitor_check_alerts
 *
 * Description:
 *   检查环境告警
 *
 ****************************************************************************/

int env_monitor_check_alerts(const struct env_data_s *data, struct env_alert_s *alert)
{
  if (!data || !alert)
    {
      return -EINVAL;
    }

  alert->type = ALERT_TYPE_NONE;
  alert->auto_action = false;

  /* 检查温度高 */
  if (data->temperature > TEMP_HIGH_THRESHOLD)
    {
      alert->type = ALERT_TYPE_TEMP_HIGH;
      alert->value = data->temperature;
      alert->threshold = TEMP_HIGH_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "⚠️ 温度过高：%.1f°C (阈值：%.1f°C)",
               data->temperature, TEMP_HIGH_THRESHOLD);
      alert->auto_action = true;
      return OK;
    }

  /* 检查温度低 */
  if (data->temperature < TEMP_LOW_THRESHOLD)
    {
      alert->type = ALERT_TYPE_TEMP_LOW;
      alert->value = data->temperature;
      alert->threshold = TEMP_LOW_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "⚠️ 温度过低：%.1f°C (阈值：%.1f°C)",
               data->temperature, TEMP_LOW_THRESHOLD);
      return OK;
    }

  /* 检查湿度低 */
  if (data->humidity < HUMIDITY_LOW_THRESHOLD)
    {
      alert->type = ALERT_TYPE_HUMIDITY_LOW;
      alert->value = data->humidity;
      alert->threshold = HUMIDITY_LOW_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "⚠️ 湿度过低：%.1f%% (阈值：%.1f%%)",
               data->humidity, HUMIDITY_LOW_THRESHOLD);
      alert->auto_action = true;
      return OK;
    }

  /* 检查湿度高 */
  if (data->humidity > HUMIDITY_HIGH_THRESHOLD)
    {
      alert->type = ALERT_TYPE_HUMIDITY_HIGH;
      alert->value = data->humidity;
      alert->threshold = HUMIDITY_HIGH_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "⚠️ 湿度过高：%.1f%% (阈值：%.1f%%)",
               data->humidity, HUMIDITY_HIGH_THRESHOLD);
      return OK;
    }

  /* 检查 CO2 高 */
  if (data->co2 > CO2_VERY_HIGH_THRESHOLD)
    {
      alert->type = ALERT_TYPE_CO2_VERY_HIGH;
      alert->value = data->co2;
      alert->threshold = CO2_VERY_HIGH_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "🚨 CO2浓度极高：%dppm (阈值：%dppm)，请立即通风！",
               data->co2, CO2_VERY_HIGH_THRESHOLD);
      return OK;
    }

  if (data->co2 > CO2_HIGH_THRESHOLD)
    {
      alert->type = ALERT_TYPE_CO2_HIGH;
      alert->value = data->co2;
      alert->threshold = CO2_HIGH_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "⚠️ CO2浓度偏高：%dppm (阈值：%dppm)，建议通风",
               data->co2, CO2_HIGH_THRESHOLD);
      return OK;
    }

  return OK;
}

/****************************************************************************
 * Name: env_monitor_control_relay
 *
 * Description:
 *   控制继电器
 *
 ****************************************************************************/

int env_monitor_control_relay(int relay, bool on)
{
  if (relay < 1 || relay > 3)
    {
      return -EINVAL;
    }

#ifdef CONFIG_DEV_GPIO
  /* 实际控制 GPIO */
  int ret = board_gpio_write(relay - 1, on ? 1 : 0);
  if (ret < 0)
    {
      board_err("Env Monitor: Failed to control relay %d\n", relay);
      return ret;
    }
#endif

  /* 更新状态 */
  g_relay_state[relay] = on;

  const char *device_name[] = {"", "风扇", "加湿器", "灯光"};
  board_info("Env Monitor: Relay %d (%s) %s\n", relay,
             device_name[relay], on ? "ON" : "OFF");

  return OK;
}

/****************************************************************************
 * Name: env_monitor_get_relay_state
 *
 * Description:
 *   获取继电器状态
 *
 ****************************************************************************/

bool env_monitor_get_relay_state(int relay)
{
  if (relay < 1 || relay > 3)
    {
      return false;
    }

  return g_relay_state[relay];
}

