71	/****************************************************************************
72	 * Name: timer_manager_calc_next_trigger
73	 *
74	 * Description:
75	 *   计算下次触发时间
76	 *
77	 ****************************************************************************/
78	
79	static time_t timer_manager_calc_next_trigger(struct timer_s *timer)
80	{
81	  time_t now = time(NULL);
82	  struct tm *tm_info = localtime(&now);
83	
84	  switch (timer->type)
85	    {
86	      case TIMER_TYPE_ONCE:
87	        /* 单次定时，直接返回设定时间 */
88	        return timer->trigger_time;
89	
90	      case TIMER_TYPE_DAILY:
91	        {
92	          /* 每日重复，计算今天的触发时间 */
93	          struct tm trigger_tm;
94	          memset(&trigger_tm, 0, sizeof(struct tm));
95	          trigger_tm.tm_year = tm_info->tm_year;
96	          trigger_tm.tm_mon = tm_info->tm_mon;
97	          trigger_tm.tm_mday = tm_info->tm_mday;
98	
99	          /* 从 trigger_time 中提取时分秒 */
100	          struct tm *trigger_info = localtime(&timer->trigger_time);
101	          trigger_tm.tm_hour = trigger_info->tm_hour;
102	          trigger_tm.tm_min = trigger_info->tm_min;
103	          trigger_tm.tm_sec = trigger_info->tm_sec;
104	
105	          time_t today_trigger = mktime(&trigger_tm);
106	
107	          /* 如果今天的触发时间已过，设置为明天 */
108	          if (today_trigger <= now)
109	            {
110	              today_trigger += 24 * 3600;
111	            }
112	
113	          return today_trigger;
114	        }
115	
116	      case TIMER_TYPE_WEEKLY:
117	        {
118	          /* 每周重复 */
119	          struct tm trigger_tm;
120	          memset(&trigger_tm, 0, sizeof(struct tm));
121	          trigger_tm.tm_year = tm_info->tm_year;
122	          trigger_tm.tm_mon = tm_info->tm_mon;
123	          trigger_tm.tm_mday = tm_info->tm_mday;
124	
125	          struct tm *trigger_info = localtime(&timer->trigger_time);
126	          trigger_tm.tm_hour = trigger_info->tm_hour;
127	          trigger_tm.tm_min = trigger_info->tm_min;
128	          trigger_tm.tm_sec = trigger_info->tm_sec;
129	          trigger_tm.tm_wday = trigger_info->tm_wday;
130	
131	          time_t this_week_trigger = mktime(&trigger_tm);
132	
133	          /* 计算到目标星期几的天数 */
134	          int days_ahead = trigger_tm.tm_wday - tm_info->tm_wday;
135	          if (days_ahead < 0)
136	            {
137	              days_ahead += 7;
138	            }
139	          if (days_ahead == 0 && this_week_trigger <= now)
140	            {
141	              days_ahead = 7;
142	            }
143	
144	          return this_week_trigger + days_ahead * 24 * 3600;
145	        }
146	
147	      case TIMER_TYPE_INTERVAL:
148	        /* 间隔重复 */
149	        return now + timer->interval;
150	
151	      default:
152	        return timer->trigger_time;
153	    }
154	}
