258	int timer_manager_create(struct timer_s *timer)
259	{
260	  if (!timer)
261	    {
262	      return -EINVAL;
263	    }
264	
265	  struct timer_s *new_timer = timer_manager_find_empty();
266	  if (!new_timer)
267	    {
268	      board_err("Timer Manager: No empty timer slot\n");
269	      return -ENOMEM;
270	    }
271	
272	  /* 复制定时器数据 */
273	  memcpy(new_timer, timer, sizeof(struct timer_s));
274	
275	  /* 分配 ID */
276	  new_timer->id = g_next_timer_id++;
277	
278	  /* 计算下次触发时间 */
279	  new_timer->next_trigger = timer_manager_calc_next_trigger(new_timer);
280	
281	  /* 设置状态为启用 */
282	  new_timer->status = TIMER_STATUS_ENABLED;
283	
284	  board_info("Timer Manager: Created timer %d, type=%d, next_trigger=%ld\n",
285	             new_timer->id, new_timer->type, (long)new_timer->next_trigger);
286	
287	  return new_timer->id;
288	}
