313	/****************************************************************************
314	 * Name: timer_manager_enable
315	 *
316	 * Description:
317	 *   启用定时器
318	 *
319	 ****************************************************************************/
320	
321	int timer_manager_enable(int timer_id)
322	{
323	  struct timer_s *timer = timer_manager_find_timer(timer_id);
324	  if (!timer)
325	    {
326	      return -ENOENT;
327	    }
328	
329	  timer->status = TIMER_STATUS_ENABLED;
330	  timer->next_trigger = timer_manager_calc_next_trigger(timer);
331	
332	  board_info("Timer Manager: Enabled timer %d\n", timer_id);
333	  return OK;
334	}
335	
336	/****************************************************************************
337	 * Name: timer_manager_disable
338	 *
339	 * Description:
340	 *   禁用定时器
341	 *
342	 ****************************************************************************/
343	
344	int timer_manager_disable(int timer_id)
345	{
346	  struct timer_s *timer = timer_manager_find_timer(timer_id);
347	  if (!timer)
348	    {
349	      return -ENOENT;
350	    }
351	
352	  timer->status = TIMER_STATUS_DISABLED;
353	
354	  board_info("Timer Manager: Disabled timer %d\n", timer_id);
355	  return OK;
356	}
357	
358	/****************************************************************************
359	 * Name: timer_manager_process
360	 *
361	 * Description:
362	 *   处理定时器（主循环调用）
363	 *
364	 ****************************************************************************/
365	
366	int timer_manager_process(void)
367	{
368	  if (!g_timer_manager_initialized)
369	    {
370	      return -EINVAL;
371	    }
372	
373	  time_t now = time(NULL);
374	
375	  for (int i = 0; i < MAX_TIMERS; i++)
376	    {
377	      struct timer_s *timer = &g_timers[i];
378	
379	      /* 跳过空定时器和禁用的定时器 */
380	      if (timer->id == 0 || timer->status != TIMER_STATUS_ENABLED)
381	        {
382	          continue;
383	        }
384	
385	      /* 检查是否到达触发时间 */
386	      if (now >= timer->next_trigger)
387	        {
388	          /* 执行动作 */
389	          timer_manager_execute_action(timer);
390	
391	          /* 根据类型处理 */
392	          switch (timer->type)
393	            {
394	              case TIMER_TYPE_ONCE:
395	                /* 单次定时，执行后禁用 */
396	                timer->status = TIMER_STATUS_FIRED;
397	                board_info("Timer: Timer %d fired (once)\n", timer->id);
398	                break;
399	
400	              case TIMER_TYPE_DAILY:
401	              case TIMER_TYPE_WEEKLY:
402	              case TIMER_TYPE_INTERVAL:
403	                /* 重复定时，计算下次触发时间 */
404	                timer->next_trigger = timer_manager_calc_next_trigger(timer);
405	                board_info("Timer: Timer %d fired, next trigger=%ld\n",
406	                           timer->id, (long)timer->next_trigger);
407	                break;
408	
409	              default:
410	                break;
411	            }
412	        }
413	    }
414	
415	  return OK;
416	}
417	
418	/****************************************************************************
419	 * Name: timer_manager_create_reminder
420	 *
421	 * Description:
422	 *   创建提醒定时器
423	 *
424	 ****************************************************************************/
425	
426	int timer_manager_create_reminder(int seconds, const char *message)
427	{
428	  struct timer_s timer;
429	  memset(&timer, 0, sizeof(struct timer_s));
430	
431	  timer.type = TIMER_TYPE_ONCE;
432	  timer.action = TIMER_ACTION_REMIND;
433	  timer.trigger_time = time(NULL) + seconds;
434	  timer.next_trigger = timer.trigger_time;
435	
436	  if (message)
437	    {
438	      strncpy(timer.message, message, sizeof(timer.message) - 1);
439	    }
440	  else
441	    {
442	      snprintf(timer.message, sizeof(timer.message), "提醒：%d秒到了", seconds);
443	    }
444	
445	  return timer_manager_create(&timer);
446	}
447	
448	/****************************************************************************
449	 * Name: timer_manager_create_relay_timer
450	 *
451	 * Description:
452	 *   创建继电器定时器
453	 *
454	 ****************************************************************************/
455	
456	int timer_manager_create_relay_timer(int relay, bool on, int delay_seconds)
457	{
458	  struct timer_s timer;
459	  memset(&timer, 0, sizeof(struct timer_s));
460	
461	  timer.type = TIMER_TYPE_ONCE;
462	  timer.action = on ? TIMER_ACTION_RELAY_ON : TIMER_ACTION_RELAY_OFF;
463	  timer.trigger_time = time(NULL) + delay_seconds;
464	  timer.next_trigger = timer.trigger_time;
465	  timer.relay_id = relay;
466	
467	  snprintf(timer.message, sizeof(timer.message),
468	           "%s继电器%d", on ? "开启" : "关闭", relay);
469	
470	  return timer_manager_create(&timer);
471	}
472	
473	/****************************************************************************
474	 * Name: timer_manager_create_daily_greeting
475	 *
476	 * Description:
477	 *   创建每日问候定时器
478	 *
479	 ****************************************************************************/
480	
481	int timer_manager_create_daily_greeting(int hour, int minute, const char *greeting)
482	{
483	  struct timer_s timer;
484	  memset(&timer, 0, sizeof(struct timer_s));
485	
486	  timer.type = TIMER_TYPE_DAILY;
487	  timer.action = TIMER_ACTION_GREETING;
488	
489	  /* 设置触发时间 */
490	  time_t now = time(NULL);
491	  struct tm *tm_info = localtime(&now);
492	  struct tm trigger_tm;
493	  memset(&trigger_tm, 0, sizeof(struct tm));
494	  trigger_tm.tm_year = tm_info->tm_year;
495	  trigger_tm.tm_mon = tm_info->tm_mon;
496	  trigger_tm.tm_mday = tm_info->tm_mday;
497	  trigger_tm.tm_hour = hour;
498	  trigger_tm.tm_min = minute;
499	  trigger_tm.tm_sec = 0;
500	
501	  timer.trigger_time = mktime(&trigger_tm);
502	
503	  if (greeting)
504	    {
505	      strncpy(timer.message, greeting, sizeof(timer.message) - 1);
506	    }
507	  else
508	    {
509	      snprintf(timer.message, sizeof(timer.message),
510	               "问候：%02d:%02d", hour, minute);
511	    }
512	
513	  return timer_manager_create(&timer);
514	}
