/****************************************************************************
 * AI Butler - Timer Manager
 * 定时器管理模块 - 定时提醒、定时控制
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/board.h>
#include <debug.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <errno.h>

#include "timer_manager.h"
#include "env_monitor.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct timer_s g_timers[MAX_TIMERS];
static bool g_timer_manager_initialized = false;
static int g_next_timer_id = 1;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: timer_manager_find_timer
 *
 * Description:
 *   查找定时器
 *
 ****************************************************************************/

static struct timer_s *timer_manager_find_timer(int timer_id)
{
  for (int i = 0; i < MAX_TIMERS; i++)
    {
      if (g_timers[i].id == timer_id)
        {
          return &g_timers[i];
        }
    }

  return NULL;
}

/****************************************************************************
 * Name: timer_manager_find_empty
 *
 * Description:
 *   查找空闲定时器槽位
 *
 ****************************************************************************/

static struct timer_s *timer_manager_find_empty(void)
{
  for (int i = 0; i < MAX_TIMERS; i++)
    {
      if (g_timers[i].id == 0)
        {
          return &g_timers[i];
        }
    }

  return NULL;
}

/****************************************************************************
 * Name: timer_manager_calc_next_trigger
 *
 * Description:
 *   计算下次触发时间
 *
 ****************************************************************************/

static time_t timer_manager_calc_next_trigger(struct timer_s *timer)
{
  time_t now = time(NULL);
  struct tm *tm_info = localtime(&now);

  switch (timer->type)
    {
      case TIMER_TYPE_ONCE:
        /* 单次定时，直接返回设定时间 */
        return timer->trigger_time;

      case TIMER_TYPE_DAILY:
        {
          /* 每日重复，计算今天的触发时间 */
          struct tm trigger_tm;
          memset(&trigger_tm, 0, sizeof(struct tm));
          trigger_tm.tm_year = tm_info->tm_year;
          trigger_tm.tm_mon = tm_info->tm_mon;
          trigger_tm.tm_mday = tm_info->tm_mday;

          /* 从 trigger_time 中提取时分秒 */
          struct tm *trigger_info = localtime(&timer->trigger_time);
          trigger_tm.tm_hour = trigger_info->tm_hour;
          trigger_tm.tm_min = trigger_info->tm_min;
          trigger_tm.tm_sec = trigger_info->tm_sec;

          time_t today_trigger = mktime(&trigger_tm);

          /* 如果今天的触发时间已过，设置为明天 */
          if (today_trigger <= now)
            {
              today_trigger += 24 * 3600;
            }

          return today_trigger;
        }

      case TIMER_TYPE_WEEKLY:
        {
          /* 每周重复 */
          struct tm trigger_tm;
          memset(&trigger_tm, 0, sizeof(struct tm));
          trigger_tm.tm_year = tm_info->tm_year;
          trigger_tm.tm_mon = tm_info->tm_mon;
          trigger_tm.tm_mday = tm_info->tm_mday;

          struct tm *trigger_info = localtime(&timer->trigger_time);
          trigger_tm.tm_hour = trigger_info->tm_hour;
          trigger_tm.tm_min = trigger_info->tm_min;
          trigger_tm.tm_sec = trigger_info->tm_sec;
          trigger_tm.tm_wday = trigger_info->tm_wday;

          time_t this_week_trigger = mktime(&trigger_tm);

          /* 计算到目标星期几的天数 */
          int days_ahead = trigger_tm.tm_wday - tm_info->tm_wday;
          if (days_ahead < 0)
            {
              days_ahead += 7;
            }
          if (days_ahead == 0 && this_week_trigger <= now)
            {
              days_ahead = 7;
            }

          return this_week_trigger + days_ahead * 24 * 3600;
        }

      case TIMER_TYPE_INTERVAL:
        /* 间隔重复 */
        return now + timer->interval;

      default:
        return timer->trigger_time;
    }
}

/****************************************************************************
 * Name: timer_manager_execute_action
 *
 * Description:
 *   执行定时器动作
 *
 ****************************************************************************/

static int timer_manager_execute_action(struct timer_s *timer)
{
  board_info("Timer: Executing timer %d action\n", timer->id);

  switch (timer->action)
    {
      case TIMER_ACTION_RELAY_ON:
        env_monitor_control_relay(timer->relay_id, true);
        board_info("Timer: Relay %d ON\n", timer->relay_id);
        break;

      case TIMER_ACTION_RELAY_OFF:
        env_monitor_control_relay(timer->relay_id, false);
        board_info("Timer: Relay %d OFF\n", timer->relay_id);
        break;

      case TIMER_ACTION_REMIND:
        board_info("Timer: Reminder - %s\n", timer->message);
        /* 这里可以通过 TTS 播报提醒 */
        break;

      case TIMER_ACTION_GREETING:
        board_info("Timer: Greeting - %s\n", timer->message);
        /* 这里可以通过 TTS 播报问候 */
        break;

      default:
        board_warn("Timer: Unknown action %d\n", timer->action);
        break;
    }

  /* 执行回调函数 */
  if (timer->callback)
    {
      timer->callback(timer, timer->arg);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: timer_manager_init
 *
 * Description:
 *   初始化定时器管理模块
 *
 ****************************************************************************/

int timer_manager_init(void)
{
  board_info("Timer Manager: Initializing...\n");

  /* 清零定时器数组 */
  memset(g_timers, 0, sizeof(g_timers));
  g_next_timer_id = 1;

  g_timer_manager_initialized = true;
  board_info("Timer Manager: Initialized successfully\n");

  /* 创建默认的每日问候定时器 */
  timer_manager_create_daily_greeting(8, 0, "早上好！我是您的AI管家，祝您今天愉快！");
  timer_manager_create_daily_greeting(14, 0, "下午好！记得适当休息哦。");
  timer_manager_create_daily_greeting(20, 0, "晚上好！今天过得怎么样？");

  return OK;
}

/****************************************************************************
 * Name: timer_manager_deinit
 *
 * Description:
 *   反初始化定时器管理模块
 *
 ****************************************************************************/

int timer_manager_deinit(void)
{
  board_info("Timer Manager: Deinitializing...\n");
  g_timer_manager_initialized = false;
  return OK;
}

/****************************************************************************
 * Name: timer_manager_create
 *
 * Description:
 *   创建定时器
 *
 ****************************************************************************/

int timer_manager_create(struct timer_s *timer)
{
  if (!timer)
    {
      return -EINVAL;
    }

  struct timer_s *new_timer = timer_manager_find_empty();
  if (!new_timer)
    {
      board_err("Timer Manager: No empty timer slot\n");
      return -ENOMEM;
    }

  /* 复制定时器数据 */
  memcpy(new_timer, timer, sizeof(struct timer_s));

  /* 分配 ID */
  new_timer->id = g_next_timer_id++;

  /* 计算下次触发时间 */
  new_timer->next_trigger = timer_manager_calc_next_trigger(new_timer);

  /* 设置状态为启用 */
  new_timer->status = TIMER_STATUS_ENABLED;

  board_info("Timer Manager: Created timer %d, type=%d, next_trigger=%ld\n",
             new_timer->id, new_timer->type, (long)new_timer->next_trigger);

  return new_timer->id;
}

/****************************************************************************
 * Name: timer_manager_delete
 *
 * Description:
 *   删除定时器
 *
 ****************************************************************************/

int timer_manager_delete(int timer_id)
{
  struct timer_s *timer = timer_manager_find_timer(timer_id);
  if (!timer)
    {
      return -ENOENT;
    }

  /* 清零定时器 */
  memset(timer, 0, sizeof(struct timer_s));

  board_info("Timer Manager: Deleted timer %d\n", timer_id);
  return OK;
}

/****************************************************************************
 * Name: timer_manager_enable
 *
 * Description:
 *   启用定时器
 *
 ****************************************************************************/

int timer_manager_enable(int timer_id)
{
  struct timer_s *timer = timer_manager_find_timer(timer_id);
  if (!timer)
    {
      return -ENOENT;
    }

  timer->status = TIMER_STATUS_ENABLED;
  timer->next_trigger = timer_manager_calc_next_trigger(timer);

  board_info("Timer Manager: Enabled timer %d\n", timer_id);
  return OK;
}

/****************************************************************************
 * Name: timer_manager_disable
 *
 * Description:
 *   禁用定时器
 *
 ****************************************************************************/

int timer_manager_disable(int timer_id)
{
  struct timer_s *timer = timer_manager_find_timer(timer_id);
  if (!timer)
    {
      return -ENOENT;
    }

  timer->status = TIMER_STATUS_DISABLED;

  board_info("Timer Manager: Disabled timer %d\n", timer_id);
  return OK;
}

/****************************************************************************
 * Name: timer_manager_process
 *
 * Description:
 *   处理定时器（主循环调用）
 *
 ****************************************************************************/

int timer_manager_process(void)
{
  if (!g_timer_manager_initialized)
    {
      return -EINVAL;
    }

  time_t now = time(NULL);

  for (int i = 0; i < MAX_TIMERS; i++)
    {
      struct timer_s *timer = &g_timers[i];

      /* 跳过空定时器和禁用的定时器 */
      if (timer->id == 0 || timer->status != TIMER_STATUS_ENABLED)
        {
          continue;
        }

      /* 检查是否到达触发时间 */
      if (now >= timer->next_trigger)
        {
          /* 执行动作 */
          timer_manager_execute_action(timer);

          /* 根据类型处理 */
          switch (timer->type)
            {
              case TIMER_TYPE_ONCE:
                /* 单次定时，执行后禁用 */
                timer->status = TIMER_STATUS_FIRED;
                board_info("Timer: Timer %d fired (once)\n", timer->id);
                break;

              case TIMER_TYPE_DAILY:
              case TIMER_TYPE_WEEKLY:
              case TIMER_TYPE_INTERVAL:
                /* 重复定时，计算下次触发时间 */
                timer->next_trigger = timer_manager_calc_next_trigger(timer);
                board_info("Timer: Timer %d fired, next trigger=%ld\n",
                           timer->id, (long)timer->next_trigger);
                break;

              default:
                break;
            }
        }
    }

  return OK;
}

/****************************************************************************
 * Name: timer_manager_create_reminder
 *
 * Description:
 *   创建提醒定时器
 *
 ****************************************************************************/

int timer_manager_create_reminder(int seconds, const char *message)
{
  struct timer_s timer;
  memset(&timer, 0, sizeof(struct timer_s));

  timer.type = TIMER_TYPE_ONCE;
  timer.action = TIMER_ACTION_REMIND;
  timer.trigger_time = time(NULL) + seconds;
  timer.next_trigger = timer.trigger_time;

  if (message)
    {
      strncpy(timer.message, message, sizeof(timer.message) - 1);
    }
  else
    {
      snprintf(timer.message, sizeof(timer.message), "提醒：%d秒到了", seconds);
    }

  return timer_manager_create(&timer);
}

/****************************************************************************
 * Name: timer_manager_create_relay_timer
 *
 * Description:
 *   创建继电器定时器
 *
 ****************************************************************************/

int timer_manager_create_relay_timer(int relay, bool on, int delay_seconds)
{
  struct timer_s timer;
  memset(&timer, 0, sizeof(struct timer_s));

  timer.type = TIMER_TYPE_ONCE;
  timer.action = on ? TIMER_ACTION_RELAY_ON : TIMER_ACTION_RELAY_OFF;
  timer.trigger_time = time(NULL) + delay_seconds;
  timer.next_trigger = timer.trigger_time;
  timer.relay_id = relay;

  snprintf(timer.message, sizeof(timer.message),
           "%s继电器%d", on ? "开启" : "关闭", relay);

  return timer_manager_create(&timer);
}

/****************************************************************************
 * Name: timer_manager_create_daily_greeting
 *
 * Description:
 *   创建每日问候定时器
 *
 ****************************************************************************/

int timer_manager_create_daily_greeting(int hour, int minute, const char *greeting)
{
  struct timer_s timer;
  memset(&timer, 0, sizeof(struct timer_s));

  timer.type = TIMER_TYPE_DAILY;
  timer.action = TIMER_ACTION_GREETING;

  /* 设置触发时间 */
  time_t now = time(NULL);
  struct tm *tm_info = localtime(&now);
  struct tm trigger_tm;
  memset(&trigger_tm, 0, sizeof(struct tm));
  trigger_tm.tm_year = tm_info->tm_year;
  trigger_tm.tm_mon = tm_info->tm_mon;
  trigger_tm.tm_mday = tm_info->tm_mday;
  trigger_tm.tm_hour = hour;
  trigger_tm.tm_min = minute;
  trigger_tm.tm_sec = 0;

  timer.trigger_time = mktime(&trigger_tm);

  if (greeting)
    {
      strncpy(timer.message, greeting, sizeof(timer.message) - 1);
    }
  else
    {
      snprintf(timer.message, sizeof(timer.message),
               "问候：%02d:%02d", hour, minute);
    }

  return timer_manager_create(&timer);
}

