/****************************************************************************
 * AI Butler - Scene Manager
 * 场景管理模块 - 自动化场景联动
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/board.h>
#include <debug.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

#include "scene_manager.h"
#include "env_monitor.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct scene_s g_scenes[MAX_SCENES];
static bool g_scene_manager_initialized = false;
static int g_active_scene = SCENE_ID_NONE;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: scene_manager_find_scene
 *
 * Description:
 *   查找场景
 *
 ****************************************************************************/

static struct scene_s *scene_manager_find_scene(int scene_id)
{
  for (int i = 0; i < MAX_SCENES; i++)
    {
      if (g_scenes[i].id == scene_id)
        {
          return &g_scenes[i];
        }
    }

  return NULL;
}

/****************************************************************************
 * Name: scene_manager_find_empty
 *
 * Description:
 *   查找空闲场景槽位
 *
 ****************************************************************************/

static struct scene_s *scene_manager_find_empty(void)
{
  for (int i = 0; i < MAX_SCENES; i++)
    {
      if (g_scenes[i].id == 0)
        {
          return &g_scenes[i];
        }
    }

  return NULL;
}

/****************************************************************************
 * Name: scene_manager_execute_actions
 *
 * Description:
 *   执行场景动作
 *
 ****************************************************************************/

static int scene_manager_execute_actions(struct scene_s *scene)
{
  if (!scene)
    {
      return -EINVAL;
    }

  board_info("Scene: Executing scene '%s' (%d actions)\n",
             scene->name, scene->action_count);

  for (int i = 0; i < scene->action_count; i++)
    {
      struct scene_action_s *action = &scene->actions[i];

      /* 延时 */
      if (action->delay_ms > 0)
        {
          usleep(action->delay_ms * 1000);
        }

      /* 执行继电器动作 */
      if (action->relay_id > 0)
        {
          env_monitor_control_relay(action->relay_id, action->relay_state);
          board_info("Scene: Relay %d -> %s\n",
                     action->relay_id,
                     action->relay_state ? "ON" : "OFF");
        }
    }

  /* 执行回调函数 */
  if (scene->callback)
    {
      scene->callback(scene, scene->arg);
    }

  return OK;
}

/****************************************************************************
 * Name: scene_manager_check_trigger
 *
 * Description:
 *   检查场景触发条件
 *
 ****************************************************************************/

static bool scene_manager_check_trigger(struct scene_s *scene, const struct env_data_s *env_data)
{
  if (!scene || !env_data)
    {
      return false;
    }

  switch (scene->trigger.type)
    {
      case SCENE_TRIGGER_TIME:
        {
          /* 时间触发 */
          time_t now = time(NULL);
          struct tm *tm_info = localtime(&now);

          return (tm_info->tm_hour == scene->trigger.hour &&
                  tm_info->tm_min == scene->trigger.minute);
        }

      case SCENE_TRIGGER_SENSOR:
        {
          /* 传感器触发 */
          if (scene->trigger.temp_threshold > 0)
            {
              if (scene->trigger.above_threshold)
                {
                  if (env_data->temperature < scene->trigger.temp_threshold)
                    {
                      return false;
                    }
                }
              else
                {
                  if (env_data->temperature > scene->trigger.temp_threshold)
                    {
                      return false;
                    }
                }
            }

          if (scene->trigger.humidity_threshold > 0)
            {
              if (scene->trigger.above_threshold)
                {
                  if (env_data->humidity < scene->trigger.humidity_threshold)
                    {
                      return false;
                    }
                }
              else
                {
                  if (env_data->humidity > scene->trigger.humidity_threshold)
                    {
                      return false;
                    }
                }
            }

          if (scene->trigger.co2_threshold > 0)
            {
              if (scene->trigger.above_threshold)
                {
                  if (env_data->co2 < scene->trigger.co2_threshold)
                    {
                      return false;
                    }
                }
              else
                {
                  if (env_data->co2 > scene->trigger.co2_threshold)
                    {
                      return false;
                    }
                }
            }

          return true;
        }

      default:
        return false;
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: scene_manager_init
 *
 * Description:
 *   初始化场景管理模块
 *
 ****************************************************************************/

int scene_manager_init(void)
{
  board_info("Scene Manager: Initializing...\n");

  /* 清零场景数组 */
  memset(g_scenes, 0, sizeof(g_scenes));
  g_active_scene = SCENE_ID_NONE;

  g_scene_manager_initialized = true;
  board_info("Scene Manager: Initialized successfully\n");

  /* 创建默认场景 */

  /* 起床场景 */
  struct scene_s morning_scene;
  memset(&morning_scene, 0, sizeof(struct scene_s));
  morning_scene.id = SCENE_ID_MORNING;
  morning_scene.status = SCENE_STATUS_ENABLED;
  morning_scene.trigger_type = SCENE_TRIGGER_TIME;
  morning_scene.trigger.type = SCENE_TRIGGER_TIME;
  morning_scene.trigger.hour = 7;
  morning_scene.trigger.minute = 0;
  morning_scene.actions[0] = (struct scene_action_s){RELAY_LIGHT, true, 0};
  morning_scene.actions[1] = (struct scene_action_s){RELAY_FAN, false, 500};
  morning_scene.action_count = 2;
  strncpy(morning_scene.name, "起床", sizeof(morning_scene.name) - 1);
  strncpy(morning_scene.description, "早上7点自动开灯、关风扇",
          sizeof(morning_scene.description) - 1);
  scene_manager_create(&morning_scene);

  /* 睡眠场景 */
  struct scene_s night_scene;
  memset(&night_scene, 0, sizeof(struct scene_s));
  night_scene.id = SCENE_ID_NIGHT;
  night_scene.status = SCENE_STATUS_ENABLED;
  night_scene.trigger_type = SCENE_TRIGGER_TIME;
  night_scene.trigger.type = SCENE_TRIGGER_TIME;
  night_scene.trigger.hour = 23;
  night_scene.trigger.minute = 0;
  night_scene.actions[0] = (struct scene_action_s){RELAY_LIGHT, false, 0};
  night_scene.actions[1] = (struct scene_action_s){RELAY_FAN, true, 500};
  night_scene.actions[2] = (struct scene_action_s){RELAY_HUMIDIFIER, true, 1000};
  night_scene.action_count = 3;
  strncpy(night_scene.name, "睡眠", sizeof(night_scene.name) - 1);
  strncpy(night_scene.description, "晚上11点自动关灯、开风扇、开加湿器",
          sizeof(night_scene.description) - 1);
  scene_manager_create(&night_scene);

  /* 工作场景 */
  struct scene_s work_scene;
  memset(&work_scene, 0, sizeof(struct scene_s));
  work_scene.id = SCENE_ID_WORK;
  work_scene.status = SCENE_STATUS_ENABLED;
  work_scene.trigger_type = SCENE_TRIGGER_MANUAL;
  work_scene.actions[0] = (struct scene_action_s){RELAY_LIGHT, true, 0};
  work_scene.actions[1] = (struct scene_action_s){RELAY_FAN, false, 500};
  work_scene.actions[2] = (struct scene_action_s){RELAY_HUMIDIFIER, false, 1000};
  work_scene.action_count = 3;
  strncpy(work_scene.name, "工作", sizeof(work_scene.name) - 1);
  strncpy(work_scene.description, "开启灯光，关闭风扇和加湿器",
          sizeof(work_scene.description) - 1);
  scene_manager_create(&work_scene);

  /* 休息场景 */
  struct scene_s relax_scene;
  memset(&relax_scene, 0, sizeof(struct scene_s));
  relax_scene.id = SCENE_ID_RELAX;
  relax_scene.status = SCENE_STATUS_ENABLED;
  relax_scene.trigger_type = SCENE_TRIGGER_MANUAL;
  relax_scene.actions[0] = (struct scene_action_s){RELAY_LIGHT, false, 0};
  relax_scene.actions[1] = (struct scene_action_s){RELAY_FAN, true, 500};
  relax_scene.action_count = 2;
  strncpy(relax_scene.name, "休息", sizeof(relax_scene.name) - 1);
  strncpy(relax_scene.description, "关闭灯光，开启风扇",
          sizeof(relax_scene.description) - 1);
  scene_manager_create(&relax_scene);

  return OK;
}

/****************************************************************************
 * Name: scene_manager_deinit
 *
 * Description:
 *   反初始化场景管理模块
 *
 ****************************************************************************/

int scene_manager_deinit(void)
{
  board_info("Scene Manager: Deinitializing...\n");
  g_scene_manager_initialized = false;
  return OK;
}

/****************************************************************************
 * Name: scene_manager_create
 *
 * Description:
 *   创建场景
 *
 ****************************************************************************/

int scene_manager_create(struct scene_s *scene)
{
  if (!scene)
    {
      return -EINVAL;
    }

  struct scene_s *new_scene = scene_manager_find_empty();
  if (!new_scene)
    {
      board_err("Scene Manager: No empty scene slot\n");
      return -ENOMEM;
    }

  /* 复制场景数据 */
  memcpy(new_scene, scene, sizeof(struct scene_s));

  /* 如果没有ID，分配一个 */
  if (new_scene->id == 0)
    {
      for (int i = 1; i <= MAX_SCENES; i++)
        {
          if (!scene_manager_find_scene(i))
            {
              new_scene->id = i;
              break;
            }
        }
    }

  board_info("Scene Manager: Created scene '%s' (id=%d)\n",
             new_scene->name, new_scene->id);

  return new_scene->id;
}

/****************************************************************************
 * Name: scene_manager_delete
 *
 * Description:
 *   删除场景
 *
 ****************************************************************************/

int scene_manager_delete(int scene_id)
{
  struct scene_s *scene = scene_manager_find_scene(scene_id);
  if (!scene)
    {
      return -ENOENT;
    }

  /* 如果是当前活动场景，先停用 */
  if (g_active_scene == scene_id)
    {
      g_active_scene = SCENE_ID_NONE;
    }

  /* 清零场景 */
  memset(scene, 0, sizeof(struct scene_s));

  board_info("Scene Manager: Deleted scene %d\n", scene_id);
  return OK;
}

/****************************************************************************
 * Name: scene_manager_activate
 *
 * Description:
 *   激活场景
 *
 ****************************************************************************/

int scene_manager_activate(int scene_id)
{
  struct scene_s *scene = scene_manager_find_scene(scene_id);
  if (!scene)
    {
      return -ENOENT;
    }

  /* 执行场景动作 */
  scene_manager_execute_actions(scene);

  /* 更新状态 */
  scene->status = SCENE_STATUS_ACTIVE;
  g_active_scene = scene_id;

  board_info("Scene Manager: Activated scene '%s'\n", scene->name);
  return OK;
}

/****************************************************************************
 * Name: scene_manager_deactivate
 *
 * Description:
 *   停用场景
 *
 ****************************************************************************/

int scene_manager_deactivate(int scene_id)
{
  struct scene_s *scene = scene_manager_find_scene(scene_id);
  if (!scene)
    {
      return -ENOENT;
    }

  /* 更新状态 */
  scene->status = SCENE_STATUS_ENABLED;

  if (g_active_scene == scene_id)
    {
      g_active_scene = SCENE_ID_NONE;
    }

  board_info("Scene Manager: Deactivated scene '%s'\n", scene->name);
  return OK;
}

/****************************************************************************
 * Name: scene_manager_process
 *
 * Description:
 *   处理场景（主循环调用）
 *
 ****************************************************************************/

int scene_manager_process(void)
{
  if (!g_scene_manager_initialized)
    {
      return -EINVAL;
    }

  /* 读取当前环境数据 */
  struct env_data_s env_data;
  memset(&env_data, 0, sizeof(struct env_data_s));

  /* 获取环境数据（简化实现，实际应该调用 env_monitor_read） */
  env_data.temperature = 25.0f;
  env_data.humidity = 50.0f;
  env_data.co2 = 500;

  /* 检查所有启用的场景 */
  for (int i = 0; i < MAX_SCENES; i++)
    {
      struct scene_s *scene = &g_scenes[i];

      /* 跳过空场景和禁用的场景 */
      if (scene->id == 0 || scene->status != SCENE_STATUS_ENABLED)
        {
          continue;
        }

      /* 跳过已经是活动状态的场景 */
      if (scene->id == g_active_scene)
        {
          continue;
        }

      /* 检查触发条件 */
      if (scene_manager_check_trigger(scene, &env_data))
        {
          /* 触发场景 */
          board_info("Scene: Scene '%s' triggered\n", scene->name);
          scene_manager_activate(scene->id);
        }
    }

  return OK;
}

/****************************************************************************
 * Name: scene_manager_get_scene
 *
 * Description:
 *   获取场景信息
 *
 ****************************************************************************/

struct scene_s *scene_manager_get_scene(int scene_id)
{
  return scene_manager_find_scene(scene_id);
}

/****************************************************************************
 * Name: scene_manager_list_scenes
 *
 * Description:
 *   列出所有场景
 *
 ****************************************************************************/

int scene_manager_list_scenes(void)
{
  board_info("=== Scene List ===\n");

  for (int i = 0; i < MAX_SCENES; i++)
    {
      struct scene_s *scene = &g_scenes[i];

      if (scene->id == 0)
        {
          continue;
        }

      const char *status_str;
      switch (scene->status)
        {
          case SCENE_STATUS_DISABLED:
            status_str = "DISABLED";
            break;
          case SCENE_STATUS_ENABLED:
            status_str = "ENABLED";
            break;
          case SCENE_STATUS_ACTIVE:
            status_str = "ACTIVE";
            break;
          default:
            status_str = "UNKNOWN";
            break;
        }

      board_info("  [%d] %s - %s (%s)\n",
                 scene->id, scene->name, scene->description, status_str);
    }

  board_info("==================\n");
  return OK;
}

