19	
20	/****************************************************************************
21	 * Pre-processor Definitions
22	 ****************************************************************************/
23	
24	/* ESP32 AT 指令 */
25	#define AT_CMD_TEST         "AT\r\n"
26	#define AT_CMD_RESET        "AT+RST\r\n"
27	#define AT_CMD_WIFI_MODE    "AT+CWMODE=1\r\n"
28	#define AT_CMD_WIFI_JOIN    "AT+CWJAP=\"%s\",\"%s\"\r\n"
29	#define AT_CMD_IP_STATUS    "AT+CIFSR\r\n"
30	#define AT_CMD_HTTPS_START  "AT+HTTPCLIENT=\"https://%s\",4\r\n"
31	
32	/* 响应缓冲区大小 */
33	#define AT_RESPONSE_SIZE    512
34	#define HTTP_RESPONSE_SIZE  4096
35	
36	/* JSON 缓冲区大小 */
37	#define JSON_BUFFER_SIZE    2048
38	
39	/****************************************************************************
40	 * Private Data
41	 ****************************************************************************/
42	
43	static struct cloud_status_s g_cloud_status;
44	static bool g_cloud_initialized = false;
45	static bool g_wifi_connected = false;
46	
47	/* UART2 句柄 */
48	static int g_uart2_fd = -1;
49	
50	/****************************************************************************
51	 * Private Functions
52	 ****************************************************************************/
53	
54	#ifdef CONFIG_USART2
55	/****************************************************************************
56	 * Name: esp32_send_command
57	 *
58	 * Description:
59	 *   发送 AT 指令到 ESP32
60	 *
61	 ****************************************************************************/
62	
63	static int esp32_send_command(const char *cmd, char *response, size_t response_size)
64	{
65	  if (g_uart2_fd < 0)
66	    {
67	      return -ENODEV;
68	    }
69	
70	  /* 清空响应缓冲区 */
71	  memset(response, 0, response_size);
72	
73	  /* 发送指令 */
74	  size_t cmd_len = strlen(cmd);
75	  ssize_t written = write(g_uart2_fd, cmd, cmd_len);
76	  if (written != cmd_len)
77	    {
78	      board_err("Cloud: Failed to send AT command\n");
79	      return -EIO;
80	    }
81	
82	  /* 等待响应 */
83	  usleep(100000);  /* 100ms */
84	
85	  /* 读取响应 */
86	  ssize_t bytes_read = read(g_uart2_fd, response, response_size - 1);
87	  if (bytes_read < 0)
88	    {
89	      board_err("Cloud: Failed to read AT response\n");
90	      return -EIO;
91	    }
92	
93	  response[bytes_read] = '\0';
94	
95	  board_debug("Cloud: AT response: %s\n", response);
96	
97	  return OK;
98	}
99	
100	/****************************************************************************
101	 * Name: esp32_check_response
102	 *
103	 * Description:
104	 *   检查 AT 指令响应
105	 *
106	 ****************************************************************************/
107	
108	static bool esp32_check_response(const char *response, const char *expected)
109	{
110	  return (strstr(response, expected) != NULL);
111	}
112	#endif
113	
114	/****************************************************************************
115	 * Public Functions
116	 ****************************************************************************/
117	
118	/****************************************************************************
119	 * Name: cloud_connector_init
120	 *
121	 * Description:
122	 *   初始化云连接模块
123	 *
124	 ****************************************************************************/
125	
126	int cloud_connector_init(void)
127	{
128	  board_info("Cloud Connector: Initializing...\n");
129	
130	  /* 清零状态 */
131	  memset(&g_cloud_status, 0, sizeof(struct cloud_status_s));
132	  g_wifi_connected = false;
133	
134	#ifdef CONFIG_USART2
135	  /* 打开 UART2 */
136	  g_uart2_fd = open("/dev/ttyS1", O_RDWR);
137	  if (g_uart2_fd < 0)
138	    {
139	      board_err("Cloud: Failed to open UART2\n");
140	      return -errno;
141	    }
142	
143	  /* 配置 UART2 */
144	  struct termios tty;
