## 三、软件实现

### 3.1 系统初始化

#### 3.1.1 启动流程

```
1. 硬件复位
   ↓
2. bootloader 启动
   ↓
3. board_boot.c: gd32_boardinitialize()
   - 时钟配置 (240 MHz)
   - GPIO 初始化
   - 串口初始化
   ↓
4. board_appinit.c: board_app_initialize()
   - 外设驱动注册
   - 文件系统挂载
   ↓
5. ai_butler_main.c: ai_butler_main()
   - 模块初始化
   - 任务创建
   - 主循环启动
```

#### 3.1.2 初始化代码

```c
// board_boot.c
void gd32_boardinitialize(void) {
    // 时钟配置
    system_clock_config();

    // GPIO 初始化
    gpio_init();

    // 串口初始化
    usart_init(USART0, 115200);
}

// board_appinit.c
int board_app_initialize(uintptr_t arg) {
    // 外设驱动注册
    i2c_register("/dev/i2c0", I2C0);
    usart_register("/dev/ttyS0", USART0);

    return OK;
}

// ai_butler_main.c
int ai_butler_main(int argc, char *argv[]) {
    // 模块初始化
    env_monitor_init();
    timer_manager_init();
    scene_manager_init();
    cloud_connector_init();

    // 主循环
    while (1) {
        // 处理定时任务
        timer_manager_process();

        // 处理场景触发
        scene_manager_process();

        // 环境监测
        env_monitor_process();

        // 延时 10ms
        usleep(10000);
    }

    return OK;
}
```

### 3.2 环境监测模块

#### 3.2.1 功能设计

- **监测参数**: 温度、湿度、CO2 浓度
- **采样周期**: 30 秒
- **告警阈值**:
  - 温度 > 28°C
  - 湿度 < 40%
  - CO2 > 1000 ppm

#### 3.2.2 数据结构

```c
// 环境数据
struct env_data_s {
    float temperature;      // 温度 (°C)
    float humidity;         // 湿度 (%)
    int   co2;              // CO2 浓度 (ppm)
    time_t timestamp;       // 时间戳
};

// 告警阈值
struct env_threshold_s {
    float temp_high;        // 温度上限
    float temp_low;         // 温度下限
    float humidity_high;    // 湿度上限
    float humidity_low;     // 湿度下限
    int   co2_high;         // CO2 上限
    int   co2_low;          // CO2 下限
};

// 告警类型
enum env_alert_type_e {
    ALERT_TEMP_HIGH,        // 温度过高
    ALERT_TEMP_LOW,         // 温度过低
    ALERT_HUMIDITY_HIGH,    // 湿度过高
    ALERT_HUMIDITY_LOW,     // 湿度过低
    ALERT_CO2_HIGH,         // CO2 过高
    ALERT_CO2_LOW           // CO2 过低
};
```

#### 3.2.3 核心算法

```c
// 环境监测主循环
int env_monitor_read(struct env_data_s *data)
{
  if (!g_env_monitor_initialized || !data)
    {
      return -EINVAL;
    }

  int ret = OK;

#ifdef CONFIG_I2C
  /* 读取温湿度 */
  ret = sht30_read(&data->temperature, &data->humidity);
  if (ret < 0)
    {
      board_err("Env Monitor: Failed to read SHT30\n");
      /* 使用默认值 */
      data->temperature = 25.0f;
      data->humidity = 50.0f;
    }
#else
  /* 模拟数据 */
  data->temperature = 25.0f;
  data->humidity = 50.0f;
#endif

#ifdef CONFIG_UART3
  /* 读取 CO2 */
  ret = mhz19b_read(&data->co2);
  if (ret < 0)
    {
      board_err("Env Monitor: Failed to read MH-Z19B\n");
      /* 使用默认值 */
      data->co2 = 500;
    }
#else
  /* 模拟数据 */
  data->co2 = 500;
#endif

  /* 更新时间戳 */
  data->timestamp = clock_systime_ticks();

  /* 保存到全局变量 */
  memcpy(&g_env_data, data, sizeof(struct env_data_s));

  board_info("Env Monitor: Temp=%.1f°C, Humidity=%.1f%%, CO2=%dppm\n",
             data->temperature, data->humidity, data->co2);

  return OK;
}

// 告警检查
int env_monitor_check_alerts(const struct env_data_s *data, struct env_alert_s *alert)
{
  if (!data || !alert)
    {
      return -EINVAL;
    }

  alert->type = ALERT_TYPE_NONE;
  alert->auto_action = false;

  /* 检查温度高 */
  if (data->temperature > TEMP_HIGH_THRESHOLD)
    {
      alert->type = ALERT_TYPE_TEMP_HIGH;
      alert->value = data->temperature;
      alert->threshold = TEMP_HIGH_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "⚠️ 温度过高：%.1f°C (阈值：%.1f°C)",
               data->temperature, TEMP_HIGH_THRESHOLD);
      alert->auto_action = true;
      return OK;
    }

  /* 检查湿度低 */
  if (data->humidity < HUMIDITY_LOW_THRESHOLD)
    {
      alert->type = ALERT_TYPE_HUMIDITY_LOW;
      alert->value = data->humidity;
      alert->threshold = HUMIDITY_LOW_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "⚠️ 湿度过低：%.1f%% (阈值：%.1f%%)",
               data->humidity, HUMIDITY_LOW_THRESHOLD);
      alert->auto_action = true;
      return OK;
    }

  /* 检查 CO2 高 */
  if (data->co2 > CO2_HIGH_THRESHOLD)
    {
      alert->type = ALERT_TYPE_CO2_HIGH;
      alert->value = data->co2;
      alert->threshold = CO2_HIGH_THRESHOLD;
      snprintf(alert->message, sizeof(alert->message),
               "⚠️ CO2浓度偏高：%dppm (阈值：%dppm)，建议通风",
               data->co2, CO2_HIGH_THRESHOLD);
      alert->auto_action = true;
      return OK;
    }

  return OK;
}
```

### 3.3 定时管理模块

#### 3.3.1 功能设计

- **定时器类型**:
  - 单次定时 (TIMER_TYPE_ONCE)
  - 每日定时 (TIMER_TYPE_DAILY)
  - 每周定时 (TIMER_TYPE_WEEKLY)
  - 间隔定时 (TIMER_TYPE_INTERVAL)

- **动作类型**:
  - 继电器开 (RELAY_ON)
  - 继电器关 (RELAY_OFF)
  - 提醒 (REMIND)
  - 问候 (GREETING)

#### 3.3.2 数据结构

```c
// 定时器结构
struct timer_s {
    int id;                     // 定时器ID
    char name[32];              // 定时器名称
    int type;                   // 定时器类型
    int hour;                   // 小时
    int minute;                 // 分钟
    int weekday;                // 星期 (0-6)
    int interval;               // 间隔 (秒)
    int action;                 // 动作类型
    int relay_id;               // 继电器ID
    bool enabled;               // 启用状态
    time_t next_trigger;        // 下次触发时间
};

// 定时器管理器
struct timer_manager_s {
    struct timer_s timers[MAX_TIMERS];  // 定时器数组
    int count;                          // 定时器数量
};
```

#### 3.3.3 核心算法

```c
// 定时器处理主循环
int timer_manager_process(void)
{
  if (!g_timer_manager_initialized)
    {
      return -EINVAL;
    }

  time_t now = time(NULL);

  for (int i = 0; i < MAX_TIMERS; i++)
    {
      struct timer_s *timer = &g_timers[i];

      /* 跳过空定时器和禁用的定时器 */
      if (timer->id == 0 || timer->status != TIMER_STATUS_ENABLED)
        {
          continue;
        }

      /* 检查是否到达触发时间 */
      if (now >= timer->next_trigger)
        {
          /* 执行动作 */
          timer_manager_execute_action(timer);

          /* 根据类型处理 */
          switch (timer->type)
            {
              case TIMER_TYPE_ONCE:
                /* 单次定时，执行后禁用 */
                timer->status = TIMER_STATUS_FIRED;
                board_info("Timer: Timer %d fired (once)\n", timer->id);
                break;

              case TIMER_TYPE_DAILY:
              case TIMER_TYPE_WEEKLY:
              case TIMER_TYPE_INTERVAL:
                /* 重复定时，计算下次触发时间 */
                timer->next_trigger = timer_manager_calc_next_trigger(timer);
                board_info("Timer: Timer %d fired, next trigger=%ld\n",
                           timer->id, (long)timer->next_trigger);
                break;

              default:
                break;
            }
        }
    }

  return OK;
}

// 执行定时动作
static int timer_manager_execute_action(struct timer_s *timer)
{
  board_info("Timer: Executing timer %d action\n", timer->id);

  switch (timer->action)
    {
      case TIMER_ACTION_RELAY_ON:
        env_monitor_control_relay(timer->relay_id, true);
        board_info("Timer: Relay %d ON\n", timer->relay_id);
        break;

      case TIMER_ACTION_RELAY_OFF:
        env_monitor_control_relay(timer->relay_id, false);
        board_info("Timer: Relay %d OFF\n", timer->relay_id);
        break;

      case TIMER_ACTION_REMIND:
        board_info("Timer: Reminder - %s\n", timer->message);
        /* 这里可以通过 TTS 播报提醒 */
        break;

      case TIMER_ACTION_GREETING:
        board_info("Timer: Greeting - %s\n", timer->message);
        /* 这里可以通过 TTS 播报问候 */
        break;

      default:
        board_warn("Timer: Unknown action %d\n", timer->action);
        break;
    }

  /* 执行回调函数 */
  if (timer->callback)
    {
      timer->callback(timer, timer->arg);
    }

  return OK;
}

// 计算下次触发时间
static time_t timer_manager_calc_next_trigger(struct timer_s *timer)
{
  time_t now = time(NULL);
  struct tm *tm_info = localtime(&now);

  switch (timer->type)
    {
      case TIMER_TYPE_ONCE:
        /* 单次定时，直接返回设定时间 */
        return timer->trigger_time;

      case TIMER_TYPE_DAILY:
        {
          /* 每日重复，计算今天的触发时间 */
          struct tm trigger_tm;
          memset(&trigger_tm, 0, sizeof(struct tm));
          trigger_tm.tm_year = tm_info->tm_year;
          trigger_tm.tm_mon = tm_info->tm_mon;
          trigger_tm.tm_mday = tm_info->tm_mday;

          /* 从 trigger_time 中提取时分秒 */
          struct tm *trigger_info = localtime(&timer->trigger_time);
          trigger_tm.tm_hour = trigger_info->tm_hour;
          trigger_tm.tm_min = trigger_info->tm_min;
          trigger_tm.tm_sec = trigger_info->tm_sec;

          time_t today_trigger = mktime(&trigger_tm);

          /* 如果今天的触发时间已过，设置为明天 */
          if (today_trigger <= now)
            {
              today_trigger += 24 * 3600;
            }

          return today_trigger;
        }

      case TIMER_TYPE_WEEKLY:
        {
          /* 每周重复 */
          struct tm trigger_tm;
          memset(&trigger_tm, 0, sizeof(struct tm));
          trigger_tm.tm_year = tm_info->tm_year;
          trigger_tm.tm_mon = tm_info->tm_mon;
          trigger_tm.tm_mday = tm_info->tm_mday;

          struct tm *trigger_info = localtime(&timer->trigger_time);
          trigger_tm.tm_hour = trigger_info->tm_hour;
          trigger_tm.tm_min = trigger_info->tm_min;
          trigger_tm.tm_sec = trigger_info->tm_sec;
          trigger_tm.tm_wday = trigger_info->tm_wday;

          time_t this_week_trigger = mktime(&trigger_tm);

          /* 计算到目标星期几的天数 */
          int days_ahead = trigger_tm.tm_wday - tm_info->tm_wday;
          if (days_ahead < 0)
            {
              days_ahead += 7;
            }
          if (days_ahead == 0 && this_week_trigger <= now)
            {
              days_ahead = 7;
            }

          return this_week_trigger + days_ahead * 24 * 3600;
        }

      case TIMER_TYPE_INTERVAL:
        /* 间隔重复 */
        return now + timer->interval;

      default:
        return timer->trigger_time;
    }
}
```

### 3.4 场景管理模块

#### 3.4.1 功能设计

- **场景类型**:
  - 起床场景 (07:00)
  - 睡眠场景 (23:00)
  - 工作场景 (手动)
  - 休息场景 (手动)

- **触发方式**:
  - 时间触发 (SCENE_TRIGGER_TIME)
  - 传感器触发 (SCENE_TRIGGER_SENSOR)
  - 手动触发 (SCENE_TRIGGER_MANUAL)
  - 语音触发 (SCENE_TRIGGER_VOICE)

#### 3.4.2 数据结构

```c
// 场景动作
struct scene_action_s {
    int relay_id;           // 继电器ID
    bool state;             // 动作状态
    int delay_ms;           // 延时 (毫秒)
};

// 场景触发
struct scene_trigger_s {
    int type;               // 触发类型
    int hour;               // 小时
    int minute;             // 分钟
    int sensor_type;        // 传感器类型
    float threshold;        // 阈值
};

// 场景结构
struct scene_s {
    int id;                     // 场景ID
    char name[32];              // 场景名称
    struct scene_trigger_s trigger;  // 触发条件
    struct scene_action_s actions[4]; // 动作列表
    int action_count;           // 动作数量
    bool enabled;               // 启用状态
};

// 场景管理器
struct scene_manager_s {
    struct scene_s scenes[MAX_SCENES];  // 场景数组
    int count;                          // 场景数量
    int active_scene;                   // 当前活动场景
};
```

#### 3.4.3 核心算法

```c
// 场景处理主循环
int scene_manager_process(void)
{
  if (!g_scene_manager_initialized)
    {
      return -EINVAL;
    }

  /* 读取当前环境数据 */
  struct env_data_s env_data;
  memset(&env_data, 0, sizeof(struct env_data_s));

  /* 获取环境数据（简化实现，实际应该调用 env_monitor_read） */
  env_data.temperature = 25.0f;
  env_data.humidity = 50.0f;
  env_data.co2 = 500;

  /* 检查所有启用的场景 */
  for (int i = 0; i < MAX_SCENES; i++)
    {
      struct scene_s *scene = &g_scenes[i];

      /* 跳过空场景和禁用的场景 */
      if (scene->id == 0 || scene->status != SCENE_STATUS_ENABLED)
        {
          continue;
        }

      /* 跳过已经是活动状态的场景 */
      if (scene->id == g_active_scene)
        {
          continue;
        }

      /* 检查触发条件 */
      if (scene_manager_check_trigger(scene, &env_data))
        {
          /* 触发场景 */
          board_info("Scene: Scene '%s' triggered\n", scene->name);
          scene_manager_activate(scene->id);
        }
    }

  return OK;
}

// 检查场景触发
static bool scene_manager_check_trigger(struct scene_s *scene, const struct env_data_s *env_data)
{
  if (!scene || !env_data)
    {
      return false;
    }

  switch (scene->trigger.type)
    {
      case SCENE_TRIGGER_TIME:
        {
          /* 时间触发 */
          time_t now = time(NULL);
          struct tm *tm_info = localtime(&now);

          return (tm_info->tm_hour == scene->trigger.hour &&
                  tm_info->tm_min == scene->trigger.minute);
        }

      case SCENE_TRIGGER_SENSOR:
        {
          /* 传感器触发 */
          if (scene->trigger.temp_threshold > 0)
            {
              if (scene->trigger.above_threshold)
                {
                  if (env_data->temperature < scene->trigger.temp_threshold)
                    {
                      return false;
                    }
                }
              else
                {
                  if (env_data->temperature > scene->trigger.temp_threshold)
                    {
                      return false;
                    }
                }
            }

          if (scene->trigger.humidity_threshold > 0)
            {
              if (scene->trigger.above_threshold)
                {
                  if (env_data->humidity < scene->trigger.humidity_threshold)
                    {
                      return false;
                    }
                }
              else
                {
                  if (env_data->humidity > scene->trigger.humidity_threshold)
                    {
                      return false;
                    }
                }
            }

          if (scene->trigger.co2_threshold > 0)
            {
              if (scene->trigger.above_threshold)
                {
                  if (env_data->co2 < scene->trigger.co2_threshold)
                    {
                      return false;
                    }
                }
              else
                {
                  if (env_data->co2 > scene->trigger.co2_threshold)
                    {
                      return false;
                    }
                }
            }

          return true;
        }

      default:
        return false;
    }
}

// 执行场景动作
static int scene_manager_execute_actions(struct scene_s *scene)
{
  if (!scene)
    {
      return -EINVAL;
    }

  board_info("Scene: Executing scene '%s' (%d actions)\n",
             scene->name, scene->action_count);

  for (int i = 0; i < scene->action_count; i++)
    {
      struct scene_action_s *action = &scene->actions[i];

      /* 延时 */
      if (action->delay_ms > 0)
        {
          usleep(action->delay_ms * 1000);
        }

      /* 执行继电器动作 */
      if (action->relay_id > 0)
        {
          env_monitor_control_relay(action->relay_id, action->relay_state);
          board_info("Scene: Relay %d -> %s\n",
                     action->relay_id,
                     action->relay_state ? "ON" : "OFF");
        }
    }

  /* 执行回调函数 */
  if (scene->callback)
    {
      scene->callback(scene, scene->arg);
    }

  return OK;
}
```

