### 2.5 通信模块

#### 2.5.1 ESP32 WiFi 模块

- **接口**: UART2 (115200 baud)
- **协议**: AT 指令
- **功能**:
  - WiFi 连接
  - TCP/UDP 通信
  - HTTP 请求
  - WebSocket 连接

- **AT 指令实现** (基于 NuttX UART API):
```c
static int esp32_send_command(const char *cmd, char *response, size_t response_size)
{
  if (g_uart2_fd < 0)
    {
      return -ENODEV;
    }

  /* 清空响应缓冲区 */
  memset(response, 0, response_size);

  /* 发送指令 */
  size_t cmd_len = strlen(cmd);
  ssize_t written = write(g_uart2_fd, cmd, cmd_len);
  if (written != cmd_len)
    {
      board_err("Cloud: Failed to send AT command\n");
      return -EIO;
    }

  /* 等待响应 */
  usleep(100000);  /* 100ms */

  /* 读取响应 */
  ssize_t bytes_read = read(g_uart2_fd, response, response_size - 1);
  if (bytes_read < 0)
    {
      board_err("Cloud: Failed to read AT response\n");
      return -EIO;
    }

  response[bytes_read] = '\0';

  board_debug("Cloud: AT response: %s\n", response);

  return OK;
}

/* WiFi 连接函数 */
int cloud_connector_wifi_connect(const char *ssid, const char *password)
{
  if (!ssid || !password)
    {
      return -EINVAL;
    }

  board_info("Cloud: Connecting to WiFi '%s'...\n", ssid);

  g_cloud_status.wifi_status = CLOUD_STATUS_CONNECTING;

#ifdef CONFIG_USART2
  char cmd[128];
  char response[AT_RESPONSE_SIZE];

  /* 构建连接指令 */
  snprintf(cmd, sizeof(cmd), AT_CMD_WIFI_JOIN, ssid, password);

  /* 发送指令 */
  if (esp32_send_command(cmd, response, sizeof(response)) == OK)
    {
      if (esp32_check_response(response, "OK"))
        {
          board_info("Cloud: WiFi connected\n");
          g_wifi_connected = true;
          g_cloud_status.wifi_status = CLOUD_STATUS_CONNECTED;

          /* 获取 IP 地址 */
          esp32_send_command(AT_CMD_IP_STATUS, response, sizeof(response));
          /* 解析 IP 地址（简化实现） */
          char *ip_start = strstr(response, "\"");
          if (ip_start)
            {
              ip_start++;
              char *ip_end = strstr(ip_start, "\"");
              if (ip_end)
                {
                  size_t ip_len = ip_end - ip_start;
                  if (ip_len < sizeof(g_cloud_status.ip_address))
                    {
                      strncpy(g_cloud_status.ip_address, ip_start, ip_len);
                      g_cloud_status.ip_address[ip_len] = '\0';
                      board_info("Cloud: IP Address: %s\n", g_cloud_status.ip_address);
                    }
                }
            }

          g_cloud_status.internet_available = true;
          return OK;
        }
      else
        {
          board_err("Cloud: WiFi connection failed\n");
          g_cloud_status.wifi_status = CLOUD_STATUS_ERROR;
          return -ECONNREFUSED;
        }
    }
#endif

  /* 如果没有 UART2，使用模拟数据 */
  board_warn("Cloud: UART2 not available, using simulated WiFi\n");
  g_wifi_connected = true;
  g_cloud_status.wifi_status = CLOUD_STATUS_CONNECTED;
  strcpy(g_cloud_status.ip_address, "192.168.1.100");
  g_cloud_status.internet_available = true;

  return OK;
}
```

