/* ESP32 AT 指令 */
#define AT_CMD_TEST         "AT\r\n"
#define AT_CMD_RESET        "AT+RST\r\n"
#define AT_CMD_WIFI_MODE    "AT+CWMODE=1\r\n"
#define AT_CMD_WIFI_JOIN    "AT+CWJAP=\"%s\",\"%s\"\r\n"
#define AT_CMD_IP_STATUS    "AT+CIFSR\r\n"
#define AT_CMD_HTTPS_START  "AT+HTTPCLIENT=\"https://%s\",4\r\n"

/* 响应缓冲区大小 */
#define AT_RESPONSE_SIZE    512
#define HTTP_RESPONSE_SIZE  4096

/* JSON 缓冲区大小 */
#define JSON_BUFFER_SIZE    2048

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct cloud_status_s g_cloud_status;
static bool g_cloud_initialized = false;
static bool g_wifi_connected = false;

/* UART2 句柄 */
static int g_uart2_fd = -1;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

#ifdef CONFIG_USART2
/****************************************************************************
 * Name: esp32_send_command
 *
 * Description:
 *   发送 AT 指令到 ESP32
 *
 ****************************************************************************/

static int esp32_send_command(const char *cmd, char *response, size_t response_size)
{
  if (g_uart2_fd < 0)
    {
      return -ENODEV;
    }

  /* 清空响应缓冲区 */
  memset(response, 0, response_size);

  /* 发送指令 */
  size_t cmd_len = strlen(cmd);
  ssize_t written = write(g_uart2_fd, cmd, cmd_len);
  if (written != cmd_len)
    {
      board_err("Cloud: Failed to send AT command\n");
      return -EIO;
    }

